var files = [{"name":"sys_script_include_aeab153d89134770a6c0ef4fddfad5f8.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>aeab153d89134770a6c0ef4fddfad5f8</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_aeab153d89134770a6c0ef4fddfad5f8</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.FinancePolicy</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Reads the configurable BCFA finance policy (AI provider, AP tolerances, confidence threshold, approval rule, exception severity/SLA/assignment, override rules) from x_695068_bcfa.* system properties. Values are POC ASSUMPTIONS.</description>\n    <mobile_callable>false</mobile_callable>\n    <name>FinancePolicy</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[// Single read point for the configurable BCFA finance policy (Phase 12).\r\n// Every value comes from an x_695068_bcfa.* system property (see\r\n// src/fluent/config/policy_properties.now.ts). The initial values are\r\n// synthetic POC ASSUMPTIONS, not Birla Carbon production rules. The\r\n// defaults below apply only when a property is missing or unparsable, so\r\n// a bad edit can never switch a control off.\r\nvar FinancePolicy = Class.create();\r\n\r\nFinancePolicy.PREFIX = 'x_695068_bcfa.';\r\n\r\nFinancePolicy.DEFAULTS = {\r\n    'ai.provider': 'native',\r\n    'ap.tolerance.quantity_pct': 0.02,\r\n    'ap.tolerance.price_pct': 0.02,\r\n    'ap.tolerance.tax_absolute': 1,\r\n    'ap.tolerance.tax_relative_pct': 0.02,\r\n    'ap.extraction.confidence_threshold': 0.85,\r\n    'ap.approval.auto_approve_limit': 0,\r\n    'ap.exception.high_value_variance': 1000,\r\n    'ap.exception.sla_hours': '{\"critical\":4,\"high\":8,\"medium\":24,\"low\":72}',\r\n    'ap.exception.assignment_group': '',\r\n    'ap.exception.default_owner': '',\r\n    'ap.override.allowed_reasons': 'quantity_tolerance,price_tolerance,tax_validation',\r\n    'ar.approval.auto_approve_limit': 0,\r\n    'ar.match.auto_confidence': 0.95,\r\n    'ar.deduction.approval_threshold': 5000,\r\n    'ar.deduction.allowed_types': 'bank_charge,tcs,short_pay,credit_note_netting',\r\n    'ar.bank_charge.max_amount': 1000,\r\n    'ar.exception.high_value_residual': 5000,\r\n    'ar.exception.sla_hours': '{\"critical\":4,\"high\":8,\"medium\":24,\"low\":72}',\r\n    'ar.exception.assignment_group': '',\r\n    'ar.exception.default_owner': ''\r\n};\r\n\r\n// Base severity per AR exception reason. Short and over payments are\r\n// raised to high when the residual reaches ar.exception.high_value_residual.\r\nFinancePolicy.AR_BASE_SEVERITY = {\r\n    unmatched: 'medium',\r\n    customer_ambiguous: 'medium',\r\n    short_pay: 'medium',\r\n    over_pay: 'medium',\r\n    duplicate: 'high',\r\n    currency_mismatch: 'high',\r\n    other: 'medium'\r\n};\r\n\r\n// Base severity per AP exception reason. Tolerance failures are raised to\r\n// high when the variance value reaches ap.exception.high_value_variance.\r\nFinancePolicy.AP_BASE_SEVERITY = {\r\n    duplicate: 'high',\r\n    po_mismatch: 'high',\r\n    vendor_invalid: 'high',\r\n    quantity_tolerance: 'medium',\r\n    price_tolerance: 'medium',\r\n    tax_validation: 'medium',\r\n    low_confidence: 'medium',\r\n    missing_field: 'medium',\r\n    other: 'medium'\r\n};\r\n\r\n// Phase 15: native Decision Tables (Decision Builder) hold the policy that\r\n// depends on several inputs. They are created through the supported\r\n// sn_dt Decision Table API (scripts/deploy/phase15_decision_tables_bg.js),\r\n// found by name in the app scope and evaluated with sn_dt.DecisionTableAPI.\r\n// If a table is missing, returns no row, or cannot be read, the matching\r\n// x_695068_bcfa.* properties apply instead, so a control is never off.\r\nFinancePolicy.APP_SCOPE = '229ba2b1a079431e104010f5ea883e85';\r\nFinancePolicy.DECISION_TABLES = {\r\n    apTolerance: 'BCFA AP Tolerance',\r\n    apApproval: 'BCFA AP Approval',\r\n    arDeduction: 'BCFA AR Deduction'\r\n};\r\n// Fallback approval group when no decision table row applies.\r\nFinancePolicy.DEFAULT_APPROVAL_GROUP = 'e34ee8a159fd504893d4fc248a6632a7'; // BCFA Finance Approvers\r\n\r\nFinancePolicy.prototype = {\r\n    initialize: function() {\r\n        this._tableIds = {};\r\n    },\r\n\r\n    // ---- Decision tables ---------------------------------------------------\r\n\r\n    // Evaluates a BCFA decision table. Returns { source:'decision_table',\r\n    // table, values:{output: value} } for the first matching row, or null\r\n    // (no table, no row, or an error) so the caller uses its property\r\n    // fallback.\r\n    decide: function(tableKey, inputs, outputs) {\r\n        var tableId = this._decisionTableId(tableKey);\r\n        if (!tableId) return null;\r\n        try {\r\n            var answer = new sn_dt.DecisionTableAPI().getDecision(tableId, inputs);\r\n            if (!answer || (answer.isValidRecord && !answer.isValidRecord())) return null;\r\n            var values = {};\r\n            for (var i = 0; i < outputs.length; i++) {\r\n                var value = this._answerValue(answer, outputs[i]);\r\n                if (value === null || value === undefined || value === '') return null;\r\n                values[outputs[i]] = value;\r\n            }\r\n            return { source: 'decision_table', table: FinancePolicy.DECISION_TABLES[tableKey], answer: answer.getDisplayValue(), values: values };\r\n        } catch (e) {\r\n            gs.warn('BCFA FinancePolicy: decision table ' + FinancePolicy.DECISION_TABLES[tableKey] + ' could not be evaluated, using properties: ' + e);\r\n            return null;\r\n        }\r\n    },\r\n\r\n    _decisionTableId: function(tableKey) {\r\n        if (this._tableIds.hasOwnProperty(tableKey)) return this._tableIds[tableKey];\r\n        var table = new GlideRecord('sys_decision');\r\n        table.addQuery('name', FinancePolicy.DECISION_TABLES[tableKey]);\r\n        table.addQuery('sys_scope', FinancePolicy.APP_SCOPE);\r\n        table.addQuery('active', true);\r\n        table.setLimit(1);\r\n        table.query();\r\n        this._tableIds[tableKey] = table.next() ? table.getUniqueValue() : null;\r\n        return this._tableIds[tableKey];\r\n    },\r\n\r\n    // Reads one result value of a multi-result answer: through the answer's\r\n    // result elements, else from the stored variable value.\r\n    _answerValue: function(answer, name) {\r\n        try {\r\n            if (answer.result_elements && answer.result_elements[name] !== undefined && answer.result_elements[name] !== null) {\r\n                var direct = String(answer.result_elements[name]);\r\n                if (direct !== '' && direct !== 'undefined') return direct;\r\n            }\r\n        } catch (e) {\r\n            // fall through to the stored value\r\n        }\r\n        var stored = new GlideRecord('sys_variable_value');\r\n        stored.addQuery('document', 'sys_decision_multi_result');\r\n        stored.addQuery('document_key', answer.getUniqueValue());\r\n        stored.addQuery('variable.element', name);\r\n        stored.setLimit(1);\r\n        stored.query();\r\n        return stored.next() ? stored.getValue('value') : null;\r\n    },\r\n\r\n    _bool: function(value) {\r\n        return value === true || value === 'true' || value === '1';\r\n    },\r\n\r\n    // 'native' (ServiceNow AI: Now Assist skills/agents, simulated document\r\n    // extraction until DocIntel extraction is licensed), 'claude' (legacy,\r\n    // removed in Phase 34) or 'simulated' (deterministic templates only).\r\n    aiProvider: function() {\r\n        var value = this._string('ai.provider');\r\n        return value === 'claude' || value === 'simulated' ? value : 'native';\r\n    },\r\n\r\n    // context (optional): { company, country, vendorType, invoiceType }.\r\n    // With a context the BCFA AP Tolerance decision table decides; the\r\n    // x_695068_bcfa.ap.tolerance.* properties are the fallback.\r\n    apTolerances: function(context) {\r\n        var fallback = {\r\n            quantityPct: this._number('ap.tolerance.quantity_pct'),\r\n            pricePct: this._number('ap.tolerance.price_pct'),\r\n            taxAbsolute: this._number('ap.tolerance.tax_absolute'),\r\n            taxRelativePct: this._number('ap.tolerance.tax_relative_pct'),\r\n            source: 'properties'\r\n        };\r\n        if (!context) return fallback;\r\n        var decision = this.decide('apTolerance', {\r\n            company: context.company || '', country: context.country || '',\r\n            vendor_type: context.vendorType || 'standard', invoice_type: context.invoiceType || 'po'\r\n        }, ['quantity_tolerance_pct', 'price_tolerance_pct', 'tax_tolerance_abs', 'tax_tolerance_pct']);\r\n        if (!decision) return fallback;\r\n        var values = {\r\n            quantityPct: parseFloat(decision.values.quantity_tolerance_pct),\r\n            pricePct: parseFloat(decision.values.price_tolerance_pct),\r\n            taxAbsolute: parseFloat(decision.values.tax_tolerance_abs),\r\n            taxRelativePct: parseFloat(decision.values.tax_tolerance_pct),\r\n            source: 'decision table ' + decision.table + ' (' + decision.answer + ')'\r\n        };\r\n        for (var k in values) {\r\n            if (k !== 'source' && (isNaN(values[k]) || values[k] < 0)) return fallback;\r\n        }\r\n        return values;\r\n    },\r\n\r\n    // BCFA AP Approval decision table: context { amount, exceptionType\r\n    // ('none' for a clean invoice), variancePct (percent), company }.\r\n    // Returns { required, group, rule, source }.\r\n    apApprovalDecision: function(context) {\r\n        var decision = this.decide('apApproval', {\r\n            amount: context.amount || 0, exception_type: context.exceptionType || 'none',\r\n            variance_pct: context.variancePct || 0, company: context.company || ''\r\n        }, ['approval_required', 'approval_group']);\r\n        if (decision) {\r\n            var required = this._bool(decision.values.approval_required);\r\n            return { required: required, group: decision.values.approval_group, source: 'decision table ' + decision.table,\r\n                rule: (required ? 'Approval required' : 'No approval required') + ' by decision table ' + decision.table + ' (' + decision.answer + ') for amount ' +\r\n                    context.amount + ', exception ' + (context.exceptionType || 'none') + ', variance ' + (context.variancePct || 0) + '%.' };\r\n        }\r\n        var fallback = this.apApprovalRule(context.amount);\r\n        fallback.group = FinancePolicy.DEFAULT_APPROVAL_GROUP;\r\n        fallback.source = 'properties';\r\n        return fallback;\r\n    },\r\n\r\n    // BCFA AR Deduction decision table: context { deductionType, amount,\r\n    // company }. Returns { allowed, approvalRequired, group, rule, source }.\r\n    arDeductionDecision: function(context) {\r\n        var decision = this.decide('arDeduction', {\r\n            deduction_type: context.deductionType || '', amount: context.amount || 0, company: context.company || ''\r\n        }, ['allowed', 'approval_required', 'approval_group']);\r\n        if (decision) {\r\n            return {\r\n                allowed: this._bool(decision.values.allowed),\r\n                approvalRequired: this._bool(decision.values.approval_required),\r\n                group: decision.values.approval_group,\r\n                source: 'decision table ' + decision.table,\r\n                rule: 'Decision table ' + decision.table + ' (' + decision.answer + ') for ' + context.deductionType + ' ' + context.amount + '.'\r\n            };\r\n        }\r\n        var threshold = this.arDeductionApprovalThreshold();\r\n        return {\r\n            allowed: this.arDeductionTypeAllowed(context.deductionType),\r\n            approvalRequired: parseFloat(context.amount || '0') > threshold,\r\n            group: FinancePolicy.DEFAULT_APPROVAL_GROUP,\r\n            source: 'properties',\r\n            rule: 'Properties: allowed types ' + this._string('ar.deduction.allowed_types') + ', finance approver above ' + threshold + '.'\r\n        };\r\n    },\r\n\r\n    extractionConfidenceThreshold: function() {\r\n        return this._number('ap.extraction.confidence_threshold');\r\n    },\r\n\r\n    // Approval is required unless the gross amount is at or below the\r\n    // configured auto-approve limit. The POC default limit is 0, so every\r\n    // invoice goes to a human approver.\r\n    apApprovalRule: function(grossAmount) {\r\n        var limit = this._number('ap.approval.auto_approve_limit');\r\n        var amount = parseFloat(grossAmount || '0');\r\n        var required = !(limit > 0 && amount <= limit);\r\n        return {\r\n            required: required,\r\n            limit: limit,\r\n            rule: required\r\n                ? 'Human approval required: gross ' + amount + (limit > 0 ? ' exceeds the auto-approve limit ' + limit : ' (auto-approve limit is 0, so every invoice needs approval)') + '.'\r\n                : 'No approval required: gross ' + amount + ' is within the auto-approve limit ' + limit + '.'\r\n        };\r\n    },\r\n\r\n    apExceptionSeverity: function(reasonCode, varianceAmount) {\r\n        var severity = FinancePolicy.AP_BASE_SEVERITY[reasonCode] || 'medium';\r\n        var tolerance = reasonCode === 'quantity_tolerance' || reasonCode === 'price_tolerance' || reasonCode === 'tax_validation';\r\n        if (tolerance && Math.abs(parseFloat(varianceAmount || '0')) >= this._number('ap.exception.high_value_variance')) {\r\n            severity = 'high';\r\n        }\r\n        return severity;\r\n    },\r\n\r\n    // Returns a GlideDateTime for the SLA due date of a new exception.\r\n    apExceptionDueDate: function(severity) {\r\n        return this._dueDate('ap.exception.sla_hours', severity);\r\n    },\r\n\r\n    // ---- AR (Phase 13) ----------------------------------------------------\r\n\r\n    arApprovalRule: function(amount) {\r\n        var limit = this._number('ar.approval.auto_approve_limit');\r\n        var value = parseFloat(amount || '0');\r\n        var required = !(limit > 0 && value <= limit);\r\n        return {\r\n            required: required,\r\n            limit: limit,\r\n            rule: required\r\n                ? 'Human approval required: payment ' + value + (limit > 0 ? ' exceeds the auto-approve limit ' + limit : ' (auto-approve limit is 0, so every clearing needs approval)') + '.'\r\n                : 'No approval required: payment ' + value + ' is within the auto-approve limit ' + limit + '.'\r\n        };\r\n    },\r\n\r\n    // Minimum confidence for resolving a customer automatically from an\r\n    // alias; below it the payment goes to a human as customer_ambiguous.\r\n    arAutoMatchConfidence: function() {\r\n        return this._number('ar.match.auto_confidence');\r\n    },\r\n\r\n    // Deductions above this amount need a finance approver to accept them.\r\n    arDeductionApprovalThreshold: function() {\r\n        return this._number('ar.deduction.approval_threshold');\r\n    },\r\n\r\n    // Largest short-pay residual the matching engine suggests as a bank\r\n    // charge (a suggestion only; the reviewer confirms).\r\n    arBankChargeMax: function() {\r\n        return this._number('ar.bank_charge.max_amount');\r\n    },\r\n\r\n    arDeductionTypeAllowed: function(type) {\r\n        return this._inList('ar.deduction.allowed_types', type);\r\n    },\r\n\r\n    arExceptionSeverity: function(reasonCode, residual) {\r\n        var severity = FinancePolicy.AR_BASE_SEVERITY[reasonCode] || 'medium';\r\n        if ((reasonCode === 'short_pay' || reasonCode === 'over_pay') &&\r\n            Math.abs(parseFloat(residual || '0')) >= this._number('ar.exception.high_value_residual')) {\r\n            severity = 'high';\r\n        }\r\n        return severity;\r\n    },\r\n\r\n    arExceptionDueDate: function(severity) {\r\n        return this._dueDate('ar.exception.sla_hours', severity);\r\n    },\r\n\r\n    arExceptionAssignmentGroup: function() {\r\n        return this._string('ar.exception.assignment_group');\r\n    },\r\n\r\n    arExceptionDefaultOwner: function() {\r\n        return this._string('ar.exception.default_owner');\r\n    },\r\n\r\n    _dueDate: function(key, severity) {\r\n        var hours = 24;\r\n        try {\r\n            var table = JSON.parse(this._string(key));\r\n            if (table && table[severity] > 0) hours = table[severity];\r\n        } catch (e) {\r\n            // Unparsable property: keep the 24h default.\r\n        }\r\n        var due = new GlideDateTime();\r\n        due.addSeconds(Math.round(hours * 3600));\r\n        return due;\r\n    },\r\n\r\n    _inList: function(key, value) {\r\n        var allowed = this._string(key).split(',');\r\n        for (var i = 0; i < allowed.length; i++) {\r\n            if (allowed[i].trim() === value) return true;\r\n        }\r\n        return false;\r\n    },\r\n\r\n    apExceptionAssignmentGroup: function() {\r\n        return this._string('ap.exception.assignment_group');\r\n    },\r\n\r\n    apExceptionDefaultOwner: function() {\r\n        return this._string('ap.exception.default_owner');\r\n    },\r\n\r\n    overrideAllowed: function(reasonCode) {\r\n        return this._inList('ap.override.allowed_reasons', reasonCode);\r\n    },\r\n\r\n    _string: function(key) {\r\n        var value = gs.getProperty(FinancePolicy.PREFIX + key);\r\n        if (value === null || value === undefined || String(value).trim() === '') return String(FinancePolicy.DEFAULTS[key]);\r\n        return String(value).trim();\r\n    },\r\n\r\n    _number: function(key) {\r\n        var value = parseFloat(gs.getProperty(FinancePolicy.PREFIX + key));\r\n        return isNaN(value) ? FinancePolicy.DEFAULTS[key] : value;\r\n    },\r\n\r\n    type: 'FinancePolicy'\r\n};\r\n]]></script>\n    <sys_name>FinancePolicy</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_a662cc88c9234f3083a63532043a48e0.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>a662cc88c9234f3083a63532043a48e0</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_a662cc88c9234f3083a63532043a48e0</sys_update_name>\n    <content><![CDATA[// Single read point for the configurable BCFA finance policy (Phase 12).\r\n// Every value comes from an x_695068_bcfa.* system property (see\r\n// src/fluent/config/policy_properties.now.ts). The initial values are\r\n// synthetic POC ASSUMPTIONS, not Birla Carbon production rules. The\r\n// defaults below apply only when a property is missing or unparsable, so\r\n// a bad edit can never switch a control off.\r\nvar FinancePolicy = Class.create();\r\n\r\nFinancePolicy.PREFIX = 'x_695068_bcfa.';\r\n\r\nFinancePolicy.DEFAULTS = {\r\n    'ai.provider': 'native',\r\n    'ap.tolerance.quantity_pct': 0.02,\r\n    'ap.tolerance.price_pct': 0.02,\r\n    'ap.tolerance.tax_absolute': 1,\r\n    'ap.tolerance.tax_relative_pct': 0.02,\r\n    'ap.extraction.confidence_threshold': 0.85,\r\n    'ap.approval.auto_approve_limit': 0,\r\n    'ap.exception.high_value_variance': 1000,\r\n    'ap.exception.sla_hours': '{\"critical\":4,\"high\":8,\"medium\":24,\"low\":72}',\r\n    'ap.exception.assignment_group': '',\r\n    'ap.exception.default_owner': '',\r\n    'ap.override.allowed_reasons': 'quantity_tolerance,price_tolerance,tax_validation',\r\n    'ar.approval.auto_approve_limit': 0,\r\n    'ar.match.auto_confidence': 0.95,\r\n    'ar.deduction.approval_threshold': 5000,\r\n    'ar.deduction.allowed_types': 'bank_charge,tcs,short_pay,credit_note_netting',\r\n    'ar.bank_charge.max_amount': 1000,\r\n    'ar.exception.high_value_residual': 5000,\r\n    'ar.exception.sla_hours': '{\"critical\":4,\"high\":8,\"medium\":24,\"low\":72}',\r\n    'ar.exception.assignment_group': '',\r\n    'ar.exception.default_owner': ''\r\n};\r\n\r\n// Base severity per AR exception reason. Short and over payments are\r\n// raised to high when the residual reaches ar.exception.high_value_residual.\r\nFinancePolicy.AR_BASE_SEVERITY = {\r\n    unmatched: 'medium',\r\n    customer_ambiguous: 'medium',\r\n    short_pay: 'medium',\r\n    over_pay: 'medium',\r\n    duplicate: 'high',\r\n    currency_mismatch: 'high',\r\n    other: 'medium'\r\n};\r\n\r\n// Base severity per AP exception reason. Tolerance failures are raised to\r\n// high when the variance value reaches ap.exception.high_value_variance.\r\nFinancePolicy.AP_BASE_SEVERITY = {\r\n    duplicate: 'high',\r\n    po_mismatch: 'high',\r\n    vendor_invalid: 'high',\r\n    quantity_tolerance: 'medium',\r\n    price_tolerance: 'medium',\r\n    tax_validation: 'medium',\r\n    low_confidence: 'medium',\r\n    missing_field: 'medium',\r\n    other: 'medium'\r\n};\r\n\r\n// Phase 15: native Decision Tables (Decision Builder) hold the policy that\r\n// depends on several inputs. They are created through the supported\r\n// sn_dt Decision Table API (scripts/deploy/phase15_decision_tables_bg.js),\r\n// found by name in the app scope and evaluated with sn_dt.DecisionTableAPI.\r\n// If a table is missing, returns no row, or cannot be read, the matching\r\n// x_695068_bcfa.* properties apply instead, so a control is never off.\r\nFinancePolicy.APP_SCOPE = '229ba2b1a079431e104010f5ea883e85';\r\nFinancePolicy.DECISION_TABLES = {\r\n    apTolerance: 'BCFA AP Tolerance',\r\n    apApproval: 'BCFA AP Approval',\r\n    arDeduction: 'BCFA AR Deduction'\r\n};\r\n// Fallback approval group when no decision table row applies.\r\nFinancePolicy.DEFAULT_APPROVAL_GROUP = 'e34ee8a159fd504893d4fc248a6632a7'; // BCFA Finance Approvers\r\n\r\nFinancePolicy.prototype = {\r\n    initialize: function() {\r\n        this._tableIds = {};\r\n    },\r\n\r\n    // ---- Decision tables ---------------------------------------------------\r\n\r\n    // Evaluates a BCFA decision table. Returns { source:'decision_table',\r\n    // table, values:{output: value} } for the first matching row, or null\r\n    // (no table, no row, or an error) so the caller uses its property\r\n    // fallback.\r\n    decide: function(tableKey, inputs, outputs) {\r\n        var tableId = this._decisionTableId(tableKey);\r\n        if (!tableId) return null;\r\n        try {\r\n            var answer = new sn_dt.DecisionTableAPI().getDecision(tableId, inputs);\r\n            if (!answer || (answer.isValidRecord && !answer.isValidRecord())) return null;\r\n            var values = {};\r\n            for (var i = 0; i < outputs.length; i++) {\r\n                var value = this._answerValue(answer, outputs[i]);\r\n                if (value === null || value === undefined || value === '') return null;\r\n                values[outputs[i]] = value;\r\n            }\r\n            return { source: 'decision_table', table: FinancePolicy.DECISION_TABLES[tableKey], answer: answer.getDisplayValue(), values: values };\r\n        } catch (e) {\r\n            gs.warn('BCFA FinancePolicy: decision table ' + FinancePolicy.DECISION_TABLES[tableKey] + ' could not be evaluated, using properties: ' + e);\r\n            return null;\r\n        }\r\n    },\r\n\r\n    _decisionTableId: function(tableKey) {\r\n        if (this._tableIds.hasOwnProperty(tableKey)) return this._tableIds[tableKey];\r\n        var table = new GlideRecord('sys_decision');\r\n        table.addQuery('name', FinancePolicy.DECISION_TABLES[tableKey]);\r\n        table.addQuery('sys_scope', FinancePolicy.APP_SCOPE);\r\n        table.addQuery('active', true);\r\n        table.setLimit(1);\r\n        table.query();\r\n        this._tableIds[tableKey] = table.next() ? table.getUniqueValue() : null;\r\n        return this._tableIds[tableKey];\r\n    },\r\n\r\n    // Reads one result value of a multi-result answer: through the answer's\r\n    // result elements, else from the stored variable value.\r\n    _answerValue: function(answer, name) {\r\n        try {\r\n            if (answer.result_elements && answer.result_elements[name] !== undefined && answer.result_elements[name] !== null) {\r\n                var direct = String(answer.result_elements[name]);\r\n                if (direct !== '' && direct !== 'undefined') return direct;\r\n            }\r\n        } catch (e) {\r\n            // fall through to the stored value\r\n        }\r\n        var stored = new GlideRecord('sys_variable_value');\r\n        stored.addQuery('document', 'sys_decision_multi_result');\r\n        stored.addQuery('document_key', answer.getUniqueValue());\r\n        stored.addQuery('variable.element', name);\r\n        stored.setLimit(1);\r\n        stored.query();\r\n        return stored.next() ? stored.getValue('value') : null;\r\n    },\r\n\r\n    _bool: function(value) {\r\n        return value === true || value === 'true' || value === '1';\r\n    },\r\n\r\n    // 'native' (ServiceNow AI: Now Assist skills/agents, simulated document\r\n    // extraction until DocIntel extraction is licensed), 'claude' (legacy,\r\n    // removed in Phase 34) or 'simulated' (deterministic templates only).\r\n    aiProvider: function() {\r\n        var value = this._string('ai.provider');\r\n        return value === 'claude' || value === 'simulated' ? value : 'native';\r\n    },\r\n\r\n    // context (optional): { company, country, vendorType, invoiceType }.\r\n    // With a context the BCFA AP Tolerance decision table decides; the\r\n    // x_695068_bcfa.ap.tolerance.* properties are the fallback.\r\n    apTolerances: function(context) {\r\n        var fallback = {\r\n            quantityPct: this._number('ap.tolerance.quantity_pct'),\r\n            pricePct: this._number('ap.tolerance.price_pct'),\r\n            taxAbsolute: this._number('ap.tolerance.tax_absolute'),\r\n            taxRelativePct: this._number('ap.tolerance.tax_relative_pct'),\r\n            source: 'properties'\r\n        };\r\n        if (!context) return fallback;\r\n        var decision = this.decide('apTolerance', {\r\n            company: context.company || '', country: context.country || '',\r\n            vendor_type: context.vendorType || 'standard', invoice_type: context.invoiceType || 'po'\r\n        }, ['quantity_tolerance_pct', 'price_tolerance_pct', 'tax_tolerance_abs', 'tax_tolerance_pct']);\r\n        if (!decision) return fallback;\r\n        var values = {\r\n            quantityPct: parseFloat(decision.values.quantity_tolerance_pct),\r\n            pricePct: parseFloat(decision.values.price_tolerance_pct),\r\n            taxAbsolute: parseFloat(decision.values.tax_tolerance_abs),\r\n            taxRelativePct: parseFloat(decision.values.tax_tolerance_pct),\r\n            source: 'decision table ' + decision.table + ' (' + decision.answer + ')'\r\n        };\r\n        for (var k in values) {\r\n            if (k !== 'source' && (isNaN(values[k]) || values[k] < 0)) return fallback;\r\n        }\r\n        return values;\r\n    },\r\n\r\n    // BCFA AP Approval decision table: context { amount, exceptionType\r\n    // ('none' for a clean invoice), variancePct (percent), company }.\r\n    // Returns { required, group, rule, source }.\r\n    apApprovalDecision: function(context) {\r\n        var decision = this.decide('apApproval', {\r\n            amount: context.amount || 0, exception_type: context.exceptionType || 'none',\r\n            variance_pct: context.variancePct || 0, company: context.company || ''\r\n        }, ['approval_required', 'approval_group']);\r\n        if (decision) {\r\n            var required = this._bool(decision.values.approval_required);\r\n            return { required: required, group: decision.values.approval_group, source: 'decision table ' + decision.table,\r\n                rule: (required ? 'Approval required' : 'No approval required') + ' by decision table ' + decision.table + ' (' + decision.answer + ') for amount ' +\r\n                    context.amount + ', exception ' + (context.exceptionType || 'none') + ', variance ' + (context.variancePct || 0) + '%.' };\r\n        }\r\n        var fallback = this.apApprovalRule(context.amount);\r\n        fallback.group = FinancePolicy.DEFAULT_APPROVAL_GROUP;\r\n        fallback.source = 'properties';\r\n        return fallback;\r\n    },\r\n\r\n    // BCFA AR Deduction decision table: context { deductionType, amount,\r\n    // company }. Returns { allowed, approvalRequired, group, rule, source }.\r\n    arDeductionDecision: function(context) {\r\n        var decision = this.decide('arDeduction', {\r\n            deduction_type: context.deductionType || '', amount: context.amount || 0, company: context.company || ''\r\n        }, ['allowed', 'approval_required', 'approval_group']);\r\n        if (decision) {\r\n            return {\r\n                allowed: this._bool(decision.values.allowed),\r\n                approvalRequired: this._bool(decision.values.approval_required),\r\n                group: decision.values.approval_group,\r\n                source: 'decision table ' + decision.table,\r\n                rule: 'Decision table ' + decision.table + ' (' + decision.answer + ') for ' + context.deductionType + ' ' + context.amount + '.'\r\n            };\r\n        }\r\n        var threshold = this.arDeductionApprovalThreshold();\r\n        return {\r\n            allowed: this.arDeductionTypeAllowed(context.deductionType),\r\n            approvalRequired: parseFloat(context.amount || '0') > threshold,\r\n            group: FinancePolicy.DEFAULT_APPROVAL_GROUP,\r\n            source: 'properties',\r\n            rule: 'Properties: allowed types ' + this._string('ar.deduction.allowed_types') + ', finance approver above ' + threshold + '.'\r\n        };\r\n    },\r\n\r\n    extractionConfidenceThreshold: function() {\r\n        return this._number('ap.extraction.confidence_threshold');\r\n    },\r\n\r\n    // Approval is required unless the gross amount is at or below the\r\n    // configured auto-approve limit. The POC default limit is 0, so every\r\n    // invoice goes to a human approver.\r\n    apApprovalRule: function(grossAmount) {\r\n        var limit = this._number('ap.approval.auto_approve_limit');\r\n        var amount = parseFloat(grossAmount || '0');\r\n        var required = !(limit > 0 && amount <= limit);\r\n        return {\r\n            required: required,\r\n            limit: limit,\r\n            rule: required\r\n                ? 'Human approval required: gross ' + amount + (limit > 0 ? ' exceeds the auto-approve limit ' + limit : ' (auto-approve limit is 0, so every invoice needs approval)') + '.'\r\n                : 'No approval required: gross ' + amount + ' is within the auto-approve limit ' + limit + '.'\r\n        };\r\n    },\r\n\r\n    apExceptionSeverity: function(reasonCode, varianceAmount) {\r\n        var severity = FinancePolicy.AP_BASE_SEVERITY[reasonCode] || 'medium';\r\n        var tolerance = reasonCode === 'quantity_tolerance' || reasonCode === 'price_tolerance' || reasonCode === 'tax_validation';\r\n        if (tolerance && Math.abs(parseFloat(varianceAmount || '0')) >= this._number('ap.exception.high_value_variance')) {\r\n            severity = 'high';\r\n        }\r\n        return severity;\r\n    },\r\n\r\n    // Returns a GlideDateTime for the SLA due date of a new exception.\r\n    apExceptionDueDate: function(severity) {\r\n        return this._dueDate('ap.exception.sla_hours', severity);\r\n    },\r\n\r\n    // ---- AR (Phase 13) ----------------------------------------------------\r\n\r\n    arApprovalRule: function(amount) {\r\n        var limit = this._number('ar.approval.auto_approve_limit');\r\n        var value = parseFloat(amount || '0');\r\n        var required = !(limit > 0 && value <= limit);\r\n        return {\r\n            required: required,\r\n            limit: limit,\r\n            rule: required\r\n                ? 'Human approval required: payment ' + value + (limit > 0 ? ' exceeds the auto-approve limit ' + limit : ' (auto-approve limit is 0, so every clearing needs approval)') + '.'\r\n                : 'No approval required: payment ' + value + ' is within the auto-approve limit ' + limit + '.'\r\n        };\r\n    },\r\n\r\n    // Minimum confidence for resolving a customer automatically from an\r\n    // alias; below it the payment goes to a human as customer_ambiguous.\r\n    arAutoMatchConfidence: function() {\r\n        return this._number('ar.match.auto_confidence');\r\n    },\r\n\r\n    // Deductions above this amount need a finance approver to accept them.\r\n    arDeductionApprovalThreshold: function() {\r\n        return this._number('ar.deduction.approval_threshold');\r\n    },\r\n\r\n    // Largest short-pay residual the matching engine suggests as a bank\r\n    // charge (a suggestion only; the reviewer confirms).\r\n    arBankChargeMax: function() {\r\n        return this._number('ar.bank_charge.max_amount');\r\n    },\r\n\r\n    arDeductionTypeAllowed: function(type) {\r\n        return this._inList('ar.deduction.allowed_types', type);\r\n    },\r\n\r\n    arExceptionSeverity: function(reasonCode, residual) {\r\n        var severity = FinancePolicy.AR_BASE_SEVERITY[reasonCode] || 'medium';\r\n        if ((reasonCode === 'short_pay' || reasonCode === 'over_pay') &&\r\n            Math.abs(parseFloat(residual || '0')) >= this._number('ar.exception.high_value_residual')) {\r\n            severity = 'high';\r\n        }\r\n        return severity;\r\n    },\r\n\r\n    arExceptionDueDate: function(severity) {\r\n        return this._dueDate('ar.exception.sla_hours', severity);\r\n    },\r\n\r\n    arExceptionAssignmentGroup: function() {\r\n        return this._string('ar.exception.assignment_group');\r\n    },\r\n\r\n    arExceptionDefaultOwner: function() {\r\n        return this._string('ar.exception.default_owner');\r\n    },\r\n\r\n    _dueDate: function(key, severity) {\r\n        var hours = 24;\r\n        try {\r\n            var table = JSON.parse(this._string(key));\r\n            if (table && table[severity] > 0) hours = table[severity];\r\n        } catch (e) {\r\n            // Unparsable property: keep the 24h default.\r\n        }\r\n        var due = new GlideDateTime();\r\n        due.addSeconds(Math.round(hours * 3600));\r\n        return due;\r\n    },\r\n\r\n    _inList: function(key, value) {\r\n        var allowed = this._string(key).split(',');\r\n        for (var i = 0; i < allowed.length; i++) {\r\n            if (allowed[i].trim() === value) return true;\r\n        }\r\n        return false;\r\n    },\r\n\r\n    apExceptionAssignmentGroup: function() {\r\n        return this._string('ap.exception.assignment_group');\r\n    },\r\n\r\n    apExceptionDefaultOwner: function() {\r\n        return this._string('ap.exception.default_owner');\r\n    },\r\n\r\n    overrideAllowed: function(reasonCode) {\r\n        return this._inList('ap.override.allowed_reasons', reasonCode);\r\n    },\r\n\r\n    _string: function(key) {\r\n        var value = gs.getProperty(FinancePolicy.PREFIX + key);\r\n        if (value === null || value === undefined || String(value).trim() === '') return String(FinancePolicy.DEFAULTS[key]);\r\n        return String(value).trim();\r\n    },\r\n\r\n    _number: function(key) {\r\n        var value = parseFloat(gs.getProperty(FinancePolicy.PREFIX + key));\r\n        return isNaN(value) ? FinancePolicy.DEFAULTS[key] : value;\r\n    },\r\n\r\n    type: 'FinancePolicy'\r\n};\r\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/FinancePolicy.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/FinancePolicy.server.js</sys_name>\n  </sys_module>\n</record_update>"},{"name":"sys_script_include_1c5d6ab209d349538f1cc7c9f33aca6e.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>1c5d6ab209d349538f1cc7c9f33aca6e</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_1c5d6ab209d349538f1cc7c9f33aca6e</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.MatchingEngine</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Deterministic AP 3-way match, duplicate detection, and AR exact/multi-invoice matching + customer alias resolution. Pure functions over deterministic tolerances.</description>\n    <mobile_callable>false</mobile_callable>\n    <name>MatchingEngine</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[var MatchingEngine = Class.create();\nMatchingEngine.prototype = {\n    initialize: function() {},\n\n    // Fallback tolerances, used only if FinancePolicy cannot be read. The\n    // live values are the x_695068_bcfa.ap.tolerance.* properties (POC\n    // ASSUMPTION, quantity 2%) — see FinancePolicy.apTolerances().\n    DEFAULT_TOLERANCES: {\n        quantityPct: 0.02,\n        pricePct: 0.02,\n        taxAbsolute: 1.0,\n        taxRelativePct: 0.02\n    },\n\n    TAX_RATE_BY_COUNTRY: {\n        'India': 0.18,\n        'Hungary': 0.27,\n        'United States': 0.0,\n        'Germany': 0.19\n    },\n\n    // ---- AP: PO validation and 3-way match -----------------------------------\n\n    // Phase 14: the referenced purchase order must exist, belong to the\n    // invoice's vendor and not be closed. Pure check, no writes.\n    // Returns { ok:true } or { ok:false, reasonCode:'po_mismatch', description }.\n    validatePurchaseOrder: function(apInvoiceSysId) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { ok: false, reasonCode: 'other', description: 'AP Invoice not found.' };\n        if (!invoice.getValue('purchase_order')) return { ok: true, noPo: true };\n        var po = new GlideRecord('x_695068_bcfa_purchase_order');\n        if (!po.get(invoice.getValue('purchase_order'))) {\n            return { ok: false, reasonCode: 'po_mismatch', description: 'Referenced purchase order could not be resolved.' };\n        }\n        if (invoice.getValue('vendor') && po.getValue('vendor') !== invoice.getValue('vendor')) {\n            return { ok: false, reasonCode: 'po_mismatch', description: 'Purchase order ' + po.getValue('po_number') + ' belongs to vendor ' +\n                po.getDisplayValue('vendor') + ', not the invoice vendor ' + invoice.getDisplayValue('vendor') + '.' };\n        }\n        if (po.getValue('status') === 'closed') {\n            return { ok: false, reasonCode: 'po_mismatch', description: 'Purchase order ' + po.getValue('po_number') + ' is closed.' };\n        }\n        return { ok: true, poNumber: po.getValue('po_number') };\n    },\n\n    // 3-way match: invoice lines vs PO lines vs goods/service receipts, plus\n    // tax and header totals. Checks, all deterministic:\n    //   linkage   (PO invoices) at least one line; every line linked to a\n    //             line of the invoice's PO                      -> po_mismatch\n    //   receipt   (PO invoices) every line has a GRN/SRN for its own PO line\n    //                                                            -> grn_missing\n    //   quantity  |invoice qty - receipt qty| / receipt qty <= tolerance\n    //   price     |invoice price - PO price| / PO price <= tolerance\n    //   tax       |tax - net x country rate| <= max(absolute, relative band)\n    //   total     |sum of line amounts - header net| <= absolute band\n    //                                                            -> line_total_mismatch\n    threeWayMatch: function(apInvoiceSysId, toleranceOverrides) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) {\n            return { error: 'AP Invoice not found' };\n        }\n        var invoicePo = invoice.getValue('purchase_order');\n        // Phase 15: tolerances from the BCFA AP Tolerance decision table for\n        // this company / vendor country / vendor type / invoice type.\n        var tolerances = this._mergeTolerances(toleranceOverrides, {\n            company: invoice.getValue('company_code'),\n            country: this._vendorCountry(invoice.getValue('vendor')) || '',\n            vendorType: 'standard',\n            invoiceType: invoicePo ? 'po' : 'non_po'\n        });\n\n        var maxQuantityVariancePct = 0;\n        var maxPriceVariancePct = 0;\n        var matchedPoLine = null;\n        var matchedReceipt = null;\n        // Per-line evidence for the exception record and the AI agents.\n        var lineEvidence = [];\n        var quantityVarianceValue = 0;\n        var priceVarianceValue = 0;\n        var linkIssues = [];\n        var receiptIssues = [];\n        var lineCount = 0;\n        var lineTotal = 0;\n\n        var line = new GlideRecord('x_695068_bcfa_ap_invoice_line');\n        line.addQuery('ap_invoice', apInvoiceSysId);\n        line.orderBy('line_number');\n        line.query();\n        while (line.next()) {\n            lineCount++;\n            lineTotal += parseFloat(line.getValue('amount') || '0');\n            var poLineSysId = line.getValue('po_line');\n            var receiptSysId = line.getValue('receipt_reference');\n            var lineQty = parseFloat(line.getValue('quantity') || '0');\n            var lineUnitPrice = parseFloat(line.getValue('unit_price') || '0');\n            var lineLabel = 'line ' + line.getValue('line_number');\n            if (invoicePo && !poLineSysId) linkIssues.push(lineLabel + ' is not linked to a PO line');\n            if (invoicePo && poLineSysId && !receiptSysId) receiptIssues.push(lineLabel + ' has no goods/service receipt');\n            var evidence = {\n                lineNumber: line.getValue('line_number'),\n                invoiceQuantity: lineQty,\n                invoiceUnitPrice: lineUnitPrice,\n                poNumber: null,\n                poQuantity: null,\n                poUnitPrice: null,\n                receiptNumber: null,\n                receiptQuantity: null\n            };\n\n            if (poLineSysId) {\n                matchedPoLine = poLineSysId;\n                var poLine = new GlideRecord('x_695068_bcfa_po_line');\n                if (!poLine.get(poLineSysId)) {\n                    linkIssues.push(lineLabel + ' references a PO line that does not exist');\n                } else {\n                    if (invoicePo && poLine.getValue('purchase_order') !== invoicePo) {\n                        linkIssues.push(lineLabel + ' is linked to a line of PO ' + poLine.getDisplayValue('purchase_order') + ', not the invoice PO');\n                    }\n                    var poUnitPrice = parseFloat(poLine.getValue('unit_price') || '0');\n                    evidence.poNumber = poLine.getDisplayValue('purchase_order');\n                    evidence.poQuantity = parseFloat(poLine.getValue('quantity') || '0');\n                    evidence.poUnitPrice = poUnitPrice;\n                    if (poUnitPrice > 0) {\n                        var priceVariancePct = Math.abs(lineUnitPrice - poUnitPrice) / poUnitPrice;\n                        if (priceVariancePct > maxPriceVariancePct) maxPriceVariancePct = priceVariancePct;\n                        priceVarianceValue += Math.abs(lineUnitPrice - poUnitPrice) * lineQty;\n                    }\n                }\n            }\n\n            if (receiptSysId) {\n                matchedReceipt = receiptSysId;\n                var receipt = new GlideRecord('x_695068_bcfa_receipt');\n                if (!receipt.get(receiptSysId)) {\n                    receiptIssues.push(lineLabel + ' references a receipt that does not exist');\n                } else {\n                    if (poLineSysId && receipt.getValue('po_line') !== poLineSysId) {\n                        receiptIssues.push(lineLabel + ' receipt ' + receipt.getValue('receipt_number') + ' belongs to another PO line');\n                    }\n                    var receiptQty = parseFloat(receipt.getValue('quantity') || '0');\n                    evidence.receiptNumber = receipt.getValue('receipt_number');\n                    evidence.receiptQuantity = receiptQty;\n                    var base = receiptQty > 0 ? receiptQty : (lineQty > 0 ? lineQty : 1);\n                    var quantityVariancePct = Math.abs(lineQty - receiptQty) / base;\n                    if (quantityVariancePct > maxQuantityVariancePct) maxQuantityVariancePct = quantityVariancePct;\n                    quantityVarianceValue += Math.abs(lineQty - receiptQty) * lineUnitPrice;\n                }\n            }\n            lineEvidence.push(evidence);\n        }\n\n        var netAmount = parseFloat(invoice.getValue('net_amount') || '0');\n        var taxAmount = parseFloat(invoice.getValue('tax_amount') || '0');\n        var vendorCountry = this._vendorCountry(invoice.getValue('vendor'));\n        var expectedRate = this.TAX_RATE_BY_COUNTRY.hasOwnProperty(vendorCountry) ? this.TAX_RATE_BY_COUNTRY[vendorCountry] : null;\n        var taxVariance = 0;\n        var taxWithinTolerance = true;\n        var expectedTax = null;\n        if (expectedRate !== null) {\n            expectedTax = Math.round(netAmount * expectedRate * 100) / 100;\n            taxVariance = Math.abs(taxAmount - expectedTax);\n            var taxToleranceBand = Math.max(tolerances.taxAbsolute, expectedTax * tolerances.taxRelativePct);\n            taxWithinTolerance = taxVariance <= taxToleranceBand;\n        }\n\n        if (invoicePo && lineCount === 0) linkIssues.push('the invoice references PO ' + invoice.getDisplayValue('purchase_order') + ' but has no lines to match');\n        lineTotal = Math.round(lineTotal * 100) / 100;\n        // Header-vs-lines check only when lines exist (a header-only\n        // non-PO invoice has nothing to compare).\n        var lineTotalDifference = lineCount > 0 ? Math.round(Math.abs(lineTotal - netAmount) * 100) / 100 : 0;\n        var lineTotalOk = lineTotalDifference <= tolerances.taxAbsolute;\n\n        var withinTolerance = linkIssues.length === 0 && receiptIssues.length === 0 &&\n            (maxQuantityVariancePct <= tolerances.quantityPct) &&\n            (maxPriceVariancePct <= tolerances.pricePct) &&\n            taxWithinTolerance && lineTotalOk;\n\n        var matchResult = withinTolerance ? 'matched' : 'mismatch';\n\n        var match = new GlideRecord('x_695068_bcfa_ap_match');\n        match.initialize();\n        match.setValue('ap_invoice', apInvoiceSysId);\n        if (matchedPoLine) match.setValue('po_line', matchedPoLine);\n        if (matchedReceipt) match.setValue('receipt', matchedReceipt);\n        match.setValue('quantity_variance', maxQuantityVariancePct);\n        match.setValue('price_variance', maxPriceVariancePct);\n        match.setValue('tax_variance', taxVariance);\n        match.setValue('within_tolerance', withinTolerance);\n        match.setValue('match_result', matchResult);\n        match.setValue('evaluated_at', new GlideDateTime().getValue());\n        var matchSysId = match.insert();\n\n        return {\n            matchSysId: matchSysId,\n            matchResult: matchResult,\n            withinTolerance: withinTolerance,\n            quantityVariancePct: maxQuantityVariancePct,\n            priceVariancePct: maxPriceVariancePct,\n            taxVariance: taxVariance,\n            taxWithinTolerance: taxWithinTolerance,\n            quantityVarianceValue: Math.round(quantityVarianceValue * 100) / 100,\n            priceVarianceValue: Math.round(priceVarianceValue * 100) / 100,\n            netAmount: netAmount,\n            taxAmount: taxAmount,\n            vendorCountry: vendorCountry,\n            expectedTaxRate: expectedRate,\n            expectedTax: expectedTax,\n            lines: lineEvidence,\n            lineCount: lineCount,\n            linkIssues: linkIssues,\n            receiptIssues: receiptIssues,\n            lineTotal: lineTotal,\n            lineTotalDifference: lineTotalDifference,\n            lineTotalOk: lineTotalOk,\n            tolerancesUsed: tolerances\n        };\n    },\n\n    // Phase 14: an invoice is a duplicate when another live invoice of the\n    // same vendor has the same invoice number after normalization (case,\n    // spaces and punctuation ignored), whatever the amount. Same amount is\n    // an exact duplicate; a different amount is still flagged (possible\n    // re-bill or correction) and a human decides. FAILED and REJECTED\n    // invoices do not count, so a rejected invoice can be resubmitted.\n    detectDuplicateInvoice: function(apInvoiceSysId) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n\n        var duplicateKey = this._computeDuplicateKey(invoice.getValue('vendor'), invoice.getValue('invoice_number'), invoice.getValue('gross_amount'));\n        if (invoice.getValue('duplicate_key') !== duplicateKey) {\n            invoice.setValue('duplicate_key', duplicateKey);\n            invoice.update();\n        }\n        if (!invoice.getValue('vendor')) return { duplicate: false, duplicateKey: duplicateKey };\n\n        var number = this.normalizeInvoiceNumber(invoice.getValue('invoice_number'));\n        var gross = parseFloat(invoice.getValue('gross_amount') || '0');\n        var other = new GlideRecord('x_695068_bcfa_ap_invoice');\n        other.addQuery('vendor', invoice.getValue('vendor'));\n        other.addQuery('sys_id', '!=', apInvoiceSysId);\n        other.addQuery('state', 'NOT IN', 'FAILED,REJECTED');\n        other.orderBy('sys_created_on');\n        other.query();\n        var sameNumber = null;\n        while (other.next()) {\n            if (this.normalizeInvoiceNumber(other.getValue('invoice_number')) !== number) continue;\n            var otherGross = parseFloat(other.getValue('gross_amount') || '0');\n            var exact = Math.abs(otherGross - gross) <= 0.01;\n            var found = { duplicate: true, matchedInvoiceSysId: other.getUniqueValue(), matchedInvoiceNumber: other.getValue('invoice_number'),\n                matchedState: other.getValue('state'), matchedGross: otherGross, sameAmount: exact, duplicateKey: duplicateKey };\n            if (exact) return found;\n            if (!sameNumber) sameNumber = found;\n        }\n        return sameNumber || { duplicate: false, duplicateKey: duplicateKey };\n    },\n\n    // Upper case, letters and digits only: \"inv-ap 001\" == \"INVAP001\".\n    normalizeInvoiceNumber: function(value) {\n        return String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');\n    },\n\n    // ---- AR: cash application matching --------------------------------------\n\n    // Phase 13: resolves the invoice references printed on the payment's\n    // remittance to open items. Pure lookup, no writes. Never guesses: a\n    // reference that does not resolve exactly, references that belong to\n    // more than one customer, or an open item in another currency make\n    // the result unusable, and the caller falls back or raises an exception.\n    // Returns { available:false } when there is no remittance with references.\n    resolveRemittanceReferences: function(paymentSysId) {\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { available: false, error: 'Payment not found' };\n\n        var remittance = new GlideRecord('x_695068_bcfa_remittance');\n        remittance.addQuery('payment', paymentSysId);\n        remittance.addNotNullQuery('extracted_fields');\n        remittance.orderByDesc('sys_created_on');\n        remittance.setLimit(1);\n        remittance.query();\n        if (!remittance.next()) return { available: false };\n\n        var fields = {};\n        try {\n            fields = JSON.parse(remittance.getValue('extracted_fields')) || {};\n        } catch (e) {\n            return { available: false };\n        }\n        var lines = [];\n        var refLines = fields.invoice_lines || [];\n        for (var l = 0; l < refLines.length; l++) {\n            lines.push({ reference: String(refLines[l].invoice_reference || '').trim(), applied: parseFloat(refLines[l].amount_applied || '0') });\n        }\n        if (lines.length === 0) {\n            var refs = fields.invoice_references || [];\n            for (var r = 0; r < refs.length; r++) lines.push({ reference: String(refs[r] || '').trim(), applied: null });\n        }\n        if (lines.length === 0) return { available: false };\n\n        var paymentCustomer = payment.getValue('customer');\n        var paymentCurrency = payment.getValue('currency');\n        var items = [];\n        var unresolved = [];\n        var currencyMismatch = [];\n        var customers = {};\n        for (var i = 0; i < lines.length; i++) {\n            var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n            item.addQuery('item_number', lines[i].reference);\n            item.addQuery('status', '!=', 'cleared');\n            if (paymentCustomer) item.addQuery('customer', paymentCustomer);\n            item.query();\n            if (item.getRowCount() !== 1 || !item.next()) {\n                unresolved.push(lines[i].reference);\n                continue;\n            }\n            if (paymentCurrency && item.getValue('currency') && item.getValue('currency') !== paymentCurrency) {\n                currencyMismatch.push(lines[i].reference + ' (' + item.getValue('currency') + ')');\n            }\n            customers[item.getValue('customer')] = true;\n            items.push({\n                sysId: item.getUniqueValue(),\n                itemNumber: item.getValue('item_number'),\n                customer: item.getValue('customer'),\n                openAmount: parseFloat(item.getValue('open_amount') || '0'),\n                applied: lines[i].applied\n            });\n        }\n\n        var customerIds = [];\n        for (var c in customers) customerIds.push(c);\n        var openTotal = 0;\n        for (var t = 0; t < items.length; t++) openTotal += items[t].openAmount;\n        openTotal = Math.round(openTotal * 100) / 100;\n        var paymentAmount = parseFloat(payment.getValue('amount') || '0');\n\n        return {\n            available: true,\n            usable: unresolved.length === 0 && currencyMismatch.length === 0 && customerIds.length === 1,\n            remittanceSysId: remittance.getUniqueValue(),\n            references: lines,\n            items: items,\n            unresolved: unresolved,\n            currencyMismatch: currencyMismatch,\n            customerSysId: customerIds.length === 1 ? customerIds[0] : null,\n            customerCount: customerIds.length,\n            openTotal: openTotal,\n            paymentAmount: paymentAmount,\n            residual: Math.round((paymentAmount - openTotal) * 100) / 100,\n            deductionHint: fields.deduction_reason ? { amount: fields.deduction_amount, reason: fields.deduction_reason } : null\n        };\n    },\n\n    // Records the resolved remittance references as selected match\n    // candidates (match_type 'remittance'), in remittance order.\n    recordRemittanceCandidates: function(paymentSysId, resolution) {\n        for (var i = 0; i < resolution.items.length; i++) {\n            this._recordMatchCandidate(paymentSysId, resolution.items[i].sysId, resolution.customerSysId, 'remittance', 1.0, i + 1, true);\n        }\n    },\n\n    exactMatch: function(paymentSysId) {\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { error: 'Payment not found' };\n        if (!payment.getValue('customer')) return { matched: false, reason: 'no customer resolved' };\n\n        var amount = parseFloat(payment.getValue('amount') || '0');\n        var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n        item.addQuery('customer', payment.getValue('customer'));\n        item.addQuery('status', '!=', 'cleared');\n        // Phase 14: never match across currencies.\n        if (payment.getValue('currency')) item.addQuery('currency', payment.getValue('currency'));\n        item.query();\n        var candidates = [];\n        while (item.next()) {\n            var openAmount = parseFloat(item.getValue('open_amount') || '0');\n            if (Math.abs(openAmount - amount) <= 0.01) {\n                candidates.push(item.getUniqueValue());\n            }\n        }\n        if (candidates.length === 1) {\n            this._recordMatchCandidate(paymentSysId, candidates[0], payment.getValue('customer'), 'exact', 1.0, 1, true);\n            return { matched: true, arOpenItemSysId: candidates[0] };\n        }\n        return { matched: false, candidateCount: candidates.length };\n    },\n\n    // Greedy multi-invoice allocation suggestion: accumulates the customer's\n    // open items (oldest due date first) until the running total reaches the\n    // payment amount. Deterministic and simple by design — a POC stand-in\n    // for a full subset-sum solver.\n    multiInvoiceSuggestion: function(paymentSysId) {\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { error: 'Payment not found' };\n        if (!payment.getValue('customer')) return { matched: false, reason: 'no customer resolved' };\n\n        var amount = parseFloat(payment.getValue('amount') || '0');\n        var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n        item.addQuery('customer', payment.getValue('customer'));\n        item.addQuery('status', '!=', 'cleared');\n        if (payment.getValue('currency')) item.addQuery('currency', payment.getValue('currency'));\n        item.orderBy('due_date');\n        item.query();\n\n        var running = 0;\n        var selected = [];\n        var rank = 1;\n        while (item.next() && running < amount) {\n            var openAmount = parseFloat(item.getValue('open_amount') || '0');\n            selected.push(item.getUniqueValue());\n            this._recordMatchCandidate(paymentSysId, item.getUniqueValue(), payment.getValue('customer'), 'fuzzy', 0.75, rank, false);\n            running += openAmount;\n            rank++;\n        }\n\n        var residual = Math.round((amount - running) * 100) / 100;\n        var exact = Math.abs(residual) <= 0.01;\n        return { matched: selected.length > 0, exact: exact, residual: residual, arOpenItemSysIds: selected };\n    },\n\n    // Phase 14: remitter name -> customer. Compares normalized names (case,\n    // punctuation and spacing ignored) against active aliases, then active\n    // customer names. A name that points to more than one customer is\n    // ambiguous and never resolved; the candidates are returned for a human.\n    resolveCustomerByAlias: function(candidateName) {\n        var wanted = this.normalizeName(candidateName);\n        if (!wanted) return { resolved: false };\n\n        var byCustomer = {};\n        var alias = new GlideRecord('x_695068_bcfa_customer_alias');\n        alias.addQuery('active', true);\n        alias.query();\n        while (alias.next()) {\n            if (this.normalizeName(alias.getValue('alias_name')) !== wanted) continue;\n            var aliasConfidence = parseFloat(alias.getValue('confidence') || '1');\n            var existing = byCustomer[alias.getValue('customer')];\n            if (!existing || aliasConfidence > existing.confidence) {\n                byCustomer[alias.getValue('customer')] = { confidence: aliasConfidence, method: 'alias' };\n            }\n        }\n        var result = this._singleCustomer(byCustomer);\n        if (result) return result;\n\n        byCustomer = {};\n        var customer = new GlideRecord('x_695068_bcfa_customer');\n        customer.addQuery('active', true);\n        customer.query();\n        while (customer.next()) {\n            if (this.normalizeName(customer.getValue('name')) === wanted) {\n                byCustomer[customer.getUniqueValue()] = { confidence: 1.0, method: 'exact_name' };\n            }\n        }\n        return this._singleCustomer(byCustomer) || { resolved: false };\n    },\n\n    _singleCustomer: function(byCustomer) {\n        var ids = [];\n        for (var id in byCustomer) ids.push(id);\n        if (ids.length === 1) {\n            return { resolved: true, customerSysId: ids[0], confidence: byCustomer[ids[0]].confidence, method: byCustomer[ids[0]].method };\n        }\n        if (ids.length > 1) return { resolved: false, ambiguous: true, candidates: ids };\n        return null;\n    },\n\n    // Upper case, letters/digits separated by single spaces:\n    // \"Lone Star Tyre Co.\" == \"LONE STAR TYRE CO\".\n    normalizeName: function(value) {\n        return String(value || '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();\n    },\n\n    // Phase 14: exact combinations of the customer's open items (same\n    // currency) that sum to the payment amount, found by an exhaustive,\n    // deterministic search in cents. Stops after maxSolutions. Customers\n    // with more than MAX_COMBINATION_ITEMS open items are not searched (the\n    // result says so) to bound the work.\n    // Returns { searched, solutions: [[{sysId, itemNumber, openAmount}]] }.\n    MAX_COMBINATION_ITEMS: 20,\n\n    findExactCombinations: function(paymentSysId, maxSolutions) {\n        maxSolutions = maxSolutions || 2;\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId) || !payment.getValue('customer')) return { searched: false, reason: 'no customer', solutions: [] };\n        var target = Math.round(parseFloat(payment.getValue('amount') || '0') * 100);\n\n        var items = [];\n        var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n        item.addQuery('customer', payment.getValue('customer'));\n        item.addQuery('status', '!=', 'cleared');\n        item.addQuery('open_amount', '>', 0);\n        if (payment.getValue('currency')) item.addQuery('currency', payment.getValue('currency'));\n        item.orderBy('due_date');\n        item.orderBy('item_number');\n        item.query();\n        while (item.next()) {\n            items.push({ sysId: item.getUniqueValue(), itemNumber: item.getValue('item_number'),\n                openAmount: parseFloat(item.getValue('open_amount') || '0'), cents: Math.round(parseFloat(item.getValue('open_amount') || '0') * 100) });\n        }\n        if (items.length > this.MAX_COMBINATION_ITEMS) {\n            return { searched: false, reason: items.length + ' open items exceed the search limit of ' + this.MAX_COMBINATION_ITEMS, solutions: [] };\n        }\n\n        var solutions = [];\n        var chosen = [];\n        var search = function(index, remaining) {\n            if (solutions.length >= maxSolutions) return;\n            if (remaining === 0 && chosen.length > 1) {\n                solutions.push(chosen.slice());\n                return;\n            }\n            for (var i = index; i < items.length; i++) {\n                if (items[i].cents > remaining) continue;\n                chosen.push(items[i]);\n                search(i + 1, remaining - items[i].cents);\n                chosen.pop();\n                if (solutions.length >= maxSolutions) return;\n            }\n        };\n        search(0, target);\n        return { searched: true, itemCount: items.length, solutions: solutions };\n    },\n\n    // Records one combination as selected candidates, or several as\n    // unselected, ranked candidates (rank = combination number) for review.\n    recordCombinationCandidates: function(paymentSysId, customerSysId, solutions, selected) {\n        for (var s = 0; s < solutions.length; s++) {\n            for (var i = 0; i < solutions[s].length; i++) {\n                this._recordMatchCandidate(paymentSysId, solutions[s][i].sysId, customerSysId, 'combination', selected ? 1.0 : 0.5, s + 1, !!selected);\n            }\n        }\n    },\n\n    // Phase 14: deterministic suggestion for a short-pay residual, for the\n    // reviewer to confirm. A unique open credit note of the customer for\n    // exactly the residual suggests credit-note netting; otherwise a residual\n    // up to ar.bank_charge.max_amount suggests a bank charge. Never applied\n    // automatically.\n    classifyResidual: function(paymentSysId, residual) {\n        residual = Math.round(parseFloat(residual || '0') * 100) / 100;\n        if (residual <= 0.01) return { type: null };\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { type: null };\n\n        if (payment.getValue('customer')) {\n            var matches = [];\n            var note = new GlideRecord('x_695068_bcfa_credit_note');\n            note.addQuery('customer', payment.getValue('customer'));\n            note.addQuery('status', 'open');\n            note.query();\n            while (note.next()) {\n                if (Math.abs(parseFloat(note.getValue('open_amount') || '0') - residual) <= 0.01) {\n                    matches.push({ sysId: note.getUniqueValue(), number: note.getValue('credit_note_number') });\n                }\n            }\n            if (matches.length === 1) {\n                return { type: 'credit_note_netting', creditNoteSysId: matches[0].sysId,\n                    rule: 'residual ' + residual + ' equals open credit note ' + matches[0].number + ' of the same customer' };\n            }\n        }\n        var bankChargeMax = new FinancePolicy().arBankChargeMax();\n        if (residual <= bankChargeMax) {\n            return { type: 'bank_charge', rule: 'residual ' + residual + ' is within the bank charge limit ' + bankChargeMax + ' (x_695068_bcfa.ar.bank_charge.max_amount)' };\n        }\n        return { type: null, rule: 'residual ' + residual + ' matches no open credit note and exceeds the bank charge limit ' + bankChargeMax };\n    },\n\n    _recordMatchCandidate: function(paymentSysId, arOpenItemSysId, customerSysId, matchType, confidence, rank, selected) {\n        var mc = new GlideRecord('x_695068_bcfa_match_candidate');\n        mc.initialize();\n        mc.setValue('payment', paymentSysId);\n        mc.setValue('ar_open_item', arOpenItemSysId);\n        if (customerSysId) mc.setValue('customer_candidate', customerSysId);\n        mc.setValue('match_type', matchType);\n        mc.setValue('confidence', confidence);\n        mc.setValue('rank', rank);\n        mc.setValue('selected', !!selected);\n        return mc.insert();\n    },\n\n    _vendorCountry: function(vendorSysId) {\n        if (!vendorSysId) return null;\n        var vendor = new GlideRecord('x_695068_bcfa_vendor');\n        if (vendor.get(vendorSysId)) return vendor.getValue('country');\n        return null;\n    },\n\n    _computeDuplicateKey: function(vendorSysId, invoiceNumber, grossAmount) {\n        return (vendorSysId || '') + '|' + (invoiceNumber || '') + '|' + (grossAmount || '');\n    },\n\n    _mergeTolerances: function(overrides, context) {\n        var merged = {};\n        var configured = {};\n        try {\n            configured = new FinancePolicy().apTolerances(context);\n        } catch (e) {\n            configured = {};\n        }\n        for (var k in this.DEFAULT_TOLERANCES) {\n            merged[k] = configured.hasOwnProperty(k) ? configured[k] : this.DEFAULT_TOLERANCES[k];\n        }\n        merged.source = configured.source || 'engine defaults';\n        if (overrides) {\n            for (var k2 in overrides) {\n                merged[k2] = overrides[k2];\n            }\n        }\n        return merged;\n    },\n\n    type: 'MatchingEngine'\n};\n]]></script>\n    <sys_name>MatchingEngine</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_0afe83b033c04df8b7bacd7ed3786d63.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>0afe83b033c04df8b7bacd7ed3786d63</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_0afe83b033c04df8b7bacd7ed3786d63</sys_update_name>\n    <content><![CDATA[var MatchingEngine = Class.create();\nMatchingEngine.prototype = {\n    initialize: function() {},\n\n    // Fallback tolerances, used only if FinancePolicy cannot be read. The\n    // live values are the x_695068_bcfa.ap.tolerance.* properties (POC\n    // ASSUMPTION, quantity 2%) — see FinancePolicy.apTolerances().\n    DEFAULT_TOLERANCES: {\n        quantityPct: 0.02,\n        pricePct: 0.02,\n        taxAbsolute: 1.0,\n        taxRelativePct: 0.02\n    },\n\n    TAX_RATE_BY_COUNTRY: {\n        'India': 0.18,\n        'Hungary': 0.27,\n        'United States': 0.0,\n        'Germany': 0.19\n    },\n\n    // ---- AP: PO validation and 3-way match -----------------------------------\n\n    // Phase 14: the referenced purchase order must exist, belong to the\n    // invoice's vendor and not be closed. Pure check, no writes.\n    // Returns { ok:true } or { ok:false, reasonCode:'po_mismatch', description }.\n    validatePurchaseOrder: function(apInvoiceSysId) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { ok: false, reasonCode: 'other', description: 'AP Invoice not found.' };\n        if (!invoice.getValue('purchase_order')) return { ok: true, noPo: true };\n        var po = new GlideRecord('x_695068_bcfa_purchase_order');\n        if (!po.get(invoice.getValue('purchase_order'))) {\n            return { ok: false, reasonCode: 'po_mismatch', description: 'Referenced purchase order could not be resolved.' };\n        }\n        if (invoice.getValue('vendor') && po.getValue('vendor') !== invoice.getValue('vendor')) {\n            return { ok: false, reasonCode: 'po_mismatch', description: 'Purchase order ' + po.getValue('po_number') + ' belongs to vendor ' +\n                po.getDisplayValue('vendor') + ', not the invoice vendor ' + invoice.getDisplayValue('vendor') + '.' };\n        }\n        if (po.getValue('status') === 'closed') {\n            return { ok: false, reasonCode: 'po_mismatch', description: 'Purchase order ' + po.getValue('po_number') + ' is closed.' };\n        }\n        return { ok: true, poNumber: po.getValue('po_number') };\n    },\n\n    // 3-way match: invoice lines vs PO lines vs goods/service receipts, plus\n    // tax and header totals. Checks, all deterministic:\n    //   linkage   (PO invoices) at least one line; every line linked to a\n    //             line of the invoice's PO                      -> po_mismatch\n    //   receipt   (PO invoices) every line has a GRN/SRN for its own PO line\n    //                                                            -> grn_missing\n    //   quantity  |invoice qty - receipt qty| / receipt qty <= tolerance\n    //   price     |invoice price - PO price| / PO price <= tolerance\n    //   tax       |tax - net x country rate| <= max(absolute, relative band)\n    //   total     |sum of line amounts - header net| <= absolute band\n    //                                                            -> line_total_mismatch\n    threeWayMatch: function(apInvoiceSysId, toleranceOverrides) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) {\n            return { error: 'AP Invoice not found' };\n        }\n        var invoicePo = invoice.getValue('purchase_order');\n        // Phase 15: tolerances from the BCFA AP Tolerance decision table for\n        // this company / vendor country / vendor type / invoice type.\n        var tolerances = this._mergeTolerances(toleranceOverrides, {\n            company: invoice.getValue('company_code'),\n            country: this._vendorCountry(invoice.getValue('vendor')) || '',\n            vendorType: 'standard',\n            invoiceType: invoicePo ? 'po' : 'non_po'\n        });\n\n        var maxQuantityVariancePct = 0;\n        var maxPriceVariancePct = 0;\n        var matchedPoLine = null;\n        var matchedReceipt = null;\n        // Per-line evidence for the exception record and the AI agents.\n        var lineEvidence = [];\n        var quantityVarianceValue = 0;\n        var priceVarianceValue = 0;\n        var linkIssues = [];\n        var receiptIssues = [];\n        var lineCount = 0;\n        var lineTotal = 0;\n\n        var line = new GlideRecord('x_695068_bcfa_ap_invoice_line');\n        line.addQuery('ap_invoice', apInvoiceSysId);\n        line.orderBy('line_number');\n        line.query();\n        while (line.next()) {\n            lineCount++;\n            lineTotal += parseFloat(line.getValue('amount') || '0');\n            var poLineSysId = line.getValue('po_line');\n            var receiptSysId = line.getValue('receipt_reference');\n            var lineQty = parseFloat(line.getValue('quantity') || '0');\n            var lineUnitPrice = parseFloat(line.getValue('unit_price') || '0');\n            var lineLabel = 'line ' + line.getValue('line_number');\n            if (invoicePo && !poLineSysId) linkIssues.push(lineLabel + ' is not linked to a PO line');\n            if (invoicePo && poLineSysId && !receiptSysId) receiptIssues.push(lineLabel + ' has no goods/service receipt');\n            var evidence = {\n                lineNumber: line.getValue('line_number'),\n                invoiceQuantity: lineQty,\n                invoiceUnitPrice: lineUnitPrice,\n                poNumber: null,\n                poQuantity: null,\n                poUnitPrice: null,\n                receiptNumber: null,\n                receiptQuantity: null\n            };\n\n            if (poLineSysId) {\n                matchedPoLine = poLineSysId;\n                var poLine = new GlideRecord('x_695068_bcfa_po_line');\n                if (!poLine.get(poLineSysId)) {\n                    linkIssues.push(lineLabel + ' references a PO line that does not exist');\n                } else {\n                    if (invoicePo && poLine.getValue('purchase_order') !== invoicePo) {\n                        linkIssues.push(lineLabel + ' is linked to a line of PO ' + poLine.getDisplayValue('purchase_order') + ', not the invoice PO');\n                    }\n                    var poUnitPrice = parseFloat(poLine.getValue('unit_price') || '0');\n                    evidence.poNumber = poLine.getDisplayValue('purchase_order');\n                    evidence.poQuantity = parseFloat(poLine.getValue('quantity') || '0');\n                    evidence.poUnitPrice = poUnitPrice;\n                    if (poUnitPrice > 0) {\n                        var priceVariancePct = Math.abs(lineUnitPrice - poUnitPrice) / poUnitPrice;\n                        if (priceVariancePct > maxPriceVariancePct) maxPriceVariancePct = priceVariancePct;\n                        priceVarianceValue += Math.abs(lineUnitPrice - poUnitPrice) * lineQty;\n                    }\n                }\n            }\n\n            if (receiptSysId) {\n                matchedReceipt = receiptSysId;\n                var receipt = new GlideRecord('x_695068_bcfa_receipt');\n                if (!receipt.get(receiptSysId)) {\n                    receiptIssues.push(lineLabel + ' references a receipt that does not exist');\n                } else {\n                    if (poLineSysId && receipt.getValue('po_line') !== poLineSysId) {\n                        receiptIssues.push(lineLabel + ' receipt ' + receipt.getValue('receipt_number') + ' belongs to another PO line');\n                    }\n                    var receiptQty = parseFloat(receipt.getValue('quantity') || '0');\n                    evidence.receiptNumber = receipt.getValue('receipt_number');\n                    evidence.receiptQuantity = receiptQty;\n                    var base = receiptQty > 0 ? receiptQty : (lineQty > 0 ? lineQty : 1);\n                    var quantityVariancePct = Math.abs(lineQty - receiptQty) / base;\n                    if (quantityVariancePct > maxQuantityVariancePct) maxQuantityVariancePct = quantityVariancePct;\n                    quantityVarianceValue += Math.abs(lineQty - receiptQty) * lineUnitPrice;\n                }\n            }\n            lineEvidence.push(evidence);\n        }\n\n        var netAmount = parseFloat(invoice.getValue('net_amount') || '0');\n        var taxAmount = parseFloat(invoice.getValue('tax_amount') || '0');\n        var vendorCountry = this._vendorCountry(invoice.getValue('vendor'));\n        var expectedRate = this.TAX_RATE_BY_COUNTRY.hasOwnProperty(vendorCountry) ? this.TAX_RATE_BY_COUNTRY[vendorCountry] : null;\n        var taxVariance = 0;\n        var taxWithinTolerance = true;\n        var expectedTax = null;\n        if (expectedRate !== null) {\n            expectedTax = Math.round(netAmount * expectedRate * 100) / 100;\n            taxVariance = Math.abs(taxAmount - expectedTax);\n            var taxToleranceBand = Math.max(tolerances.taxAbsolute, expectedTax * tolerances.taxRelativePct);\n            taxWithinTolerance = taxVariance <= taxToleranceBand;\n        }\n\n        if (invoicePo && lineCount === 0) linkIssues.push('the invoice references PO ' + invoice.getDisplayValue('purchase_order') + ' but has no lines to match');\n        lineTotal = Math.round(lineTotal * 100) / 100;\n        // Header-vs-lines check only when lines exist (a header-only\n        // non-PO invoice has nothing to compare).\n        var lineTotalDifference = lineCount > 0 ? Math.round(Math.abs(lineTotal - netAmount) * 100) / 100 : 0;\n        var lineTotalOk = lineTotalDifference <= tolerances.taxAbsolute;\n\n        var withinTolerance = linkIssues.length === 0 && receiptIssues.length === 0 &&\n            (maxQuantityVariancePct <= tolerances.quantityPct) &&\n            (maxPriceVariancePct <= tolerances.pricePct) &&\n            taxWithinTolerance && lineTotalOk;\n\n        var matchResult = withinTolerance ? 'matched' : 'mismatch';\n\n        var match = new GlideRecord('x_695068_bcfa_ap_match');\n        match.initialize();\n        match.setValue('ap_invoice', apInvoiceSysId);\n        if (matchedPoLine) match.setValue('po_line', matchedPoLine);\n        if (matchedReceipt) match.setValue('receipt', matchedReceipt);\n        match.setValue('quantity_variance', maxQuantityVariancePct);\n        match.setValue('price_variance', maxPriceVariancePct);\n        match.setValue('tax_variance', taxVariance);\n        match.setValue('within_tolerance', withinTolerance);\n        match.setValue('match_result', matchResult);\n        match.setValue('evaluated_at', new GlideDateTime().getValue());\n        var matchSysId = match.insert();\n\n        return {\n            matchSysId: matchSysId,\n            matchResult: matchResult,\n            withinTolerance: withinTolerance,\n            quantityVariancePct: maxQuantityVariancePct,\n            priceVariancePct: maxPriceVariancePct,\n            taxVariance: taxVariance,\n            taxWithinTolerance: taxWithinTolerance,\n            quantityVarianceValue: Math.round(quantityVarianceValue * 100) / 100,\n            priceVarianceValue: Math.round(priceVarianceValue * 100) / 100,\n            netAmount: netAmount,\n            taxAmount: taxAmount,\n            vendorCountry: vendorCountry,\n            expectedTaxRate: expectedRate,\n            expectedTax: expectedTax,\n            lines: lineEvidence,\n            lineCount: lineCount,\n            linkIssues: linkIssues,\n            receiptIssues: receiptIssues,\n            lineTotal: lineTotal,\n            lineTotalDifference: lineTotalDifference,\n            lineTotalOk: lineTotalOk,\n            tolerancesUsed: tolerances\n        };\n    },\n\n    // Phase 14: an invoice is a duplicate when another live invoice of the\n    // same vendor has the same invoice number after normalization (case,\n    // spaces and punctuation ignored), whatever the amount. Same amount is\n    // an exact duplicate; a different amount is still flagged (possible\n    // re-bill or correction) and a human decides. FAILED and REJECTED\n    // invoices do not count, so a rejected invoice can be resubmitted.\n    detectDuplicateInvoice: function(apInvoiceSysId) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n\n        var duplicateKey = this._computeDuplicateKey(invoice.getValue('vendor'), invoice.getValue('invoice_number'), invoice.getValue('gross_amount'));\n        if (invoice.getValue('duplicate_key') !== duplicateKey) {\n            invoice.setValue('duplicate_key', duplicateKey);\n            invoice.update();\n        }\n        if (!invoice.getValue('vendor')) return { duplicate: false, duplicateKey: duplicateKey };\n\n        var number = this.normalizeInvoiceNumber(invoice.getValue('invoice_number'));\n        var gross = parseFloat(invoice.getValue('gross_amount') || '0');\n        var other = new GlideRecord('x_695068_bcfa_ap_invoice');\n        other.addQuery('vendor', invoice.getValue('vendor'));\n        other.addQuery('sys_id', '!=', apInvoiceSysId);\n        other.addQuery('state', 'NOT IN', 'FAILED,REJECTED');\n        other.orderBy('sys_created_on');\n        other.query();\n        var sameNumber = null;\n        while (other.next()) {\n            if (this.normalizeInvoiceNumber(other.getValue('invoice_number')) !== number) continue;\n            var otherGross = parseFloat(other.getValue('gross_amount') || '0');\n            var exact = Math.abs(otherGross - gross) <= 0.01;\n            var found = { duplicate: true, matchedInvoiceSysId: other.getUniqueValue(), matchedInvoiceNumber: other.getValue('invoice_number'),\n                matchedState: other.getValue('state'), matchedGross: otherGross, sameAmount: exact, duplicateKey: duplicateKey };\n            if (exact) return found;\n            if (!sameNumber) sameNumber = found;\n        }\n        return sameNumber || { duplicate: false, duplicateKey: duplicateKey };\n    },\n\n    // Upper case, letters and digits only: \"inv-ap 001\" == \"INVAP001\".\n    normalizeInvoiceNumber: function(value) {\n        return String(value || '').toUpperCase().replace(/[^A-Z0-9]/g, '');\n    },\n\n    // ---- AR: cash application matching --------------------------------------\n\n    // Phase 13: resolves the invoice references printed on the payment's\n    // remittance to open items. Pure lookup, no writes. Never guesses: a\n    // reference that does not resolve exactly, references that belong to\n    // more than one customer, or an open item in another currency make\n    // the result unusable, and the caller falls back or raises an exception.\n    // Returns { available:false } when there is no remittance with references.\n    resolveRemittanceReferences: function(paymentSysId) {\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { available: false, error: 'Payment not found' };\n\n        var remittance = new GlideRecord('x_695068_bcfa_remittance');\n        remittance.addQuery('payment', paymentSysId);\n        remittance.addNotNullQuery('extracted_fields');\n        remittance.orderByDesc('sys_created_on');\n        remittance.setLimit(1);\n        remittance.query();\n        if (!remittance.next()) return { available: false };\n\n        var fields = {};\n        try {\n            fields = JSON.parse(remittance.getValue('extracted_fields')) || {};\n        } catch (e) {\n            return { available: false };\n        }\n        var lines = [];\n        var refLines = fields.invoice_lines || [];\n        for (var l = 0; l < refLines.length; l++) {\n            lines.push({ reference: String(refLines[l].invoice_reference || '').trim(), applied: parseFloat(refLines[l].amount_applied || '0') });\n        }\n        if (lines.length === 0) {\n            var refs = fields.invoice_references || [];\n            for (var r = 0; r < refs.length; r++) lines.push({ reference: String(refs[r] || '').trim(), applied: null });\n        }\n        if (lines.length === 0) return { available: false };\n\n        var paymentCustomer = payment.getValue('customer');\n        var paymentCurrency = payment.getValue('currency');\n        var items = [];\n        var unresolved = [];\n        var currencyMismatch = [];\n        var customers = {};\n        for (var i = 0; i < lines.length; i++) {\n            var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n            item.addQuery('item_number', lines[i].reference);\n            item.addQuery('status', '!=', 'cleared');\n            if (paymentCustomer) item.addQuery('customer', paymentCustomer);\n            item.query();\n            if (item.getRowCount() !== 1 || !item.next()) {\n                unresolved.push(lines[i].reference);\n                continue;\n            }\n            if (paymentCurrency && item.getValue('currency') && item.getValue('currency') !== paymentCurrency) {\n                currencyMismatch.push(lines[i].reference + ' (' + item.getValue('currency') + ')');\n            }\n            customers[item.getValue('customer')] = true;\n            items.push({\n                sysId: item.getUniqueValue(),\n                itemNumber: item.getValue('item_number'),\n                customer: item.getValue('customer'),\n                openAmount: parseFloat(item.getValue('open_amount') || '0'),\n                applied: lines[i].applied\n            });\n        }\n\n        var customerIds = [];\n        for (var c in customers) customerIds.push(c);\n        var openTotal = 0;\n        for (var t = 0; t < items.length; t++) openTotal += items[t].openAmount;\n        openTotal = Math.round(openTotal * 100) / 100;\n        var paymentAmount = parseFloat(payment.getValue('amount') || '0');\n\n        return {\n            available: true,\n            usable: unresolved.length === 0 && currencyMismatch.length === 0 && customerIds.length === 1,\n            remittanceSysId: remittance.getUniqueValue(),\n            references: lines,\n            items: items,\n            unresolved: unresolved,\n            currencyMismatch: currencyMismatch,\n            customerSysId: customerIds.length === 1 ? customerIds[0] : null,\n            customerCount: customerIds.length,\n            openTotal: openTotal,\n            paymentAmount: paymentAmount,\n            residual: Math.round((paymentAmount - openTotal) * 100) / 100,\n            deductionHint: fields.deduction_reason ? { amount: fields.deduction_amount, reason: fields.deduction_reason } : null\n        };\n    },\n\n    // Records the resolved remittance references as selected match\n    // candidates (match_type 'remittance'), in remittance order.\n    recordRemittanceCandidates: function(paymentSysId, resolution) {\n        for (var i = 0; i < resolution.items.length; i++) {\n            this._recordMatchCandidate(paymentSysId, resolution.items[i].sysId, resolution.customerSysId, 'remittance', 1.0, i + 1, true);\n        }\n    },\n\n    exactMatch: function(paymentSysId) {\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { error: 'Payment not found' };\n        if (!payment.getValue('customer')) return { matched: false, reason: 'no customer resolved' };\n\n        var amount = parseFloat(payment.getValue('amount') || '0');\n        var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n        item.addQuery('customer', payment.getValue('customer'));\n        item.addQuery('status', '!=', 'cleared');\n        // Phase 14: never match across currencies.\n        if (payment.getValue('currency')) item.addQuery('currency', payment.getValue('currency'));\n        item.query();\n        var candidates = [];\n        while (item.next()) {\n            var openAmount = parseFloat(item.getValue('open_amount') || '0');\n            if (Math.abs(openAmount - amount) <= 0.01) {\n                candidates.push(item.getUniqueValue());\n            }\n        }\n        if (candidates.length === 1) {\n            this._recordMatchCandidate(paymentSysId, candidates[0], payment.getValue('customer'), 'exact', 1.0, 1, true);\n            return { matched: true, arOpenItemSysId: candidates[0] };\n        }\n        return { matched: false, candidateCount: candidates.length };\n    },\n\n    // Greedy multi-invoice allocation suggestion: accumulates the customer's\n    // open items (oldest due date first) until the running total reaches the\n    // payment amount. Deterministic and simple by design — a POC stand-in\n    // for a full subset-sum solver.\n    multiInvoiceSuggestion: function(paymentSysId) {\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { error: 'Payment not found' };\n        if (!payment.getValue('customer')) return { matched: false, reason: 'no customer resolved' };\n\n        var amount = parseFloat(payment.getValue('amount') || '0');\n        var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n        item.addQuery('customer', payment.getValue('customer'));\n        item.addQuery('status', '!=', 'cleared');\n        if (payment.getValue('currency')) item.addQuery('currency', payment.getValue('currency'));\n        item.orderBy('due_date');\n        item.query();\n\n        var running = 0;\n        var selected = [];\n        var rank = 1;\n        while (item.next() && running < amount) {\n            var openAmount = parseFloat(item.getValue('open_amount') || '0');\n            selected.push(item.getUniqueValue());\n            this._recordMatchCandidate(paymentSysId, item.getUniqueValue(), payment.getValue('customer'), 'fuzzy', 0.75, rank, false);\n            running += openAmount;\n            rank++;\n        }\n\n        var residual = Math.round((amount - running) * 100) / 100;\n        var exact = Math.abs(residual) <= 0.01;\n        return { matched: selected.length > 0, exact: exact, residual: residual, arOpenItemSysIds: selected };\n    },\n\n    // Phase 14: remitter name -> customer. Compares normalized names (case,\n    // punctuation and spacing ignored) against active aliases, then active\n    // customer names. A name that points to more than one customer is\n    // ambiguous and never resolved; the candidates are returned for a human.\n    resolveCustomerByAlias: function(candidateName) {\n        var wanted = this.normalizeName(candidateName);\n        if (!wanted) return { resolved: false };\n\n        var byCustomer = {};\n        var alias = new GlideRecord('x_695068_bcfa_customer_alias');\n        alias.addQuery('active', true);\n        alias.query();\n        while (alias.next()) {\n            if (this.normalizeName(alias.getValue('alias_name')) !== wanted) continue;\n            var aliasConfidence = parseFloat(alias.getValue('confidence') || '1');\n            var existing = byCustomer[alias.getValue('customer')];\n            if (!existing || aliasConfidence > existing.confidence) {\n                byCustomer[alias.getValue('customer')] = { confidence: aliasConfidence, method: 'alias' };\n            }\n        }\n        var result = this._singleCustomer(byCustomer);\n        if (result) return result;\n\n        byCustomer = {};\n        var customer = new GlideRecord('x_695068_bcfa_customer');\n        customer.addQuery('active', true);\n        customer.query();\n        while (customer.next()) {\n            if (this.normalizeName(customer.getValue('name')) === wanted) {\n                byCustomer[customer.getUniqueValue()] = { confidence: 1.0, method: 'exact_name' };\n            }\n        }\n        return this._singleCustomer(byCustomer) || { resolved: false };\n    },\n\n    _singleCustomer: function(byCustomer) {\n        var ids = [];\n        for (var id in byCustomer) ids.push(id);\n        if (ids.length === 1) {\n            return { resolved: true, customerSysId: ids[0], confidence: byCustomer[ids[0]].confidence, method: byCustomer[ids[0]].method };\n        }\n        if (ids.length > 1) return { resolved: false, ambiguous: true, candidates: ids };\n        return null;\n    },\n\n    // Upper case, letters/digits separated by single spaces:\n    // \"Lone Star Tyre Co.\" == \"LONE STAR TYRE CO\".\n    normalizeName: function(value) {\n        return String(value || '').toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();\n    },\n\n    // Phase 14: exact combinations of the customer's open items (same\n    // currency) that sum to the payment amount, found by an exhaustive,\n    // deterministic search in cents. Stops after maxSolutions. Customers\n    // with more than MAX_COMBINATION_ITEMS open items are not searched (the\n    // result says so) to bound the work.\n    // Returns { searched, solutions: [[{sysId, itemNumber, openAmount}]] }.\n    MAX_COMBINATION_ITEMS: 20,\n\n    findExactCombinations: function(paymentSysId, maxSolutions) {\n        maxSolutions = maxSolutions || 2;\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId) || !payment.getValue('customer')) return { searched: false, reason: 'no customer', solutions: [] };\n        var target = Math.round(parseFloat(payment.getValue('amount') || '0') * 100);\n\n        var items = [];\n        var item = new GlideRecord('x_695068_bcfa_ar_open_item');\n        item.addQuery('customer', payment.getValue('customer'));\n        item.addQuery('status', '!=', 'cleared');\n        item.addQuery('open_amount', '>', 0);\n        if (payment.getValue('currency')) item.addQuery('currency', payment.getValue('currency'));\n        item.orderBy('due_date');\n        item.orderBy('item_number');\n        item.query();\n        while (item.next()) {\n            items.push({ sysId: item.getUniqueValue(), itemNumber: item.getValue('item_number'),\n                openAmount: parseFloat(item.getValue('open_amount') || '0'), cents: Math.round(parseFloat(item.getValue('open_amount') || '0') * 100) });\n        }\n        if (items.length > this.MAX_COMBINATION_ITEMS) {\n            return { searched: false, reason: items.length + ' open items exceed the search limit of ' + this.MAX_COMBINATION_ITEMS, solutions: [] };\n        }\n\n        var solutions = [];\n        var chosen = [];\n        var search = function(index, remaining) {\n            if (solutions.length >= maxSolutions) return;\n            if (remaining === 0 && chosen.length > 1) {\n                solutions.push(chosen.slice());\n                return;\n            }\n            for (var i = index; i < items.length; i++) {\n                if (items[i].cents > remaining) continue;\n                chosen.push(items[i]);\n                search(i + 1, remaining - items[i].cents);\n                chosen.pop();\n                if (solutions.length >= maxSolutions) return;\n            }\n        };\n        search(0, target);\n        return { searched: true, itemCount: items.length, solutions: solutions };\n    },\n\n    // Records one combination as selected candidates, or several as\n    // unselected, ranked candidates (rank = combination number) for review.\n    recordCombinationCandidates: function(paymentSysId, customerSysId, solutions, selected) {\n        for (var s = 0; s < solutions.length; s++) {\n            for (var i = 0; i < solutions[s].length; i++) {\n                this._recordMatchCandidate(paymentSysId, solutions[s][i].sysId, customerSysId, 'combination', selected ? 1.0 : 0.5, s + 1, !!selected);\n            }\n        }\n    },\n\n    // Phase 14: deterministic suggestion for a short-pay residual, for the\n    // reviewer to confirm. A unique open credit note of the customer for\n    // exactly the residual suggests credit-note netting; otherwise a residual\n    // up to ar.bank_charge.max_amount suggests a bank charge. Never applied\n    // automatically.\n    classifyResidual: function(paymentSysId, residual) {\n        residual = Math.round(parseFloat(residual || '0') * 100) / 100;\n        if (residual <= 0.01) return { type: null };\n        var payment = new GlideRecord('x_695068_bcfa_payment');\n        if (!payment.get(paymentSysId)) return { type: null };\n\n        if (payment.getValue('customer')) {\n            var matches = [];\n            var note = new GlideRecord('x_695068_bcfa_credit_note');\n            note.addQuery('customer', payment.getValue('customer'));\n            note.addQuery('status', 'open');\n            note.query();\n            while (note.next()) {\n                if (Math.abs(parseFloat(note.getValue('open_amount') || '0') - residual) <= 0.01) {\n                    matches.push({ sysId: note.getUniqueValue(), number: note.getValue('credit_note_number') });\n                }\n            }\n            if (matches.length === 1) {\n                return { type: 'credit_note_netting', creditNoteSysId: matches[0].sysId,\n                    rule: 'residual ' + residual + ' equals open credit note ' + matches[0].number + ' of the same customer' };\n            }\n        }\n        var bankChargeMax = new FinancePolicy().arBankChargeMax();\n        if (residual <= bankChargeMax) {\n            return { type: 'bank_charge', rule: 'residual ' + residual + ' is within the bank charge limit ' + bankChargeMax + ' (x_695068_bcfa.ar.bank_charge.max_amount)' };\n        }\n        return { type: null, rule: 'residual ' + residual + ' matches no open credit note and exceeds the bank charge limit ' + bankChargeMax };\n    },\n\n    _recordMatchCandidate: function(paymentSysId, arOpenItemSysId, customerSysId, matchType, confidence, rank, selected) {\n        var mc = new GlideRecord('x_695068_bcfa_match_candidate');\n        mc.initialize();\n        mc.setValue('payment', paymentSysId);\n        mc.setValue('ar_open_item', arOpenItemSysId);\n        if (customerSysId) mc.setValue('customer_candidate', customerSysId);\n        mc.setValue('match_type', matchType);\n        mc.setValue('confidence', confidence);\n        mc.setValue('rank', rank);\n        mc.setValue('selected', !!selected);\n        return mc.insert();\n    },\n\n    _vendorCountry: function(vendorSysId) {\n        if (!vendorSysId) return null;\n        var vendor = new GlideRecord('x_695068_bcfa_vendor');\n        if (vendor.get(vendorSysId)) return vendor.getValue('country');\n        return null;\n    },\n\n    _computeDuplicateKey: function(vendorSysId, invoiceNumber, grossAmount) {\n        return (vendorSysId || '') + '|' + (invoiceNumber || '') + '|' + (grossAmount || '');\n    },\n\n    _mergeTolerances: function(overrides, context) {\n        var merged = {};\n        var configured = {};\n        try {\n            configured = new FinancePolicy().apTolerances(context);\n        } catch (e) {\n            configured = {};\n        }\n        for (var k in this.DEFAULT_TOLERANCES) {\n            merged[k] = configured.hasOwnProperty(k) ? configured[k] : this.DEFAULT_TOLERANCES[k];\n        }\n        merged.source = configured.source || 'engine defaults';\n        if (overrides) {\n            for (var k2 in overrides) {\n                merged[k2] = overrides[k2];\n            }\n        }\n        return merged;\n    },\n\n    type: 'MatchingEngine'\n};\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/MatchingEngine.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/MatchingEngine.server.js</sys_name>\n  </sys_module>\n</record_update>"},{"name":"sys_script_include_5d8f9a6cb8f340a49220bf64557ab807.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>5d8f9a6cb8f340a49220bf64557ab807</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_5d8f9a6cb8f340a49220bf64557ab807</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.ApDomainService</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Orchestrates the AP Invoice lifecycle (intake, extraction, validation, matching, exception resolution, approval, posting, Unknown Outcome reconciliation, archive) on top of the AP Invoice StateModel.</description>\n    <mobile_callable>false</mobile_callable>\n    <name>ApDomainService</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[// Orchestrates the AP Invoice lifecycle (Section 7 of the build brief) on\n// top of the AP Invoice StateModel. Each method performs the real\n// validation/matching/posting work FIRST, then moves the state field to\n// whichever transition that result legalizes — state progression is a\n// side effect of real logic running, never a bare status flip.\nvar ApDomainService = Class.create();\nApDomainService.prototype = {\n    initialize: function() {\n        this.auditEngine = new AuditEngine();\n        this.matchingEngine = new MatchingEngine();\n        this.exceptionEngine = new ExceptionEngine();\n        this.approvalEngine = new ApprovalEngine();\n        this.integrationService = new IntegrationService();\n        this.aiSimulation = new AISimulationService();\n        this.claudeClient = new BCClaudeClient();\n        this.policy = new FinancePolicy();\n    },\n\n    // Public entry point for the \"Explain with Now Assist\" UI Action on AP\n    // Exception: regenerates the advisory ai_recommendation on demand, as\n    // the current user. With the native provider it calls the published\n    // Now Assist skills through FinanceAgentTools (role-checked, advisory\n    // field only); other providers use the automatic path below.\n    explainException: function(apExceptionSysId) {\n        if (this.policy.aiProvider() !== 'native') return this._explainApException(apExceptionSysId);\n\n        var tools = new FinanceAgentTools();\n        var explanation = tools.explainApException(apExceptionSysId);\n        if (!explanation.ok) return explanation;\n        var recommendation = tools.recommendApNextAction(apExceptionSysId);\n        var note = 'AI REVIEW (advisory only - a human must decide)\\n\\nExplanation:\\n' + explanation.text +\n            (recommendation.ok ? '\\n\\nRecommended next action:\\n' + recommendation.text : '\\n\\nRecommended next action: not available (' + recommendation.error + ')');\n        var saved = tools.recordExceptionAdvice('ap', apExceptionSysId, note);\n        return saved.ok ? { ok: true, recommendation: note } : saved;\n    },\n\n    _setState: function(apInvoiceSysId, newState, correlationId, description) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return false;\n        var previous = invoice.getValue('state');\n        invoice.setValue('state', newState);\n        invoice.update();\n        this.auditEngine.logEvent({\n            correlationId: correlationId || invoice.getValue('correlation_id'),\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            eventType: 'state_transition',\n            actorType: 'system',\n            description: description || ('AP Invoice ' + previous + ' -> ' + newState),\n            beforeValue: { state: previous },\n            afterValue: { state: newState }\n        });\n        return true;\n    },\n\n    // Single entry point for the fully-automated portion of the pipeline\n    // (Section 7 items 1-14): intake through matching, stopping naturally at\n    // whichever state the deterministic logic reaches (MATCHED or\n    // EXCEPTION). This is the \"flow\" for automated intake — see\n    // docs/ARTIFACT_STRATEGY.md's Stage 15 refinement for why this is a\n    // direct call chain rather than a Flow Designer flow.\n    // fields.lines (optional): invoice lines (attachInvoiceLine field shape)\n    // attached before extraction and matching, so the 3-way match sees them.\n    intakeAndAutoProcess: function(fields) {\n        var intake = this.intakeInvoice(fields);\n        var lines = fields.lines || [];\n        for (var i = 0; i < lines.length; i++) this.attachInvoiceLine(intake.apInvoiceSysId, lines[i]);\n        this.runExtraction(intake.apInvoiceSysId, fields.seedExtraction || {}, fields.extractionOptions);\n        var validation = this.validateInvoice(intake.apInvoiceSysId);\n        if (!validation.validated) {\n            return { apInvoiceSysId: intake.apInvoiceSysId, stoppedAt: 'VALIDATION_EXCEPTION', detail: validation };\n        }\n        var match = this.matchInvoice(intake.apInvoiceSysId);\n        if (!match.matched) {\n            return { apInvoiceSysId: intake.apInvoiceSysId, stoppedAt: 'MATCH_EXCEPTION', detail: match };\n        }\n        return { apInvoiceSysId: intake.apInvoiceSysId, stoppedAt: 'MATCHED', detail: match };\n    },\n\n    intakeInvoice: function(fields) {\n        var correlationId = fields.correlationId || gs.generateGUID();\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        invoice.initialize();\n        invoice.setValue('invoice_number', fields.invoiceNumber);\n        if (fields.vendor) invoice.setValue('vendor', fields.vendor);\n        invoice.setValue('company_code', fields.companyCode || '');\n        invoice.setValue('currency', fields.currency || '');\n        if (fields.invoiceDate) invoice.setValue('invoice_date', fields.invoiceDate);\n        if (fields.purchaseOrder) invoice.setValue('purchase_order', fields.purchaseOrder);\n        if (fields.salesOrderReference) invoice.setValue('sales_order_reference', fields.salesOrderReference);\n        invoice.setValue('gross_amount', fields.grossAmount || 0);\n        invoice.setValue('tax_amount', fields.taxAmount || 0);\n        invoice.setValue('net_amount', fields.netAmount || 0);\n        invoice.setValue('source', fields.source || 'email');\n        invoice.setValue('correlation_id', correlationId);\n        if (fields.externalReference) invoice.setValue('external_reference', fields.externalReference);\n        invoice.setValue('state', 'RECEIVED');\n        invoice.setValue('approval_state', 'not_required');\n        invoice.setValue('posting_state', 'not_posted');\n        var sysId = invoice.insert();\n\n        this.auditEngine.logEvent({\n            correlationId: correlationId,\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: sysId,\n            eventType: 'state_transition',\n            description: 'AP Invoice received (intake)',\n            afterValue: { state: 'RECEIVED' }\n        });\n        return { apInvoiceSysId: sysId, correlationId: correlationId };\n    },\n\n    // Creates one AP Invoice Line row. Previously this was only ever done as\n    // a raw GlideRecord insert inline inside DemoDataSeeder — this method\n    // encapsulates the same shape as a proper, reusable service call so\n    // FinanceDocumentIntakeService (and any future caller) doesn't have to\n    // reach around ApDomainService to create a line. Deliberately dumb: it\n    // only writes fields it is given — po_line/receipt_reference resolution\n    // is the caller's job (deterministic line-matching lives in\n    // ApLineResolutionService, not here), matching the existing separation\n    // where ApDomainService orchestrates state and MatchingEngine owns\n    // tolerance evaluation.\n    attachInvoiceLine: function(apInvoiceSysId, fields) {\n        var line = new GlideRecord('x_695068_bcfa_ap_invoice_line');\n        line.initialize();\n        line.setValue('ap_invoice', apInvoiceSysId);\n        line.setValue('line_number', fields.lineNumber || 1);\n        line.setValue('material_or_service', fields.materialOrService || '');\n        line.setValue('quantity', fields.quantity || 0);\n        line.setValue('unit', fields.unit || '');\n        line.setValue('unit_price', fields.unitPrice || 0);\n        line.setValue('tax', fields.tax || 0);\n        line.setValue('amount', fields.amount || 0);\n        if (fields.poLine) line.setValue('po_line', fields.poLine);\n        if (fields.receiptReference) line.setValue('receipt_reference', fields.receiptReference);\n        return line.insert();\n    },\n\n    // seedFields stands in for whatever partial, as-if-OCR'd fields a real\n    // extraction step would have produced. With the native provider (the\n    // default) this is the deterministic simulated extraction\n    // (AISimulationService): Document Intelligence extraction is not\n    // licensed on this instance (see docs/CONTENT_UNDERSTANDING.md). Claude\n    // is only used when x_695068_bcfa.ai.provider = claude (legacy, removed\n    // in Phase 34). Extraction never blocks the pipeline on an AI outage.\n    runExtraction: function(apInvoiceSysId, seedFields, options) {\n        this._setState(apInvoiceSysId, 'EXTRACTING', null, 'Beginning extraction');\n        var claudeResult = this.policy.aiProvider() === 'claude' ? this._runClaudeExtraction(apInvoiceSysId, seedFields, options) : null;\n        var result = claudeResult || this.aiSimulation.simulateApExtraction(apInvoiceSysId, seedFields, options);\n        this._setState(apInvoiceSysId, 'EXTRACTED', null, 'Extraction complete, confidence ' + result.confidence);\n        return result;\n    },\n\n    // Returns a simulateApExtraction()-shaped result on success, or null if\n    // Claude is disabled/unavailable/invalid so the caller falls back.\n    _runClaudeExtraction: function(apInvoiceSysId, seedFields, options) {\n        if (!this.claudeClient.isEnabled()) return null;\n\n        var envelope = this.claudeClient.extractInvoice(apInvoiceSysId, seedFields);\n        if (!envelope.ok) return null;\n\n        var data = envelope.data;\n        var forcedConfidence = options && options.forceConfidence !== undefined ? options.forceConfidence : null;\n        var confidence = forcedConfidence !== null ? forcedConfidence : data.confidence;\n        var requiresReview = confidence < this.policy.extractionConfidenceThreshold();\n\n        var extraction = new GlideRecord('x_695068_bcfa_ap_extraction');\n        extraction.initialize();\n        extraction.setValue('ap_invoice', apInvoiceSysId);\n        extraction.setValue('extracted_fields', JSON.stringify(data));\n        extraction.setValue('confidence', confidence);\n        extraction.setValue('source', 'claude_document_intelligence');\n        extraction.setValue('requires_review', requiresReview);\n        var extractionSysId = extraction.insert();\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (invoice.get(apInvoiceSysId)) {\n            invoice.setValue('extraction_confidence', confidence);\n            invoice.update();\n        }\n\n        this.auditEngine.logEvent({\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            eventType: 'ai_recommendation',\n            actorType: 'claude_ai',\n            description: 'Claude invoice extraction, confidence ' + confidence + (data.warnings && data.warnings.length ? '; warnings: ' + data.warnings.join('; ') : ''),\n            afterValue: { confidence: confidence, requiresReview: requiresReview }\n        });\n\n        return { extractionSysId: extractionSysId, confidence: confidence, requiresReview: requiresReview };\n    },\n\n    validateInvoice: function(apInvoiceSysId) {\n        this._setState(apInvoiceSysId, 'VALIDATING', null, 'Running mandatory-field/vendor/PO/confidence validation');\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n\n        var extraction = new GlideRecord('x_695068_bcfa_ap_extraction');\n        extraction.addQuery('ap_invoice', apInvoiceSysId);\n        extraction.orderByDesc('sys_created_on');\n        extraction.setLimit(1);\n        extraction.query();\n        var confidence = extraction.next() ? parseFloat(extraction.getValue('confidence') || '1') : 1;\n\n        var confidenceThreshold = this.policy.extractionConfidenceThreshold();\n        var failure = null;\n        if (confidence < confidenceThreshold) {\n            failure = { reasonCode: 'low_confidence', description: 'Extraction confidence ' + confidence + ' is below the ' + confidenceThreshold + ' review threshold (POC ASSUMPTION).' };\n        } else if (!invoice.getValue('invoice_number') || !invoice.getValue('vendor') || !invoice.getValue('gross_amount')) {\n            failure = { reasonCode: 'missing_field', description: 'One or more mandatory fields (invoice number, vendor, gross amount) are missing.' };\n        } else {\n            var vendor = new GlideRecord('x_695068_bcfa_vendor');\n            if (!vendor.get(invoice.getValue('vendor')) || vendor.getValue('active') !== '1') {\n                failure = { reasonCode: 'vendor_invalid', description: 'Vendor could not be resolved to an active master record.' };\n            } else {\n                // PO exists, belongs to this vendor and is not closed (Phase 14).\n                var poCheck = this.matchingEngine.validatePurchaseOrder(apInvoiceSysId);\n                if (!poCheck.ok) failure = { reasonCode: poCheck.reasonCode, description: poCheck.description };\n            }\n        }\n\n        if (failure) {\n            var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, failure.reasonCode, failure.description, {\n                ruleResult: 'FAIL validation: ' + failure.description,\n                evidence: 'Extraction confidence: ' + confidence + ' (threshold ' + confidenceThreshold + ')\\n' +\n                    'Invoice number: ' + (invoice.getValue('invoice_number') || 'missing') + '\\n' +\n                    'Vendor: ' + (invoice.getDisplayValue('vendor') || 'missing') + '\\n' +\n                    'Gross amount: ' + (invoice.getValue('gross_amount') || 'missing') + ' ' + invoice.getValue('currency') + '\\n' +\n                    'Purchase order: ' + (invoice.getDisplayValue('purchase_order') || invoice.getValue('purchase_order') || 'none')\n            });\n            this._explainApException(exceptionSysId);\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Validation failed: ' + failure.reasonCode);\n            return { validated: false, reasonCode: failure.reasonCode, exceptionSysId: exceptionSysId };\n        }\n\n        this._setState(apInvoiceSysId, 'VALIDATED', null, 'Validation passed');\n        return { validated: true };\n    },\n\n    matchInvoice: function(apInvoiceSysId) {\n        this._setState(apInvoiceSysId, 'MATCHING', null, 'Running duplicate detection and 3-way match');\n\n        var duplicateResult = this.matchingEngine.detectDuplicateInvoice(apInvoiceSysId);\n        if (duplicateResult.duplicate) {\n            var original = new GlideRecord('x_695068_bcfa_ap_invoice');\n            original.get(duplicateResult.matchedInvoiceSysId);\n            var thisInvoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n            thisInvoice.get(apInvoiceSysId);\n            var dupExceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'duplicate', 'Duplicate of AP Invoice ' + duplicateResult.matchedInvoiceSysId, {\n                ruleResult: duplicateResult.sameAmount\n                    ? 'FAIL duplicate check: same vendor, invoice number and gross amount as AP invoice ' + original.getValue('invoice_number') + ' (state ' + original.getValue('state') + ').'\n                    : 'FAIL duplicate check: same vendor and invoice number as AP invoice ' + original.getValue('invoice_number') + ' (state ' + original.getValue('state') +\n                        ') but a different gross amount (' + thisInvoice.getValue('gross_amount') + ' vs ' + duplicateResult.matchedGross + '): possible re-bill or correction; confirm with the vendor.',\n                evidence: 'Vendor: ' + thisInvoice.getDisplayValue('vendor') + '; invoice number ' + thisInvoice.getValue('invoice_number') +\n                    ' (normalized ' + this.matchingEngine.normalizeInvoiceNumber(thisInvoice.getValue('invoice_number')) + ')' +\n                    '\\nExisting invoice: ' + original.getValue('invoice_number') + ', sys_id ' + duplicateResult.matchedInvoiceSysId + ', gross ' + duplicateResult.matchedGross +\n                    ', state ' + original.getValue('state') + ', SAP document ' + (original.getValue('sap_document_id') || 'none') +\n                    '\\nThis invoice: gross ' + thisInvoice.getValue('gross_amount') + ' ' + thisInvoice.getValue('currency')\n            });\n            this._explainApException(dupExceptionSysId);\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Duplicate invoice detected');\n            return { matched: false, reasonCode: 'duplicate', exceptionSysId: dupExceptionSysId };\n        }\n\n        var match = this.matchingEngine.threeWayMatch(apInvoiceSysId);\n        if (!match.withinTolerance) {\n            // One reason per exception, in order of what a reviewer must\n            // fix first: PO linkage, receipt, quantity, price, tax, totals.\n            var tolerances = match.tolerancesUsed;\n            var reasonCode = 'line_total_mismatch';\n            if (match.linkIssues.length) reasonCode = 'po_mismatch';\n            else if (match.receiptIssues.length) reasonCode = 'grn_missing';\n            else if (match.quantityVariancePct > tolerances.quantityPct) reasonCode = 'quantity_tolerance';\n            else if (match.priceVariancePct > tolerances.pricePct) reasonCode = 'price_tolerance';\n            else if (!match.taxWithinTolerance) reasonCode = 'tax_validation';\n            var exceptionSysId2 = this.exceptionEngine.createApException(apInvoiceSysId, reasonCode,\n                'Match result: ' + match.matchResult + '. Quantity variance ' + (match.quantityVariancePct * 100).toFixed(1) + '%, price variance ' + (match.priceVariancePct * 100).toFixed(1) + '%.',\n                this._matchExceptionDetails(reasonCode, match));\n            this._explainApException(exceptionSysId2);\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Match failed: ' + reasonCode);\n            return { matched: false, reasonCode: reasonCode, exceptionSysId: exceptionSysId2, match: match };\n        }\n\n        this._setState(apInvoiceSysId, 'MATCHED', null, 'Matched within tolerance');\n        return { matched: true, match: match };\n    },\n\n    // Deterministic rule result, evidence and variance for a failed 3-way\n    // match: what the exception shows the reviewer and what the AI agents\n    // explain. Only facts the MatchingEngine computed; no AI.\n    _matchExceptionDetails: function(reasonCode, match) {\n        var t = match.tolerancesUsed;\n        var pct = function(v) { return (v * 100).toFixed(1) + '%'; };\n        var checks = [\n            'PO linkage ' + (match.linkIssues.length ? 'FAIL (' + match.linkIssues.join('; ') + ')' : 'pass'),\n            'receipt ' + (match.receiptIssues.length ? 'FAIL (' + match.receiptIssues.join('; ') + ')' : 'pass'),\n            'quantity ' + pct(match.quantityVariancePct) + ' vs tolerance ' + pct(t.quantityPct) + (match.quantityVariancePct > t.quantityPct ? ' FAIL' : ' pass'),\n            'price ' + pct(match.priceVariancePct) + ' vs tolerance ' + pct(t.pricePct) + (match.priceVariancePct > t.pricePct ? ' FAIL' : ' pass'),\n            'tax variance ' + match.taxVariance + (match.taxWithinTolerance ? ' pass' : ' FAIL'),\n            'line total ' + match.lineTotal + ' vs net ' + match.netAmount + (match.lineTotalOk ? ' pass' : ' FAIL (difference ' + match.lineTotalDifference + ')')\n        ];\n        var evidence = [];\n        for (var i = 0; i < match.lines.length; i++) {\n            var l = match.lines[i];\n            evidence.push('Line ' + l.lineNumber + ': invoice qty ' + l.invoiceQuantity + ' at ' + l.invoiceUnitPrice +\n                '; PO ' + (l.poNumber || 'not linked') + (l.poQuantity !== null ? ' qty ' + l.poQuantity + ' at ' + l.poUnitPrice : '') +\n                '; GRN ' + (l.receiptNumber || 'not linked') + (l.receiptQuantity !== null ? ' qty ' + l.receiptQuantity : ''));\n        }\n        evidence.push('Net ' + match.netAmount + ', tax ' + match.taxAmount +\n            (match.expectedTax !== null ? ', expected tax ' + match.expectedTax + ' (' + match.vendorCountry + ' rate ' + pct(match.expectedTaxRate) + ')' : ', no expected tax rate for vendor country'));\n        evidence.push('Tolerances (POC ASSUMPTION) from ' + (t.source || 'x_695068_bcfa.ap.tolerance.* properties') + '.');\n\n        var varianceAmount = match.priceVarianceValue;\n        var variancePct = match.priceVariancePct;\n        if (reasonCode === 'quantity_tolerance') {\n            varianceAmount = match.quantityVarianceValue;\n            variancePct = match.quantityVariancePct;\n        } else if (reasonCode === 'tax_validation') {\n            varianceAmount = match.taxVariance;\n            variancePct = match.expectedTax ? match.taxVariance / match.expectedTax : 0;\n        } else if (reasonCode === 'line_total_mismatch') {\n            varianceAmount = match.lineTotalDifference;\n            variancePct = match.netAmount ? match.lineTotalDifference / match.netAmount : 0;\n        } else if (reasonCode === 'po_mismatch' || reasonCode === 'grn_missing') {\n            varianceAmount = null;\n            variancePct = null;\n        }\n        return {\n            ruleResult: 'FAIL 3-way match (' + reasonCode + '): ' + checks.join('; ') + '.',\n            evidence: evidence.join('\\n'),\n            varianceAmount: varianceAmount,\n            variancePct: variancePct\n        };\n    },\n\n    // Applies the configured approval rule to a MATCHED invoice: either\n    // requests human approval (requester = requestedBy) or, when the gross\n    // amount is within the configured auto-approve limit, records a\n    // rule-based approval. Either way posting only happens through the\n    // approval cascade and IntegrationService.\n    // Phase 15: the BCFA AP Approval decision table decides whether approval\n    // is needed and which group approves (inputs: amount, exception type,\n    // variance %, company). context (optional): { exceptionType, variancePct }\n    // for an invoice approved after an exception; a clean invoice is 'none'.\n    routeForApproval: function(apInvoiceSysId, requestedBy, context) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n        context = context || {};\n        var rule = this.policy.apApprovalDecision({\n            amount: parseFloat(invoice.getValue('gross_amount') || '0'),\n            exceptionType: context.exceptionType || 'none',\n            variancePct: context.variancePct || 0,\n            company: invoice.getValue('company_code')\n        });\n        this.auditEngine.logEvent({\n            correlationId: invoice.getValue('correlation_id'),\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            eventType: 'approval_decision',\n            actorType: 'system',\n            description: 'Approval rule evaluated (POC ASSUMPTION): ' + rule.rule,\n            afterValue: rule\n        });\n        var approval = this.requestApproval(apInvoiceSysId, requestedBy, rule.group);\n        if (rule.required) return { approvalRequired: true, approvalSysId: approval.approvalSysId, rule: rule.rule };\n        var decision = this.decideApproval(apInvoiceSysId, approval.approvalSysId, 'approved', null, 'Approved by configured rule: ' + rule.rule);\n        return { approvalRequired: false, approvalSysId: approval.approvalSysId, rule: rule.rule, decision: decision };\n    },\n\n    // Advisory explanation for a newly raised exception (ai_recommendation,\n    // never read by any deterministic rule or approval/posting logic).\n    // native (default): nothing runs here. The BCFA AP Invoice Review\n    // agentic workflow is triggered by the exception's creation, runs as\n    // the AI user and saves its note asynchronously.\n    // claude (legacy): Claude, falling back to the simulation.\n    // simulated: deterministic templated explanation only.\n    _explainApException: function(exceptionSysId) {\n        var provider = this.policy.aiProvider();\n        if (provider === 'native') {\n            this.auditEngine.logEvent({\n                sourceTable: 'x_695068_bcfa_ap_exception',\n                sourceRecord: exceptionSysId,\n                eventType: 'ai_recommendation',\n                actorType: 'system',\n                description: 'AI review handed to the BCFA AP Invoice Review agentic workflow (Now Assist), which starts on exception creation and records an advisory note.'\n            });\n            return { deferred: true, workflow: 'BCFA AP Invoice Review' };\n        }\n        if (provider === 'claude' && this.claudeClient.isEnabled()) {\n            var envelope = this.claudeClient.explainInvoiceException(exceptionSysId);\n            if (envelope.ok && !envelope.data.insufficient_information) {\n                var recommendation = envelope.data.explanation +\n                    (envelope.data.recommended_action ? ' Recommended next step: ' + envelope.data.recommended_action : '') +\n                    (envelope.data.evidence && envelope.data.evidence.length ? ' Evidence: ' + envelope.data.evidence.join('; ') + '.' : '');\n                var exception = new GlideRecord('x_695068_bcfa_ap_exception');\n                if (exception.get(exceptionSysId)) {\n                    exception.setValue('ai_recommendation', recommendation);\n                    exception.update();\n                }\n                this.auditEngine.logEvent({\n                    sourceTable: 'x_695068_bcfa_ap_exception',\n                    sourceRecord: exceptionSysId,\n                    eventType: 'ai_recommendation',\n                    actorType: 'claude_ai',\n                    description: 'Claude exception explanation, confidence ' + envelope.data.confidence,\n                    afterValue: { recommendation: recommendation }\n                });\n                return { recommendation: recommendation };\n            }\n        }\n        return this.aiSimulation.recommendApExceptionResolution(exceptionSysId);\n    },\n\n    // Reviewer correction: resolve the exception, then loop back to\n    // re-validate and rematch from scratch (Section 7 items 16-17). If the\n    // corrected invoice now matches, the configured approval rule applies.\n    resolveExceptionAndRetry: function(apInvoiceSysId, exceptionSysId, resolutionNotes, resolvedBy) {\n        this._setState(apInvoiceSysId, 'RESOLUTION', null, 'Reviewer resolving exception');\n        this.exceptionEngine.resolveApException(exceptionSysId, resolutionNotes, resolvedBy);\n        this._setState(apInvoiceSysId, 'VALIDATING', null, 'Re-validating after correction');\n        var validation = this.validateInvoice(apInvoiceSysId);\n        if (!validation.validated) return validation;\n        var match = this.matchInvoice(apInvoiceSysId);\n        if (!match.matched) return match;\n        match.approval = this.routeForApproval(apInvoiceSysId, resolvedBy);\n        return match;\n    },\n\n    requestApproval: function(apInvoiceSysId, requestedBy, approvalGroup) {\n        this._setState(apInvoiceSysId, 'PENDING_APPROVAL', null, 'Requesting posting approval');\n        var approvalSysId = this.approvalEngine.requestApInvoiceApproval(apInvoiceSysId, requestedBy, approvalGroup);\n        return { approvalSysId: approvalSysId };\n    },\n\n    // IMPORTANT ordering: `approvalEngine.decideApInvoiceApproval` sets\n    // approval_state = 'approved' and calls .update(), which fires the\n    // \"AP Invoice - Auto Post After Approval\" Business Rule SYNCHRONOUSLY\n    // (ServiceNow \"after\" business rules run in-line, not async) — by the\n    // time that call returns, the invoice may already be POSTING/POSTED/\n    // RECONCILED/CLOSED. The state must therefore already be 'APPROVED'\n    // *before* triggering that update, and this method must never set state\n    // again afterward — doing so previously clobbered whatever state the\n    // cascade had already legitimately advanced to.\n    decideApproval: function(apInvoiceSysId, approvalSysId, decision, approver, notes) {\n        if (decision === 'approved') {\n            this._setState(apInvoiceSysId, 'APPROVED', null, 'Approving — posting cascade will follow');\n        }\n\n        var result = this.approvalEngine.decideApInvoiceApproval(approvalSysId, decision, approver, notes);\n        if (result.error) {\n            if (decision === 'approved') {\n                this._setState(apInvoiceSysId, 'PENDING_APPROVAL', null, 'Approval rejected by service layer (segregation of duties)');\n            }\n            return result;\n        }\n\n        if (decision !== 'approved') {\n            var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'other', 'Approval rejected: ' + (notes || ''));\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Approval rejected');\n            result.exceptionSysId = exceptionSysId;\n        }\n        return result;\n    },\n\n    // Posting eligibility gate + mock SAP posting + Section 11 Unknown\n    // Outcome Control, all in one step since eligibility is enforced by the\n    // state machine itself (only reachable from APPROVED).\n    postInvoice: function(apInvoiceSysId, simulateOutcome) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n        if (invoice.getValue('approval_state') !== 'approved') {\n            return { error: 'Posting eligibility gate: AP Invoice has not been approved.' };\n        }\n\n        this._setState(apInvoiceSysId, 'POSTING', null, 'Invoking mock SAP posting');\n        invoice.setValue('posting_state', 'posting');\n        invoice.update();\n\n        var idempotencyKey = 'AP-POST-' + apInvoiceSysId;\n        var result = this.integrationService.execute({\n            operation: 'postVendorInvoice',\n            adapter: 'mock_sap',\n            correlationId: invoice.getValue('correlation_id'),\n            idempotencyKey: idempotencyKey,\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            payload: { invoiceNumber: invoice.getValue('invoice_number'), vendor: invoice.getValue('vendor'), amount: invoice.getValue('net_amount') },\n            simulateOutcome: simulateOutcome\n        });\n\n        return this._applyPostingResult(apInvoiceSysId, result);\n    },\n\n    _applyPostingResult: function(apInvoiceSysId, result) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        invoice.get(apInvoiceSysId);\n\n        if (result.status === 'success') {\n            invoice.setValue('posting_state', 'posted');\n            if (result.response && result.response.sapDocumentId) invoice.setValue('sap_document_id', result.response.sapDocumentId);\n            invoice.update();\n            this._setState(apInvoiceSysId, 'POSTED', null, 'Posted to SAP (simulated): ' + (result.response ? result.response.sapDocumentId : ''));\n            this.reconcileAndClose(apInvoiceSysId);\n            return { posted: true, sapDocumentId: result.response ? result.response.sapDocumentId : null };\n        }\n\n        if (result.unknownOutcome) {\n            invoice.setValue('posting_state', 'unknown_outcome');\n            invoice.update();\n            this._setState(apInvoiceSysId, 'UNKNOWN_OUTCOME', null, 'Posting outcome unknown (timeout) — will query status before any retry, per Section 11.');\n            return { posted: false, unknownOutcome: true, transactionSysId: result.transactionSysId };\n        }\n\n        invoice.setValue('posting_state', 'failed');\n        invoice.update();\n        var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'other', 'SAP posting failed: ' + result.status);\n        this._setState(apInvoiceSysId, 'FAILED', null, 'Posting failed: ' + result.status);\n        return { posted: false, failed: true, reasonCode: result.status, exceptionSysId: exceptionSysId };\n    },\n\n    // Section 11 status-query step: never a blind retry. Resolves an\n    // UNKNOWN_OUTCOME invoice by asking the adapter for ground truth.\n    reconcilePosting: function(apInvoiceSysId, transactionSysId) {\n        var resolution = this.integrationService.reconcileUnknownOutcome(transactionSysId);\n\n        if (resolution.resolution === 'POSTED') {\n            var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n            invoice.get(apInvoiceSysId);\n            invoice.setValue('posting_state', 'posted');\n            invoice.setValue('sap_document_id', resolution.sapDocumentId);\n            invoice.update();\n            this._setState(apInvoiceSysId, 'POSTED', null, 'Reconciliation confirmed the posting committed: ' + resolution.sapDocumentId);\n            this.reconcileAndClose(apInvoiceSysId);\n            return { posted: true, sapDocumentId: resolution.sapDocumentId };\n        }\n\n        if (resolution.resolution === 'RETRY') {\n            this._setState(apInvoiceSysId, 'POSTING', null, 'Reconciliation confirmed nothing committed — safe to retry.');\n            return this.postInvoice(apInvoiceSysId);\n        }\n\n        var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'other', 'Integration exception: ' + resolution.reason);\n        this._setState(apInvoiceSysId, 'FAILED', null, 'Reconciliation could not confirm outcome — integration exception.');\n        return { posted: false, failed: true, exceptionSysId: exceptionSysId };\n    },\n\n    reconcileAndClose: function(apInvoiceSysId) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n\n        this.integrationService.execute({\n            operation: 'archive',\n            adapter: 'mock_archive',\n            correlationId: invoice.getValue('correlation_id'),\n            idempotencyKey: 'AP-ARCHIVE-' + apInvoiceSysId,\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            payload: { sourceTable: 'x_695068_bcfa_ap_invoice', sourceRecord: apInvoiceSysId, correlationId: invoice.getValue('correlation_id') }\n        });\n\n        this._setState(apInvoiceSysId, 'RECONCILED', null, 'Posting reconciled and archived');\n        this._setState(apInvoiceSysId, 'CLOSED', null, 'AP Invoice closed');\n        return { closed: true };\n    },\n\n    type: 'ApDomainService'\n};\n]]></script>\n    <sys_name>ApDomainService</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_e86ed0d384544abd95097dde0847f525.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>e86ed0d384544abd95097dde0847f525</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_e86ed0d384544abd95097dde0847f525</sys_update_name>\n    <content><![CDATA[// Orchestrates the AP Invoice lifecycle (Section 7 of the build brief) on\n// top of the AP Invoice StateModel. Each method performs the real\n// validation/matching/posting work FIRST, then moves the state field to\n// whichever transition that result legalizes — state progression is a\n// side effect of real logic running, never a bare status flip.\nvar ApDomainService = Class.create();\nApDomainService.prototype = {\n    initialize: function() {\n        this.auditEngine = new AuditEngine();\n        this.matchingEngine = new MatchingEngine();\n        this.exceptionEngine = new ExceptionEngine();\n        this.approvalEngine = new ApprovalEngine();\n        this.integrationService = new IntegrationService();\n        this.aiSimulation = new AISimulationService();\n        this.claudeClient = new BCClaudeClient();\n        this.policy = new FinancePolicy();\n    },\n\n    // Public entry point for the \"Explain with Now Assist\" UI Action on AP\n    // Exception: regenerates the advisory ai_recommendation on demand, as\n    // the current user. With the native provider it calls the published\n    // Now Assist skills through FinanceAgentTools (role-checked, advisory\n    // field only); other providers use the automatic path below.\n    explainException: function(apExceptionSysId) {\n        if (this.policy.aiProvider() !== 'native') return this._explainApException(apExceptionSysId);\n\n        var tools = new FinanceAgentTools();\n        var explanation = tools.explainApException(apExceptionSysId);\n        if (!explanation.ok) return explanation;\n        var recommendation = tools.recommendApNextAction(apExceptionSysId);\n        var note = 'AI REVIEW (advisory only - a human must decide)\\n\\nExplanation:\\n' + explanation.text +\n            (recommendation.ok ? '\\n\\nRecommended next action:\\n' + recommendation.text : '\\n\\nRecommended next action: not available (' + recommendation.error + ')');\n        var saved = tools.recordExceptionAdvice('ap', apExceptionSysId, note);\n        return saved.ok ? { ok: true, recommendation: note } : saved;\n    },\n\n    _setState: function(apInvoiceSysId, newState, correlationId, description) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return false;\n        var previous = invoice.getValue('state');\n        invoice.setValue('state', newState);\n        invoice.update();\n        this.auditEngine.logEvent({\n            correlationId: correlationId || invoice.getValue('correlation_id'),\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            eventType: 'state_transition',\n            actorType: 'system',\n            description: description || ('AP Invoice ' + previous + ' -> ' + newState),\n            beforeValue: { state: previous },\n            afterValue: { state: newState }\n        });\n        return true;\n    },\n\n    // Single entry point for the fully-automated portion of the pipeline\n    // (Section 7 items 1-14): intake through matching, stopping naturally at\n    // whichever state the deterministic logic reaches (MATCHED or\n    // EXCEPTION). This is the \"flow\" for automated intake — see\n    // docs/ARTIFACT_STRATEGY.md's Stage 15 refinement for why this is a\n    // direct call chain rather than a Flow Designer flow.\n    // fields.lines (optional): invoice lines (attachInvoiceLine field shape)\n    // attached before extraction and matching, so the 3-way match sees them.\n    intakeAndAutoProcess: function(fields) {\n        var intake = this.intakeInvoice(fields);\n        var lines = fields.lines || [];\n        for (var i = 0; i < lines.length; i++) this.attachInvoiceLine(intake.apInvoiceSysId, lines[i]);\n        this.runExtraction(intake.apInvoiceSysId, fields.seedExtraction || {}, fields.extractionOptions);\n        var validation = this.validateInvoice(intake.apInvoiceSysId);\n        if (!validation.validated) {\n            return { apInvoiceSysId: intake.apInvoiceSysId, stoppedAt: 'VALIDATION_EXCEPTION', detail: validation };\n        }\n        var match = this.matchInvoice(intake.apInvoiceSysId);\n        if (!match.matched) {\n            return { apInvoiceSysId: intake.apInvoiceSysId, stoppedAt: 'MATCH_EXCEPTION', detail: match };\n        }\n        return { apInvoiceSysId: intake.apInvoiceSysId, stoppedAt: 'MATCHED', detail: match };\n    },\n\n    intakeInvoice: function(fields) {\n        var correlationId = fields.correlationId || gs.generateGUID();\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        invoice.initialize();\n        invoice.setValue('invoice_number', fields.invoiceNumber);\n        if (fields.vendor) invoice.setValue('vendor', fields.vendor);\n        invoice.setValue('company_code', fields.companyCode || '');\n        invoice.setValue('currency', fields.currency || '');\n        if (fields.invoiceDate) invoice.setValue('invoice_date', fields.invoiceDate);\n        if (fields.purchaseOrder) invoice.setValue('purchase_order', fields.purchaseOrder);\n        if (fields.salesOrderReference) invoice.setValue('sales_order_reference', fields.salesOrderReference);\n        invoice.setValue('gross_amount', fields.grossAmount || 0);\n        invoice.setValue('tax_amount', fields.taxAmount || 0);\n        invoice.setValue('net_amount', fields.netAmount || 0);\n        invoice.setValue('source', fields.source || 'email');\n        invoice.setValue('correlation_id', correlationId);\n        if (fields.externalReference) invoice.setValue('external_reference', fields.externalReference);\n        invoice.setValue('state', 'RECEIVED');\n        invoice.setValue('approval_state', 'not_required');\n        invoice.setValue('posting_state', 'not_posted');\n        var sysId = invoice.insert();\n\n        this.auditEngine.logEvent({\n            correlationId: correlationId,\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: sysId,\n            eventType: 'state_transition',\n            description: 'AP Invoice received (intake)',\n            afterValue: { state: 'RECEIVED' }\n        });\n        return { apInvoiceSysId: sysId, correlationId: correlationId };\n    },\n\n    // Creates one AP Invoice Line row. Previously this was only ever done as\n    // a raw GlideRecord insert inline inside DemoDataSeeder — this method\n    // encapsulates the same shape as a proper, reusable service call so\n    // FinanceDocumentIntakeService (and any future caller) doesn't have to\n    // reach around ApDomainService to create a line. Deliberately dumb: it\n    // only writes fields it is given — po_line/receipt_reference resolution\n    // is the caller's job (deterministic line-matching lives in\n    // ApLineResolutionService, not here), matching the existing separation\n    // where ApDomainService orchestrates state and MatchingEngine owns\n    // tolerance evaluation.\n    attachInvoiceLine: function(apInvoiceSysId, fields) {\n        var line = new GlideRecord('x_695068_bcfa_ap_invoice_line');\n        line.initialize();\n        line.setValue('ap_invoice', apInvoiceSysId);\n        line.setValue('line_number', fields.lineNumber || 1);\n        line.setValue('material_or_service', fields.materialOrService || '');\n        line.setValue('quantity', fields.quantity || 0);\n        line.setValue('unit', fields.unit || '');\n        line.setValue('unit_price', fields.unitPrice || 0);\n        line.setValue('tax', fields.tax || 0);\n        line.setValue('amount', fields.amount || 0);\n        if (fields.poLine) line.setValue('po_line', fields.poLine);\n        if (fields.receiptReference) line.setValue('receipt_reference', fields.receiptReference);\n        return line.insert();\n    },\n\n    // seedFields stands in for whatever partial, as-if-OCR'd fields a real\n    // extraction step would have produced. With the native provider (the\n    // default) this is the deterministic simulated extraction\n    // (AISimulationService): Document Intelligence extraction is not\n    // licensed on this instance (see docs/CONTENT_UNDERSTANDING.md). Claude\n    // is only used when x_695068_bcfa.ai.provider = claude (legacy, removed\n    // in Phase 34). Extraction never blocks the pipeline on an AI outage.\n    runExtraction: function(apInvoiceSysId, seedFields, options) {\n        this._setState(apInvoiceSysId, 'EXTRACTING', null, 'Beginning extraction');\n        var claudeResult = this.policy.aiProvider() === 'claude' ? this._runClaudeExtraction(apInvoiceSysId, seedFields, options) : null;\n        var result = claudeResult || this.aiSimulation.simulateApExtraction(apInvoiceSysId, seedFields, options);\n        this._setState(apInvoiceSysId, 'EXTRACTED', null, 'Extraction complete, confidence ' + result.confidence);\n        return result;\n    },\n\n    // Returns a simulateApExtraction()-shaped result on success, or null if\n    // Claude is disabled/unavailable/invalid so the caller falls back.\n    _runClaudeExtraction: function(apInvoiceSysId, seedFields, options) {\n        if (!this.claudeClient.isEnabled()) return null;\n\n        var envelope = this.claudeClient.extractInvoice(apInvoiceSysId, seedFields);\n        if (!envelope.ok) return null;\n\n        var data = envelope.data;\n        var forcedConfidence = options && options.forceConfidence !== undefined ? options.forceConfidence : null;\n        var confidence = forcedConfidence !== null ? forcedConfidence : data.confidence;\n        var requiresReview = confidence < this.policy.extractionConfidenceThreshold();\n\n        var extraction = new GlideRecord('x_695068_bcfa_ap_extraction');\n        extraction.initialize();\n        extraction.setValue('ap_invoice', apInvoiceSysId);\n        extraction.setValue('extracted_fields', JSON.stringify(data));\n        extraction.setValue('confidence', confidence);\n        extraction.setValue('source', 'claude_document_intelligence');\n        extraction.setValue('requires_review', requiresReview);\n        var extractionSysId = extraction.insert();\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (invoice.get(apInvoiceSysId)) {\n            invoice.setValue('extraction_confidence', confidence);\n            invoice.update();\n        }\n\n        this.auditEngine.logEvent({\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            eventType: 'ai_recommendation',\n            actorType: 'claude_ai',\n            description: 'Claude invoice extraction, confidence ' + confidence + (data.warnings && data.warnings.length ? '; warnings: ' + data.warnings.join('; ') : ''),\n            afterValue: { confidence: confidence, requiresReview: requiresReview }\n        });\n\n        return { extractionSysId: extractionSysId, confidence: confidence, requiresReview: requiresReview };\n    },\n\n    validateInvoice: function(apInvoiceSysId) {\n        this._setState(apInvoiceSysId, 'VALIDATING', null, 'Running mandatory-field/vendor/PO/confidence validation');\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n\n        var extraction = new GlideRecord('x_695068_bcfa_ap_extraction');\n        extraction.addQuery('ap_invoice', apInvoiceSysId);\n        extraction.orderByDesc('sys_created_on');\n        extraction.setLimit(1);\n        extraction.query();\n        var confidence = extraction.next() ? parseFloat(extraction.getValue('confidence') || '1') : 1;\n\n        var confidenceThreshold = this.policy.extractionConfidenceThreshold();\n        var failure = null;\n        if (confidence < confidenceThreshold) {\n            failure = { reasonCode: 'low_confidence', description: 'Extraction confidence ' + confidence + ' is below the ' + confidenceThreshold + ' review threshold (POC ASSUMPTION).' };\n        } else if (!invoice.getValue('invoice_number') || !invoice.getValue('vendor') || !invoice.getValue('gross_amount')) {\n            failure = { reasonCode: 'missing_field', description: 'One or more mandatory fields (invoice number, vendor, gross amount) are missing.' };\n        } else {\n            var vendor = new GlideRecord('x_695068_bcfa_vendor');\n            if (!vendor.get(invoice.getValue('vendor')) || vendor.getValue('active') !== '1') {\n                failure = { reasonCode: 'vendor_invalid', description: 'Vendor could not be resolved to an active master record.' };\n            } else {\n                // PO exists, belongs to this vendor and is not closed (Phase 14).\n                var poCheck = this.matchingEngine.validatePurchaseOrder(apInvoiceSysId);\n                if (!poCheck.ok) failure = { reasonCode: poCheck.reasonCode, description: poCheck.description };\n            }\n        }\n\n        if (failure) {\n            var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, failure.reasonCode, failure.description, {\n                ruleResult: 'FAIL validation: ' + failure.description,\n                evidence: 'Extraction confidence: ' + confidence + ' (threshold ' + confidenceThreshold + ')\\n' +\n                    'Invoice number: ' + (invoice.getValue('invoice_number') || 'missing') + '\\n' +\n                    'Vendor: ' + (invoice.getDisplayValue('vendor') || 'missing') + '\\n' +\n                    'Gross amount: ' + (invoice.getValue('gross_amount') || 'missing') + ' ' + invoice.getValue('currency') + '\\n' +\n                    'Purchase order: ' + (invoice.getDisplayValue('purchase_order') || invoice.getValue('purchase_order') || 'none')\n            });\n            this._explainApException(exceptionSysId);\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Validation failed: ' + failure.reasonCode);\n            return { validated: false, reasonCode: failure.reasonCode, exceptionSysId: exceptionSysId };\n        }\n\n        this._setState(apInvoiceSysId, 'VALIDATED', null, 'Validation passed');\n        return { validated: true };\n    },\n\n    matchInvoice: function(apInvoiceSysId) {\n        this._setState(apInvoiceSysId, 'MATCHING', null, 'Running duplicate detection and 3-way match');\n\n        var duplicateResult = this.matchingEngine.detectDuplicateInvoice(apInvoiceSysId);\n        if (duplicateResult.duplicate) {\n            var original = new GlideRecord('x_695068_bcfa_ap_invoice');\n            original.get(duplicateResult.matchedInvoiceSysId);\n            var thisInvoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n            thisInvoice.get(apInvoiceSysId);\n            var dupExceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'duplicate', 'Duplicate of AP Invoice ' + duplicateResult.matchedInvoiceSysId, {\n                ruleResult: duplicateResult.sameAmount\n                    ? 'FAIL duplicate check: same vendor, invoice number and gross amount as AP invoice ' + original.getValue('invoice_number') + ' (state ' + original.getValue('state') + ').'\n                    : 'FAIL duplicate check: same vendor and invoice number as AP invoice ' + original.getValue('invoice_number') + ' (state ' + original.getValue('state') +\n                        ') but a different gross amount (' + thisInvoice.getValue('gross_amount') + ' vs ' + duplicateResult.matchedGross + '): possible re-bill or correction; confirm with the vendor.',\n                evidence: 'Vendor: ' + thisInvoice.getDisplayValue('vendor') + '; invoice number ' + thisInvoice.getValue('invoice_number') +\n                    ' (normalized ' + this.matchingEngine.normalizeInvoiceNumber(thisInvoice.getValue('invoice_number')) + ')' +\n                    '\\nExisting invoice: ' + original.getValue('invoice_number') + ', sys_id ' + duplicateResult.matchedInvoiceSysId + ', gross ' + duplicateResult.matchedGross +\n                    ', state ' + original.getValue('state') + ', SAP document ' + (original.getValue('sap_document_id') || 'none') +\n                    '\\nThis invoice: gross ' + thisInvoice.getValue('gross_amount') + ' ' + thisInvoice.getValue('currency')\n            });\n            this._explainApException(dupExceptionSysId);\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Duplicate invoice detected');\n            return { matched: false, reasonCode: 'duplicate', exceptionSysId: dupExceptionSysId };\n        }\n\n        var match = this.matchingEngine.threeWayMatch(apInvoiceSysId);\n        if (!match.withinTolerance) {\n            // One reason per exception, in order of what a reviewer must\n            // fix first: PO linkage, receipt, quantity, price, tax, totals.\n            var tolerances = match.tolerancesUsed;\n            var reasonCode = 'line_total_mismatch';\n            if (match.linkIssues.length) reasonCode = 'po_mismatch';\n            else if (match.receiptIssues.length) reasonCode = 'grn_missing';\n            else if (match.quantityVariancePct > tolerances.quantityPct) reasonCode = 'quantity_tolerance';\n            else if (match.priceVariancePct > tolerances.pricePct) reasonCode = 'price_tolerance';\n            else if (!match.taxWithinTolerance) reasonCode = 'tax_validation';\n            var exceptionSysId2 = this.exceptionEngine.createApException(apInvoiceSysId, reasonCode,\n                'Match result: ' + match.matchResult + '. Quantity variance ' + (match.quantityVariancePct * 100).toFixed(1) + '%, price variance ' + (match.priceVariancePct * 100).toFixed(1) + '%.',\n                this._matchExceptionDetails(reasonCode, match));\n            this._explainApException(exceptionSysId2);\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Match failed: ' + reasonCode);\n            return { matched: false, reasonCode: reasonCode, exceptionSysId: exceptionSysId2, match: match };\n        }\n\n        this._setState(apInvoiceSysId, 'MATCHED', null, 'Matched within tolerance');\n        return { matched: true, match: match };\n    },\n\n    // Deterministic rule result, evidence and variance for a failed 3-way\n    // match: what the exception shows the reviewer and what the AI agents\n    // explain. Only facts the MatchingEngine computed; no AI.\n    _matchExceptionDetails: function(reasonCode, match) {\n        var t = match.tolerancesUsed;\n        var pct = function(v) { return (v * 100).toFixed(1) + '%'; };\n        var checks = [\n            'PO linkage ' + (match.linkIssues.length ? 'FAIL (' + match.linkIssues.join('; ') + ')' : 'pass'),\n            'receipt ' + (match.receiptIssues.length ? 'FAIL (' + match.receiptIssues.join('; ') + ')' : 'pass'),\n            'quantity ' + pct(match.quantityVariancePct) + ' vs tolerance ' + pct(t.quantityPct) + (match.quantityVariancePct > t.quantityPct ? ' FAIL' : ' pass'),\n            'price ' + pct(match.priceVariancePct) + ' vs tolerance ' + pct(t.pricePct) + (match.priceVariancePct > t.pricePct ? ' FAIL' : ' pass'),\n            'tax variance ' + match.taxVariance + (match.taxWithinTolerance ? ' pass' : ' FAIL'),\n            'line total ' + match.lineTotal + ' vs net ' + match.netAmount + (match.lineTotalOk ? ' pass' : ' FAIL (difference ' + match.lineTotalDifference + ')')\n        ];\n        var evidence = [];\n        for (var i = 0; i < match.lines.length; i++) {\n            var l = match.lines[i];\n            evidence.push('Line ' + l.lineNumber + ': invoice qty ' + l.invoiceQuantity + ' at ' + l.invoiceUnitPrice +\n                '; PO ' + (l.poNumber || 'not linked') + (l.poQuantity !== null ? ' qty ' + l.poQuantity + ' at ' + l.poUnitPrice : '') +\n                '; GRN ' + (l.receiptNumber || 'not linked') + (l.receiptQuantity !== null ? ' qty ' + l.receiptQuantity : ''));\n        }\n        evidence.push('Net ' + match.netAmount + ', tax ' + match.taxAmount +\n            (match.expectedTax !== null ? ', expected tax ' + match.expectedTax + ' (' + match.vendorCountry + ' rate ' + pct(match.expectedTaxRate) + ')' : ', no expected tax rate for vendor country'));\n        evidence.push('Tolerances (POC ASSUMPTION) from ' + (t.source || 'x_695068_bcfa.ap.tolerance.* properties') + '.');\n\n        var varianceAmount = match.priceVarianceValue;\n        var variancePct = match.priceVariancePct;\n        if (reasonCode === 'quantity_tolerance') {\n            varianceAmount = match.quantityVarianceValue;\n            variancePct = match.quantityVariancePct;\n        } else if (reasonCode === 'tax_validation') {\n            varianceAmount = match.taxVariance;\n            variancePct = match.expectedTax ? match.taxVariance / match.expectedTax : 0;\n        } else if (reasonCode === 'line_total_mismatch') {\n            varianceAmount = match.lineTotalDifference;\n            variancePct = match.netAmount ? match.lineTotalDifference / match.netAmount : 0;\n        } else if (reasonCode === 'po_mismatch' || reasonCode === 'grn_missing') {\n            varianceAmount = null;\n            variancePct = null;\n        }\n        return {\n            ruleResult: 'FAIL 3-way match (' + reasonCode + '): ' + checks.join('; ') + '.',\n            evidence: evidence.join('\\n'),\n            varianceAmount: varianceAmount,\n            variancePct: variancePct\n        };\n    },\n\n    // Applies the configured approval rule to a MATCHED invoice: either\n    // requests human approval (requester = requestedBy) or, when the gross\n    // amount is within the configured auto-approve limit, records a\n    // rule-based approval. Either way posting only happens through the\n    // approval cascade and IntegrationService.\n    // Phase 15: the BCFA AP Approval decision table decides whether approval\n    // is needed and which group approves (inputs: amount, exception type,\n    // variance %, company). context (optional): { exceptionType, variancePct }\n    // for an invoice approved after an exception; a clean invoice is 'none'.\n    routeForApproval: function(apInvoiceSysId, requestedBy, context) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n        context = context || {};\n        var rule = this.policy.apApprovalDecision({\n            amount: parseFloat(invoice.getValue('gross_amount') || '0'),\n            exceptionType: context.exceptionType || 'none',\n            variancePct: context.variancePct || 0,\n            company: invoice.getValue('company_code')\n        });\n        this.auditEngine.logEvent({\n            correlationId: invoice.getValue('correlation_id'),\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            eventType: 'approval_decision',\n            actorType: 'system',\n            description: 'Approval rule evaluated (POC ASSUMPTION): ' + rule.rule,\n            afterValue: rule\n        });\n        var approval = this.requestApproval(apInvoiceSysId, requestedBy, rule.group);\n        if (rule.required) return { approvalRequired: true, approvalSysId: approval.approvalSysId, rule: rule.rule };\n        var decision = this.decideApproval(apInvoiceSysId, approval.approvalSysId, 'approved', null, 'Approved by configured rule: ' + rule.rule);\n        return { approvalRequired: false, approvalSysId: approval.approvalSysId, rule: rule.rule, decision: decision };\n    },\n\n    // Advisory explanation for a newly raised exception (ai_recommendation,\n    // never read by any deterministic rule or approval/posting logic).\n    // native (default): nothing runs here. The BCFA AP Invoice Review\n    // agentic workflow is triggered by the exception's creation, runs as\n    // the AI user and saves its note asynchronously.\n    // claude (legacy): Claude, falling back to the simulation.\n    // simulated: deterministic templated explanation only.\n    _explainApException: function(exceptionSysId) {\n        var provider = this.policy.aiProvider();\n        if (provider === 'native') {\n            this.auditEngine.logEvent({\n                sourceTable: 'x_695068_bcfa_ap_exception',\n                sourceRecord: exceptionSysId,\n                eventType: 'ai_recommendation',\n                actorType: 'system',\n                description: 'AI review handed to the BCFA AP Invoice Review agentic workflow (Now Assist), which starts on exception creation and records an advisory note.'\n            });\n            return { deferred: true, workflow: 'BCFA AP Invoice Review' };\n        }\n        if (provider === 'claude' && this.claudeClient.isEnabled()) {\n            var envelope = this.claudeClient.explainInvoiceException(exceptionSysId);\n            if (envelope.ok && !envelope.data.insufficient_information) {\n                var recommendation = envelope.data.explanation +\n                    (envelope.data.recommended_action ? ' Recommended next step: ' + envelope.data.recommended_action : '') +\n                    (envelope.data.evidence && envelope.data.evidence.length ? ' Evidence: ' + envelope.data.evidence.join('; ') + '.' : '');\n                var exception = new GlideRecord('x_695068_bcfa_ap_exception');\n                if (exception.get(exceptionSysId)) {\n                    exception.setValue('ai_recommendation', recommendation);\n                    exception.update();\n                }\n                this.auditEngine.logEvent({\n                    sourceTable: 'x_695068_bcfa_ap_exception',\n                    sourceRecord: exceptionSysId,\n                    eventType: 'ai_recommendation',\n                    actorType: 'claude_ai',\n                    description: 'Claude exception explanation, confidence ' + envelope.data.confidence,\n                    afterValue: { recommendation: recommendation }\n                });\n                return { recommendation: recommendation };\n            }\n        }\n        return this.aiSimulation.recommendApExceptionResolution(exceptionSysId);\n    },\n\n    // Reviewer correction: resolve the exception, then loop back to\n    // re-validate and rematch from scratch (Section 7 items 16-17). If the\n    // corrected invoice now matches, the configured approval rule applies.\n    resolveExceptionAndRetry: function(apInvoiceSysId, exceptionSysId, resolutionNotes, resolvedBy) {\n        this._setState(apInvoiceSysId, 'RESOLUTION', null, 'Reviewer resolving exception');\n        this.exceptionEngine.resolveApException(exceptionSysId, resolutionNotes, resolvedBy);\n        this._setState(apInvoiceSysId, 'VALIDATING', null, 'Re-validating after correction');\n        var validation = this.validateInvoice(apInvoiceSysId);\n        if (!validation.validated) return validation;\n        var match = this.matchInvoice(apInvoiceSysId);\n        if (!match.matched) return match;\n        match.approval = this.routeForApproval(apInvoiceSysId, resolvedBy);\n        return match;\n    },\n\n    requestApproval: function(apInvoiceSysId, requestedBy, approvalGroup) {\n        this._setState(apInvoiceSysId, 'PENDING_APPROVAL', null, 'Requesting posting approval');\n        var approvalSysId = this.approvalEngine.requestApInvoiceApproval(apInvoiceSysId, requestedBy, approvalGroup);\n        return { approvalSysId: approvalSysId };\n    },\n\n    // IMPORTANT ordering: `approvalEngine.decideApInvoiceApproval` sets\n    // approval_state = 'approved' and calls .update(), which fires the\n    // \"AP Invoice - Auto Post After Approval\" Business Rule SYNCHRONOUSLY\n    // (ServiceNow \"after\" business rules run in-line, not async) — by the\n    // time that call returns, the invoice may already be POSTING/POSTED/\n    // RECONCILED/CLOSED. The state must therefore already be 'APPROVED'\n    // *before* triggering that update, and this method must never set state\n    // again afterward — doing so previously clobbered whatever state the\n    // cascade had already legitimately advanced to.\n    decideApproval: function(apInvoiceSysId, approvalSysId, decision, approver, notes) {\n        if (decision === 'approved') {\n            this._setState(apInvoiceSysId, 'APPROVED', null, 'Approving — posting cascade will follow');\n        }\n\n        var result = this.approvalEngine.decideApInvoiceApproval(approvalSysId, decision, approver, notes);\n        if (result.error) {\n            if (decision === 'approved') {\n                this._setState(apInvoiceSysId, 'PENDING_APPROVAL', null, 'Approval rejected by service layer (segregation of duties)');\n            }\n            return result;\n        }\n\n        if (decision !== 'approved') {\n            var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'other', 'Approval rejected: ' + (notes || ''));\n            this._setState(apInvoiceSysId, 'EXCEPTION', null, 'Approval rejected');\n            result.exceptionSysId = exceptionSysId;\n        }\n        return result;\n    },\n\n    // Posting eligibility gate + mock SAP posting + Section 11 Unknown\n    // Outcome Control, all in one step since eligibility is enforced by the\n    // state machine itself (only reachable from APPROVED).\n    postInvoice: function(apInvoiceSysId, simulateOutcome) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n        if (invoice.getValue('approval_state') !== 'approved') {\n            return { error: 'Posting eligibility gate: AP Invoice has not been approved.' };\n        }\n\n        this._setState(apInvoiceSysId, 'POSTING', null, 'Invoking mock SAP posting');\n        invoice.setValue('posting_state', 'posting');\n        invoice.update();\n\n        var idempotencyKey = 'AP-POST-' + apInvoiceSysId;\n        var result = this.integrationService.execute({\n            operation: 'postVendorInvoice',\n            adapter: 'mock_sap',\n            correlationId: invoice.getValue('correlation_id'),\n            idempotencyKey: idempotencyKey,\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            payload: { invoiceNumber: invoice.getValue('invoice_number'), vendor: invoice.getValue('vendor'), amount: invoice.getValue('net_amount') },\n            simulateOutcome: simulateOutcome\n        });\n\n        return this._applyPostingResult(apInvoiceSysId, result);\n    },\n\n    _applyPostingResult: function(apInvoiceSysId, result) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        invoice.get(apInvoiceSysId);\n\n        if (result.status === 'success') {\n            invoice.setValue('posting_state', 'posted');\n            if (result.response && result.response.sapDocumentId) invoice.setValue('sap_document_id', result.response.sapDocumentId);\n            invoice.update();\n            this._setState(apInvoiceSysId, 'POSTED', null, 'Posted to SAP (simulated): ' + (result.response ? result.response.sapDocumentId : ''));\n            this.reconcileAndClose(apInvoiceSysId);\n            return { posted: true, sapDocumentId: result.response ? result.response.sapDocumentId : null };\n        }\n\n        if (result.unknownOutcome) {\n            invoice.setValue('posting_state', 'unknown_outcome');\n            invoice.update();\n            this._setState(apInvoiceSysId, 'UNKNOWN_OUTCOME', null, 'Posting outcome unknown (timeout) — will query status before any retry, per Section 11.');\n            return { posted: false, unknownOutcome: true, transactionSysId: result.transactionSysId };\n        }\n\n        invoice.setValue('posting_state', 'failed');\n        invoice.update();\n        var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'other', 'SAP posting failed: ' + result.status);\n        this._setState(apInvoiceSysId, 'FAILED', null, 'Posting failed: ' + result.status);\n        return { posted: false, failed: true, reasonCode: result.status, exceptionSysId: exceptionSysId };\n    },\n\n    // Section 11 status-query step: never a blind retry. Resolves an\n    // UNKNOWN_OUTCOME invoice by asking the adapter for ground truth.\n    reconcilePosting: function(apInvoiceSysId, transactionSysId) {\n        var resolution = this.integrationService.reconcileUnknownOutcome(transactionSysId);\n\n        if (resolution.resolution === 'POSTED') {\n            var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n            invoice.get(apInvoiceSysId);\n            invoice.setValue('posting_state', 'posted');\n            invoice.setValue('sap_document_id', resolution.sapDocumentId);\n            invoice.update();\n            this._setState(apInvoiceSysId, 'POSTED', null, 'Reconciliation confirmed the posting committed: ' + resolution.sapDocumentId);\n            this.reconcileAndClose(apInvoiceSysId);\n            return { posted: true, sapDocumentId: resolution.sapDocumentId };\n        }\n\n        if (resolution.resolution === 'RETRY') {\n            this._setState(apInvoiceSysId, 'POSTING', null, 'Reconciliation confirmed nothing committed — safe to retry.');\n            return this.postInvoice(apInvoiceSysId);\n        }\n\n        var exceptionSysId = this.exceptionEngine.createApException(apInvoiceSysId, 'other', 'Integration exception: ' + resolution.reason);\n        this._setState(apInvoiceSysId, 'FAILED', null, 'Reconciliation could not confirm outcome — integration exception.');\n        return { posted: false, failed: true, exceptionSysId: exceptionSysId };\n    },\n\n    reconcileAndClose: function(apInvoiceSysId) {\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(apInvoiceSysId)) return { error: 'AP Invoice not found' };\n\n        this.integrationService.execute({\n            operation: 'archive',\n            adapter: 'mock_archive',\n            correlationId: invoice.getValue('correlation_id'),\n            idempotencyKey: 'AP-ARCHIVE-' + apInvoiceSysId,\n            sourceTable: 'x_695068_bcfa_ap_invoice',\n            sourceRecord: apInvoiceSysId,\n            payload: { sourceTable: 'x_695068_bcfa_ap_invoice', sourceRecord: apInvoiceSysId, correlationId: invoice.getValue('correlation_id') }\n        });\n\n        this._setState(apInvoiceSysId, 'RECONCILED', null, 'Posting reconciled and archived');\n        this._setState(apInvoiceSysId, 'CLOSED', null, 'AP Invoice closed');\n        return { closed: true };\n    },\n\n    type: 'ApDomainService'\n};\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ApDomainService.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ApDomainService.server.js</sys_name>\n  </sys_module>\n</record_update>"},{"name":"sys_script_include_c08e2462cb5d47729ce0d53d8ef19e7d.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>c08e2462cb5d47729ce0d53d8ef19e7d</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_c08e2462cb5d47729ce0d53d8ef19e7d</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.ApprovalEngine</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Requests/decides AP and AR approvals, enforcing segregation of duties (no self-approval) as a service-layer mirror of the ACL rule.</description>\n    <mobile_callable>false</mobile_callable>\n    <name>ApprovalEngine</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[var ApprovalEngine = Class.create();\nApprovalEngine.prototype = {\n    initialize: function() {},\n\n    // approvalGroup (optional, Phase 15): the group the approval decision\n    // table routed this approval to. Recorded on the approval; membership is\n    // enforced from Phase 17.\n    requestApInvoiceApproval: function(apInvoiceSysId, requestedBy, approvalGroup) {\n        var approval = new GlideRecord('x_695068_bcfa_ap_approval');\n        approval.initialize();\n        approval.setValue('ap_invoice', apInvoiceSysId);\n        if (requestedBy) approval.setValue('requested_by', requestedBy);\n        if (approvalGroup) approval.setValue('approval_group', approvalGroup);\n        approval.setValue('decision', 'pending');\n        var sysId = approval.insert();\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (invoice.get(apInvoiceSysId)) {\n            invoice.setValue('approval_state', 'pending');\n            invoice.update();\n        }\n        return sysId;\n    },\n\n    // Defense-in-depth mirror of the ACL script on ap_approval.decision — the\n    // platform ACL is the enforcement point, but the service layer also\n    // refuses a self-approval so a caller never sees a misleading partial\n    // success.\n    decideApInvoiceApproval: function(approvalSysId, decision, approver, notes) {\n        var approval = new GlideRecord('x_695068_bcfa_ap_approval');\n        if (!approval.get(approvalSysId)) return { error: 'Approval not found' };\n        if (approval.getValue('requested_by') && approver && approval.getValue('requested_by') === approver) {\n            return { error: 'Segregation of duties violation: requester cannot approve their own transaction.' };\n        }\n        approval.setValue('decision', decision);\n        approval.setValue('decision_notes', notes || '');\n        if (approver) approval.setValue('approver', approver);\n        approval.setValue('decided_at', new GlideDateTime().getValue());\n        approval.update();\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (invoice.get(approval.getValue('ap_invoice'))) {\n            invoice.setValue('approval_state', decision === 'approved' ? 'approved' : 'rejected');\n            invoice.update();\n        }\n        return { success: true, decision: decision };\n    },\n\n    requestPaymentApproval: function(paymentSysId, requestedBy) {\n        var approval = new GlideRecord('x_695068_bcfa_ar_approval');\n        approval.initialize();\n        approval.setValue('payment', paymentSysId);\n        if (requestedBy) approval.setValue('requested_by', requestedBy);\n        approval.setValue('decision', 'pending');\n        return approval.insert();\n    },\n\n    decidePaymentApproval: function(approvalSysId, decision, approver, notes) {\n        var approval = new GlideRecord('x_695068_bcfa_ar_approval');\n        if (!approval.get(approvalSysId)) return { error: 'Approval not found' };\n        if (approval.getValue('requested_by') && approver && approval.getValue('requested_by') === approver) {\n            return { error: 'Segregation of duties violation: requester cannot approve their own transaction.' };\n        }\n        approval.setValue('decision', decision);\n        approval.setValue('decision_notes', notes || '');\n        if (approver) approval.setValue('approver', approver);\n        approval.setValue('decided_at', new GlideDateTime().getValue());\n        approval.update();\n        return { success: true, decision: decision };\n    },\n\n    type: 'ApprovalEngine'\n};\n]]></script>\n    <sys_name>ApprovalEngine</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_ce72a3660eb94cc0bf18e4083d7ac09a.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>ce72a3660eb94cc0bf18e4083d7ac09a</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_ce72a3660eb94cc0bf18e4083d7ac09a</sys_update_name>\n    <content><![CDATA[var ApprovalEngine = Class.create();\nApprovalEngine.prototype = {\n    initialize: function() {},\n\n    // approvalGroup (optional, Phase 15): the group the approval decision\n    // table routed this approval to. Recorded on the approval; membership is\n    // enforced from Phase 17.\n    requestApInvoiceApproval: function(apInvoiceSysId, requestedBy, approvalGroup) {\n        var approval = new GlideRecord('x_695068_bcfa_ap_approval');\n        approval.initialize();\n        approval.setValue('ap_invoice', apInvoiceSysId);\n        if (requestedBy) approval.setValue('requested_by', requestedBy);\n        if (approvalGroup) approval.setValue('approval_group', approvalGroup);\n        approval.setValue('decision', 'pending');\n        var sysId = approval.insert();\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (invoice.get(apInvoiceSysId)) {\n            invoice.setValue('approval_state', 'pending');\n            invoice.update();\n        }\n        return sysId;\n    },\n\n    // Defense-in-depth mirror of the ACL script on ap_approval.decision — the\n    // platform ACL is the enforcement point, but the service layer also\n    // refuses a self-approval so a caller never sees a misleading partial\n    // success.\n    decideApInvoiceApproval: function(approvalSysId, decision, approver, notes) {\n        var approval = new GlideRecord('x_695068_bcfa_ap_approval');\n        if (!approval.get(approvalSysId)) return { error: 'Approval not found' };\n        if (approval.getValue('requested_by') && approver && approval.getValue('requested_by') === approver) {\n            return { error: 'Segregation of duties violation: requester cannot approve their own transaction.' };\n        }\n        approval.setValue('decision', decision);\n        approval.setValue('decision_notes', notes || '');\n        if (approver) approval.setValue('approver', approver);\n        approval.setValue('decided_at', new GlideDateTime().getValue());\n        approval.update();\n\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (invoice.get(approval.getValue('ap_invoice'))) {\n            invoice.setValue('approval_state', decision === 'approved' ? 'approved' : 'rejected');\n            invoice.update();\n        }\n        return { success: true, decision: decision };\n    },\n\n    requestPaymentApproval: function(paymentSysId, requestedBy) {\n        var approval = new GlideRecord('x_695068_bcfa_ar_approval');\n        approval.initialize();\n        approval.setValue('payment', paymentSysId);\n        if (requestedBy) approval.setValue('requested_by', requestedBy);\n        approval.setValue('decision', 'pending');\n        return approval.insert();\n    },\n\n    decidePaymentApproval: function(approvalSysId, decision, approver, notes) {\n        var approval = new GlideRecord('x_695068_bcfa_ar_approval');\n        if (!approval.get(approvalSysId)) return { error: 'Approval not found' };\n        if (approval.getValue('requested_by') && approver && approval.getValue('requested_by') === approver) {\n            return { error: 'Segregation of duties violation: requester cannot approve their own transaction.' };\n        }\n        approval.setValue('decision', decision);\n        approval.setValue('decision_notes', notes || '');\n        if (approver) approval.setValue('approver', approver);\n        approval.setValue('decided_at', new GlideDateTime().getValue());\n        approval.update();\n        return { success: true, decision: decision };\n    },\n\n    type: 'ApprovalEngine'\n};\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ApprovalEngine.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ApprovalEngine.server.js</sys_name>\n  </sys_module>\n</record_update>"},{"name":"sys_script_include_4a2cc6ab28d94a348000ff074d255dac.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>4a2cc6ab28d94a348000ff074d255dac</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_4a2cc6ab28d94a348000ff074d255dac</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.ApExceptionDecisionService</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Records the human decision on an AP exception (approve override, reject, request correction, hold) with a mandatory reason, role checks and maker/checker. Approved overrides post through the approval cascade and IntegrationService. Never callable by AI.</description>\n    <mobile_callable>false</mobile_callable>\n    <name>ApExceptionDecisionService</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[// Phase 12: the human decision on an AP exception. A finance user chooses\n// one of four outcomes and must give a reason:\n//   approve_override   finance approver accepts the variance; the invoice\n//                      goes through approval (maker/checker) and posts via\n//                      the approval cascade -> IntegrationService -> Mock SAP\n//   reject             the invoice is rejected and will not be paid\n//   request_correction the invoice waits (ON_HOLD) for a corrected invoice\n//                      or credit note; then \"Resolve & Retry\" re-runs it\n//   hold               the invoice is parked (ON_HOLD) pending investigation\n//\n// AI never calls this service: no AI agent tool reaches it, and every\n// decision is recorded against the signed-in user. The AI note on the\n// exception (ai_recommendation) is advisory input to the human only.\nvar ApExceptionDecisionService = Class.create();\n\nApExceptionDecisionService.DECISIONS = {\n    approve_override: { roles: ['x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\n    reject: { roles: ['x_695068_bcfa.ap_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\n    request_correction: { roles: ['x_695068_bcfa.ap_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\n    hold: { roles: ['x_695068_bcfa.ap_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION'] }\n};\n\nApExceptionDecisionService.MIN_REASON_CHARS = 10;\n\nApExceptionDecisionService.prototype = {\n    initialize: function() {\n        this.apService = new ApDomainService();\n        this.auditEngine = new AuditEngine();\n        this.policy = new FinancePolicy();\n    },\n\n    // Returns { ok:true, decision, invoiceState, ... } or { ok:false, error }.\n    // Every check runs before anything is written.\n    decide: function(exceptionSysId, decision, reason) {\n        var rule = ApExceptionDecisionService.DECISIONS[decision];\n        if (!rule) return this._error('Unknown decision \"' + decision + '\".');\n\n        var userId = gs.getUserID();\n        if (this._isAiIdentity(userId)) {\n            return this._error('AI identities cannot decide AP exceptions. A finance user must make this decision.');\n        }\n        if (!this._hasAnyRole(rule.roles)) {\n            return this._error('You need one of these roles to ' + decision.replace(/_/g, ' ') + ': ' + rule.roles.join(', ') + '.');\n        }\n\n        reason = reason ? String(reason).trim() : '';\n        if (reason.length < ApExceptionDecisionService.MIN_REASON_CHARS) {\n            return this._error('Enter a decision reason (at least ' + ApExceptionDecisionService.MIN_REASON_CHARS + ' characters) before choosing a decision.');\n        }\n\n        var exception = new GlideRecord('x_695068_bcfa_ap_exception');\n        if (!exception.get(exceptionSysId)) return this._error('AP exception not found.');\n        var status = exception.getValue('status');\n        if (status !== 'open' && status !== 'in_review') {\n            return this._error('This exception is already ' + status + '.');\n        }\n\n        var invoiceSysId = exception.getValue('ap_invoice');\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(invoiceSysId)) return this._error('The linked AP invoice was not found.');\n        var invoiceState = invoice.getValue('state');\n        if (rule.from.indexOf(invoiceState) < 0) {\n            return this._error('The invoice is in state ' + invoiceState + '; ' + decision.replace(/_/g, ' ') + ' is only allowed from ' + rule.from.join(' or ') + '.');\n        }\n\n        if (decision === 'approve_override') {\n            var blocked = this._overrideBlocker(exception, invoiceSysId, userId);\n            if (blocked) return this._error(blocked);\n        }\n\n        return this['_' + decision](exception, invoice, reason, userId);\n    },\n\n    _approve_override: function(exception, invoice, reason, userId) {\n        var invoiceSysId = invoice.getUniqueValue();\n        var requester = exception.getValue('assigned_to');\n        this._recordDecision(exception, 'approve_override', reason, userId, 'resolved',\n            'Override approved by ' + gs.getUserDisplayName() + ': ' + reason);\n        this.apService._setState(invoiceSysId, 'RESOLUTION', null, 'Finance approver accepted the ' + exception.getValue('reason_code') + ' variance by override');\n\n        // Maker/checker: the override is requested in the exception owner's\n        // name and approved by the current user (checked in _overrideBlocker\n        // and again by ApprovalEngine). Approval fires the posting cascade.\n        // The approval decision table routes the override (exception type\n        // and variance are inputs); an override always needs this approval.\n        var route = this.policy.apApprovalDecision({\n            amount: parseFloat(invoice.getValue('gross_amount') || '0'),\n            exceptionType: exception.getValue('reason_code'),\n            variancePct: parseFloat(exception.getValue('variance_pct') || '0'),\n            company: invoice.getValue('company_code')\n        });\n        var approval = this.apService.requestApproval(invoiceSysId, requester, route.group);\n        var result = this.apService.decideApproval(invoiceSysId, approval.approvalSysId, 'approved', userId,\n            'Tolerance override (' + exception.getValue('reason_code') + '): ' + reason);\n        if (result.error) return this._error(result.error);\n\n        var after = new GlideRecord('x_695068_bcfa_ap_invoice');\n        after.get(invoiceSysId);\n        return {\n            ok: true,\n            decision: 'approve_override',\n            approvalSysId: approval.approvalSysId,\n            invoiceState: after.getValue('state'),\n            postingState: after.getValue('posting_state'),\n            sapDocumentId: after.getValue('sap_document_id')\n        };\n    },\n\n    _reject: function(exception, invoice, reason, userId) {\n        this._recordDecision(exception, 'reject', reason, userId, 'closed', 'Invoice rejected: ' + reason);\n        this.apService._setState(invoice.getUniqueValue(), 'REJECTED', null, 'Invoice rejected on exception review: ' + reason);\n        return { ok: true, decision: 'reject', invoiceState: 'REJECTED' };\n    },\n\n    _request_correction: function(exception, invoice, reason, userId) {\n        this._recordDecision(exception, 'request_correction', reason, userId, 'in_review', null);\n        if (invoice.getValue('state') !== 'ON_HOLD') {\n            this.apService._setState(invoice.getUniqueValue(), 'ON_HOLD', null, 'Correction requested (corrected invoice or credit note): ' + reason);\n        }\n        return { ok: true, decision: 'request_correction', invoiceState: 'ON_HOLD', next: 'When the correction arrives, update the invoice and use Resolve & Retry.' };\n    },\n\n    _hold: function(exception, invoice, reason, userId) {\n        this._recordDecision(exception, 'hold', reason, userId, 'in_review', null);\n        this.apService._setState(invoice.getUniqueValue(), 'ON_HOLD', null, 'Invoice put on hold: ' + reason);\n        return { ok: true, decision: 'hold', invoiceState: 'ON_HOLD' };\n    },\n\n    _overrideBlocker: function(exception, invoiceSysId, userId) {\n        var reasonCode = exception.getValue('reason_code');\n        if (!this.policy.overrideAllowed(reasonCode)) {\n            return 'A ' + exception.getDisplayValue('reason_code') + ' exception cannot be approved by override (x_695068_bcfa.ap.override.allowed_reasons). Request a correction or reject the invoice.';\n        }\n        var requester = exception.getValue('assigned_to');\n        if (!requester) {\n            return 'This exception has no owner. Assign it to the AP processor who reviewed it; the override is requested in their name.';\n        }\n        if (requester === userId) {\n            return 'Segregation of duties: you own this exception, so a different finance approver must approve the override.';\n        }\n        var other = new GlideRecord('x_695068_bcfa_ap_exception');\n        other.addQuery('ap_invoice', invoiceSysId);\n        other.addQuery('sys_id', '!=', exception.getUniqueValue());\n        other.addQuery('status', 'IN', 'open,in_review');\n        other.setLimit(1);\n        other.query();\n        if (other.next()) {\n            return 'The invoice has another open exception (' + other.getDisplayValue('reason_code') + '). Resolve it first.';\n        }\n        return null;\n    },\n\n    _recordDecision: function(exception, decision, reason, userId, newStatus, resolutionNotes) {\n        var before = { status: exception.getValue('status'), decision: exception.getValue('decision') };\n        exception.setValue('decision', decision);\n        exception.setValue('decision_reason', reason);\n        exception.setValue('decided_by', userId);\n        exception.setValue('decided_at', new GlideDateTime().getValue());\n        exception.setValue('status', newStatus);\n        if (resolutionNotes) exception.setValue('resolution_notes', resolutionNotes);\n        exception.update();\n\n        this.auditEngine.logEvent({\n            sourceTable: 'x_695068_bcfa_ap_exception',\n            sourceRecord: exception.getUniqueValue(),\n            eventType: 'human_decision',\n            actor: userId,\n            actorType: 'user',\n            description: 'AP exception decision \"' + decision + '\" by ' + gs.getUserDisplayName() + ': ' + reason,\n            beforeValue: before,\n            afterValue: { status: newStatus, decision: decision, reason: reason }\n        });\n    },\n\n    // Defense in depth: the AI user holds ap_processor so it can read and\n    // record advisory notes, but must never make the human decision.\n    _isAiIdentity: function(userId) {\n        var user = new GlideRecord('sys_user');\n        return user.get(userId) && user.getValue('identity_type') === 'ai_agent';\n    },\n\n    _hasAnyRole: function(roles) {\n        for (var i = 0; i < roles.length; i++) {\n            if (gs.hasRole(roles[i])) return true;\n        }\n        return gs.hasRole('x_695068_bcfa.admin');\n    },\n\n    _error: function(message) {\n        return { ok: false, error: message };\n    },\n\n    type: 'ApExceptionDecisionService'\n};\n]]></script>\n    <sys_name>ApExceptionDecisionService</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_a507bd8daa9a4b8b977dc7425a6f54cc.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>a507bd8daa9a4b8b977dc7425a6f54cc</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_a507bd8daa9a4b8b977dc7425a6f54cc</sys_update_name>\n    <content><![CDATA[// Phase 12: the human decision on an AP exception. A finance user chooses\n// one of four outcomes and must give a reason:\n//   approve_override   finance approver accepts the variance; the invoice\n//                      goes through approval (maker/checker) and posts via\n//                      the approval cascade -> IntegrationService -> Mock SAP\n//   reject             the invoice is rejected and will not be paid\n//   request_correction the invoice waits (ON_HOLD) for a corrected invoice\n//                      or credit note; then \"Resolve & Retry\" re-runs it\n//   hold               the invoice is parked (ON_HOLD) pending investigation\n//\n// AI never calls this service: no AI agent tool reaches it, and every\n// decision is recorded against the signed-in user. The AI note on the\n// exception (ai_recommendation) is advisory input to the human only.\nvar ApExceptionDecisionService = Class.create();\n\nApExceptionDecisionService.DECISIONS = {\n    approve_override: { roles: ['x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\n    reject: { roles: ['x_695068_bcfa.ap_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\n    request_correction: { roles: ['x_695068_bcfa.ap_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\n    hold: { roles: ['x_695068_bcfa.ap_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION'] }\n};\n\nApExceptionDecisionService.MIN_REASON_CHARS = 10;\n\nApExceptionDecisionService.prototype = {\n    initialize: function() {\n        this.apService = new ApDomainService();\n        this.auditEngine = new AuditEngine();\n        this.policy = new FinancePolicy();\n    },\n\n    // Returns { ok:true, decision, invoiceState, ... } or { ok:false, error }.\n    // Every check runs before anything is written.\n    decide: function(exceptionSysId, decision, reason) {\n        var rule = ApExceptionDecisionService.DECISIONS[decision];\n        if (!rule) return this._error('Unknown decision \"' + decision + '\".');\n\n        var userId = gs.getUserID();\n        if (this._isAiIdentity(userId)) {\n            return this._error('AI identities cannot decide AP exceptions. A finance user must make this decision.');\n        }\n        if (!this._hasAnyRole(rule.roles)) {\n            return this._error('You need one of these roles to ' + decision.replace(/_/g, ' ') + ': ' + rule.roles.join(', ') + '.');\n        }\n\n        reason = reason ? String(reason).trim() : '';\n        if (reason.length < ApExceptionDecisionService.MIN_REASON_CHARS) {\n            return this._error('Enter a decision reason (at least ' + ApExceptionDecisionService.MIN_REASON_CHARS + ' characters) before choosing a decision.');\n        }\n\n        var exception = new GlideRecord('x_695068_bcfa_ap_exception');\n        if (!exception.get(exceptionSysId)) return this._error('AP exception not found.');\n        var status = exception.getValue('status');\n        if (status !== 'open' && status !== 'in_review') {\n            return this._error('This exception is already ' + status + '.');\n        }\n\n        var invoiceSysId = exception.getValue('ap_invoice');\n        var invoice = new GlideRecord('x_695068_bcfa_ap_invoice');\n        if (!invoice.get(invoiceSysId)) return this._error('The linked AP invoice was not found.');\n        var invoiceState = invoice.getValue('state');\n        if (rule.from.indexOf(invoiceState) < 0) {\n            return this._error('The invoice is in state ' + invoiceState + '; ' + decision.replace(/_/g, ' ') + ' is only allowed from ' + rule.from.join(' or ') + '.');\n        }\n\n        if (decision === 'approve_override') {\n            var blocked = this._overrideBlocker(exception, invoiceSysId, userId);\n            if (blocked) return this._error(blocked);\n        }\n\n        return this['_' + decision](exception, invoice, reason, userId);\n    },\n\n    _approve_override: function(exception, invoice, reason, userId) {\n        var invoiceSysId = invoice.getUniqueValue();\n        var requester = exception.getValue('assigned_to');\n        this._recordDecision(exception, 'approve_override', reason, userId, 'resolved',\n            'Override approved by ' + gs.getUserDisplayName() + ': ' + reason);\n        this.apService._setState(invoiceSysId, 'RESOLUTION', null, 'Finance approver accepted the ' + exception.getValue('reason_code') + ' variance by override');\n\n        // Maker/checker: the override is requested in the exception owner's\n        // name and approved by the current user (checked in _overrideBlocker\n        // and again by ApprovalEngine). Approval fires the posting cascade.\n        // The approval decision table routes the override (exception type\n        // and variance are inputs); an override always needs this approval.\n        var route = this.policy.apApprovalDecision({\n            amount: parseFloat(invoice.getValue('gross_amount') || '0'),\n            exceptionType: exception.getValue('reason_code'),\n            variancePct: parseFloat(exception.getValue('variance_pct') || '0'),\n            company: invoice.getValue('company_code')\n        });\n        var approval = this.apService.requestApproval(invoiceSysId, requester, route.group);\n        var result = this.apService.decideApproval(invoiceSysId, approval.approvalSysId, 'approved', userId,\n            'Tolerance override (' + exception.getValue('reason_code') + '): ' + reason);\n        if (result.error) return this._error(result.error);\n\n        var after = new GlideRecord('x_695068_bcfa_ap_invoice');\n        after.get(invoiceSysId);\n        return {\n            ok: true,\n            decision: 'approve_override',\n            approvalSysId: approval.approvalSysId,\n            invoiceState: after.getValue('state'),\n            postingState: after.getValue('posting_state'),\n            sapDocumentId: after.getValue('sap_document_id')\n        };\n    },\n\n    _reject: function(exception, invoice, reason, userId) {\n        this._recordDecision(exception, 'reject', reason, userId, 'closed', 'Invoice rejected: ' + reason);\n        this.apService._setState(invoice.getUniqueValue(), 'REJECTED', null, 'Invoice rejected on exception review: ' + reason);\n        return { ok: true, decision: 'reject', invoiceState: 'REJECTED' };\n    },\n\n    _request_correction: function(exception, invoice, reason, userId) {\n        this._recordDecision(exception, 'request_correction', reason, userId, 'in_review', null);\n        if (invoice.getValue('state') !== 'ON_HOLD') {\n            this.apService._setState(invoice.getUniqueValue(), 'ON_HOLD', null, 'Correction requested (corrected invoice or credit note): ' + reason);\n        }\n        return { ok: true, decision: 'request_correction', invoiceState: 'ON_HOLD', next: 'When the correction arrives, update the invoice and use Resolve & Retry.' };\n    },\n\n    _hold: function(exception, invoice, reason, userId) {\n        this._recordDecision(exception, 'hold', reason, userId, 'in_review', null);\n        this.apService._setState(invoice.getUniqueValue(), 'ON_HOLD', null, 'Invoice put on hold: ' + reason);\n        return { ok: true, decision: 'hold', invoiceState: 'ON_HOLD' };\n    },\n\n    _overrideBlocker: function(exception, invoiceSysId, userId) {\n        var reasonCode = exception.getValue('reason_code');\n        if (!this.policy.overrideAllowed(reasonCode)) {\n            return 'A ' + exception.getDisplayValue('reason_code') + ' exception cannot be approved by override (x_695068_bcfa.ap.override.allowed_reasons). Request a correction or reject the invoice.';\n        }\n        var requester = exception.getValue('assigned_to');\n        if (!requester) {\n            return 'This exception has no owner. Assign it to the AP processor who reviewed it; the override is requested in their name.';\n        }\n        if (requester === userId) {\n            return 'Segregation of duties: you own this exception, so a different finance approver must approve the override.';\n        }\n        var other = new GlideRecord('x_695068_bcfa_ap_exception');\n        other.addQuery('ap_invoice', invoiceSysId);\n        other.addQuery('sys_id', '!=', exception.getUniqueValue());\n        other.addQuery('status', 'IN', 'open,in_review');\n        other.setLimit(1);\n        other.query();\n        if (other.next()) {\n            return 'The invoice has another open exception (' + other.getDisplayValue('reason_code') + '). Resolve it first.';\n        }\n        return null;\n    },\n\n    _recordDecision: function(exception, decision, reason, userId, newStatus, resolutionNotes) {\n        var before = { status: exception.getValue('status'), decision: exception.getValue('decision') };\n        exception.setValue('decision', decision);\n        exception.setValue('decision_reason', reason);\n        exception.setValue('decided_by', userId);\n        exception.setValue('decided_at', new GlideDateTime().getValue());\n        exception.setValue('status', newStatus);\n        if (resolutionNotes) exception.setValue('resolution_notes', resolutionNotes);\n        exception.update();\n\n        this.auditEngine.logEvent({\n            sourceTable: 'x_695068_bcfa_ap_exception',\n            sourceRecord: exception.getUniqueValue(),\n            eventType: 'human_decision',\n            actor: userId,\n            actorType: 'user',\n            description: 'AP exception decision \"' + decision + '\" by ' + gs.getUserDisplayName() + ': ' + reason,\n            beforeValue: before,\n            afterValue: { status: newStatus, decision: decision, reason: reason }\n        });\n    },\n\n    // Defense in depth: the AI user holds ap_processor so it can read and\n    // record advisory notes, but must never make the human decision.\n    _isAiIdentity: function(userId) {\n        var user = new GlideRecord('sys_user');\n        return user.get(userId) && user.getValue('identity_type') === 'ai_agent';\n    },\n\n    _hasAnyRole: function(roles) {\n        for (var i = 0; i < roles.length; i++) {\n            if (gs.hasRole(roles[i])) return true;\n        }\n        return gs.hasRole('x_695068_bcfa.admin');\n    },\n\n    _error: function(message) {\n        return { ok: false, error: message };\n    },\n\n    type: 'ApExceptionDecisionService'\n};\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ApExceptionDecisionService.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ApExceptionDecisionService.server.js</sys_name>\n  </sys_module>\n</record_update>"},{"name":"sys_script_include_8ae1cfe2ab8e4d338a3b2c58faff9bec.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_script_include\">\n  <sys_script_include action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>8ae1cfe2ab8e4d338a3b2c58faff9bec</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_script_include_8ae1cfe2ab8e4d338a3b2c58faff9bec</sys_update_name>\n    <access>package_private</access>\n    <active>true</active>\n    <api_name>x_695068_bcfa.ArExceptionDecisionService</api_name>\n    <caller_access/>\n    <client_callable>false</client_callable>\n    <description>Records the human decision on an AR exception (approve deduction, request clarification, hold) with a mandatory reason and role checks. An approved deduction is the computed residual; the balance is re-checked, then the payment goes to a different approver and clears via Mock SAP. Never callable by AI.</description>\n    <mobile_callable>false</mobile_callable>\n    <name>ArExceptionDecisionService</name>\n    <sandbox_callable>false</sandbox_callable>\n    <script><![CDATA[// Phase 13: the human decision on an AR (cash application) exception. The\r\n// reviewer chooses one of three outcomes and must give a reason:\r\n//   approve_deduction      accept the short-pay residual as a deduction of\r\n//                          the type chosen on the exception (e.g. BANK_CHARGE).\r\n//                          The amount is the residual the deterministic\r\n//                          balance check computed, never a typed number. A\r\n//                          Deduction record is created, the balance is\r\n//                          re-checked (allocation - approved deductions =\r\n//                          payment), and the payment goes for approval by a\r\n//                          different user, then clearing via Mock SAP.\r\n//   request_clarification  the payment waits (ON_HOLD) for the customer\r\n//   hold                   the payment is parked (ON_HOLD)\r\n//\r\n// AI never calls this service: no agent tool reaches it, AI identities are\r\n// refused, and every decision is recorded against the signed-in user. The\r\n// AI note on the exception is advisory input to the human only.\r\nvar ArExceptionDecisionService = Class.create();\r\n\r\nArExceptionDecisionService.DECISIONS = {\r\n    approve_deduction: { roles: ['x_695068_bcfa.ar_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\r\n    request_clarification: { roles: ['x_695068_bcfa.ar_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\r\n    hold: { roles: ['x_695068_bcfa.ar_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION'] }\r\n};\r\n\r\nArExceptionDecisionService.MIN_REASON_CHARS = 10;\r\n\r\nArExceptionDecisionService.prototype = {\r\n    initialize: function() {\r\n        this.arService = new ArDomainService();\r\n        this.auditEngine = new AuditEngine();\r\n        this.policy = new FinancePolicy();\r\n    },\r\n\r\n    // Returns { ok:true, decision, paymentState, ... } or { ok:false, error }.\r\n    // Every check runs before anything is written.\r\n    decide: function(exceptionSysId, decision, reason) {\r\n        var rule = ArExceptionDecisionService.DECISIONS[decision];\r\n        if (!rule) return this._error('Unknown decision \"' + decision + '\".');\r\n\r\n        var userId = gs.getUserID();\r\n        if (this._isAiIdentity(userId)) {\r\n            return this._error('AI identities cannot decide AR exceptions. A finance user must make this decision.');\r\n        }\r\n        if (!this._hasAnyRole(rule.roles)) {\r\n            return this._error('You need one of these roles to ' + decision.replace(/_/g, ' ') + ': ' + rule.roles.join(', ') + '.');\r\n        }\r\n\r\n        reason = reason ? String(reason).trim() : '';\r\n        if (reason.length < ArExceptionDecisionService.MIN_REASON_CHARS) {\r\n            return this._error('Enter a decision reason (at least ' + ArExceptionDecisionService.MIN_REASON_CHARS + ' characters) before choosing a decision.');\r\n        }\r\n\r\n        var exception = new GlideRecord('x_695068_bcfa_ar_exception');\r\n        if (!exception.get(exceptionSysId)) return this._error('AR exception not found.');\r\n        var status = exception.getValue('status');\r\n        if (status !== 'open' && status !== 'in_review') return this._error('This exception is already ' + status + '.');\r\n\r\n        var payment = new GlideRecord('x_695068_bcfa_payment');\r\n        if (!payment.get(exception.getValue('payment'))) return this._error('The linked payment was not found.');\r\n        if (rule.from.indexOf(payment.getValue('state')) < 0) {\r\n            return this._error('The payment is in state ' + payment.getValue('state') + '; ' + decision.replace(/_/g, ' ') + ' is only allowed from ' + rule.from.join(' or ') + '.');\r\n        }\r\n\r\n        return this['_' + decision](exception, payment, reason, userId);\r\n    },\r\n\r\n    _approve_deduction: function(exception, payment, reason, userId) {\r\n        if (exception.getValue('reason_code') !== 'short_pay') {\r\n            return this._error('Only a short payment can be balanced with a deduction; this exception is ' + exception.getDisplayValue('reason_code') + '.');\r\n        }\r\n        var type = exception.getValue('deduction_type');\r\n        if (!type) return this._error('Choose the Deduction Type on the exception (for example Bank Charge) before approving the deduction.');\r\n\r\n        var balance = this._balance(payment);\r\n        if (balance.allocations.length === 0) return this._error('The payment has no allocations to attach a deduction to.');\r\n        var amount = balance.residual;\r\n        if (amount <= this.arService.BALANCE_TOLERANCE) {\r\n            return this._error('There is no short-pay residual left to deduct (allocated ' + balance.allocated + ', approved deductions ' + balance.deductions + ', payment ' + balance.payment + ').');\r\n        }\r\n        // Credit-note netting (Phase 14): the credit note chosen on the\r\n        // exception must be open, belong to the payment's customer and equal\r\n        // the residual exactly.\r\n        var creditNoteSysId = null;\r\n        if (type === 'credit_note_netting') {\r\n            creditNoteSysId = exception.getValue('credit_note');\r\n            var note = new GlideRecord('x_695068_bcfa_credit_note');\r\n            if (!creditNoteSysId || !note.get(creditNoteSysId)) return this._error('Choose the Credit Note on the exception before netting.');\r\n            if (note.getValue('status') !== 'open') return this._error('Credit note ' + note.getValue('credit_note_number') + ' is ' + note.getValue('status') + ', not open.');\r\n            if (note.getValue('customer') !== payment.getValue('customer')) return this._error('Credit note ' + note.getValue('credit_note_number') + ' belongs to another customer.');\r\n            var noteOpen = parseFloat(note.getValue('open_amount') || '0');\r\n            if (Math.abs(noteOpen - amount) > this.arService.BALANCE_TOLERANCE) {\r\n                return this._error('Credit note ' + note.getValue('credit_note_number') + ' has ' + noteOpen + ' open, but the residual is ' + amount + '; netting must match exactly.');\r\n            }\r\n        }\r\n\r\n        // Phase 15: the BCFA AR Deduction decision table (type, amount,\r\n        // company) says whether this deduction is allowed and whether it\r\n        // needs a finance approver (properties are the fallback).\r\n        var policyDecision = this.policy.arDeductionDecision({\r\n            deductionType: type, amount: amount, company: payment.customer.company_code.toString()\r\n        });\r\n        if (!policyDecision.allowed) {\r\n            return this._error('Deduction type ' + exception.getDisplayValue('deduction_type') + ' of ' + amount + ' is not allowed. ' + policyDecision.rule);\r\n        }\r\n        if (policyDecision.approvalRequired && !gs.hasRole('x_695068_bcfa.finance_approver') && !gs.hasRole('x_695068_bcfa.admin')) {\r\n            return this._error('This deduction needs a finance approver. ' + policyDecision.rule);\r\n        }\r\n\r\n        // Attach to the allocation the remittance short-paid, else the last.\r\n        var target = balance.allocations[balance.allocations.length - 1];\r\n        var remittance = new MatchingEngine().resolveRemittanceReferences(payment.getUniqueValue());\r\n        if (remittance.available) {\r\n            for (var i = 0; i < remittance.items.length; i++) {\r\n                var ref = remittance.items[i];\r\n                if (ref.applied !== null && ref.applied < ref.openAmount - this.arService.BALANCE_TOLERANCE) {\r\n                    for (var a = 0; a < balance.allocations.length; a++) {\r\n                        if (balance.allocations[a].item === ref.sysId) target = balance.allocations[a];\r\n                    }\r\n                }\r\n            }\r\n        }\r\n\r\n        var deduction = new GlideRecord('x_695068_bcfa_deduction');\r\n        deduction.initialize();\r\n        deduction.setValue('payment_allocation', target.sysId);\r\n        deduction.setValue('deduction_type', type);\r\n        deduction.setValue('amount', amount);\r\n        deduction.setValue('status', 'approved');\r\n        deduction.setValue('approved_by', userId);\r\n        deduction.setValue('approved_at', new GlideDateTime().getValue());\r\n        deduction.setValue('notes', reason);\r\n        if (creditNoteSysId) deduction.setValue('credit_note', creditNoteSysId);\r\n        var deductionSysId = deduction.insert();\r\n\r\n        var allocation = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n        if (allocation.get(target.sysId) && (type === 'bank_charge' || type === 'tcs')) {\r\n            allocation.setValue(type, amount);\r\n            allocation.update();\r\n        }\r\n\r\n        this._recordDecision(exception, 'approve_deduction', reason, userId, 'resolved',\r\n            'Deduction ' + type + ' ' + amount + ' approved by ' + gs.getUserDisplayName() + ': ' + reason + ' [' + policyDecision.rule + ']');\r\n\r\n        // Deterministic re-check: allocation - approved deductions = payment.\r\n        var advance = this.arService.advanceAfterDeduction(payment.getUniqueValue());\r\n        if (!advance.balanced) {\r\n            return this._error('The deduction was recorded but the payment still does not balance (difference ' + advance.difference + '). It stays in exception.');\r\n        }\r\n        var approval = this.arService.routeForApproval(payment.getUniqueValue(), userId);\r\n        var after = new GlideRecord('x_695068_bcfa_payment');\r\n        after.get(payment.getUniqueValue());\r\n        return {\r\n            ok: true,\r\n            decision: 'approve_deduction',\r\n            deductionSysId: deductionSysId,\r\n            deductionType: type,\r\n            policy: policyDecision.source,\r\n            amount: amount,\r\n            netAllocated: advance.netAllocated,\r\n            approvalRequired: approval.approvalRequired,\r\n            approvalSysId: approval.approvalSysId,\r\n            paymentState: after.getValue('state')\r\n        };\r\n    },\r\n\r\n    _request_clarification: function(exception, payment, reason, userId) {\r\n        this._recordDecision(exception, 'request_clarification', reason, userId, 'in_review', null);\r\n        if (payment.getValue('state') !== 'ON_HOLD') {\r\n            this.arService._setState(payment.getUniqueValue(), 'ON_HOLD', null, 'Customer clarification requested: ' + reason);\r\n        }\r\n        return { ok: true, decision: 'request_clarification', paymentState: 'ON_HOLD', next: 'When the customer replies, correct the data and use Resolve & Retry, or approve a deduction.' };\r\n    },\r\n\r\n    _hold: function(exception, payment, reason, userId) {\r\n        this._recordDecision(exception, 'hold', reason, userId, 'in_review', null);\r\n        this.arService._setState(payment.getUniqueValue(), 'ON_HOLD', null, 'Payment put on hold: ' + reason);\r\n        return { ok: true, decision: 'hold', paymentState: 'ON_HOLD' };\r\n    },\r\n\r\n    _balance: function(payment) {\r\n        var result = { payment: parseFloat(payment.getValue('amount') || '0'), allocated: 0, deductions: 0, allocations: [] };\r\n        var allocation = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n        allocation.addQuery('payment', payment.getUniqueValue());\r\n        allocation.addQuery('allocation_state', '!=', 'reversed');\r\n        allocation.orderBy('sys_created_on');\r\n        allocation.query();\r\n        while (allocation.next()) {\r\n            result.allocated += parseFloat(allocation.getValue('allocated_amount') || '0');\r\n            result.allocations.push({ sysId: allocation.getUniqueValue(), item: allocation.getValue('ar_open_item') });\r\n            var deduction = new GlideRecord('x_695068_bcfa_deduction');\r\n            deduction.addQuery('payment_allocation', allocation.getUniqueValue());\r\n            deduction.addQuery('status', 'approved');\r\n            deduction.query();\r\n            while (deduction.next()) result.deductions += parseFloat(deduction.getValue('amount') || '0');\r\n        }\r\n        result.allocated = Math.round(result.allocated * 100) / 100;\r\n        result.deductions = Math.round(result.deductions * 100) / 100;\r\n        result.residual = Math.round((result.allocated - result.deductions - result.payment) * 100) / 100;\r\n        return result;\r\n    },\r\n\r\n    _recordDecision: function(exception, decision, reason, userId, newStatus, resolutionNotes) {\r\n        var before = { status: exception.getValue('status'), decision: exception.getValue('decision') };\r\n        exception.setValue('decision', decision);\r\n        exception.setValue('decision_reason', reason);\r\n        exception.setValue('decided_by', userId);\r\n        exception.setValue('decided_at', new GlideDateTime().getValue());\r\n        exception.setValue('status', newStatus);\r\n        if (resolutionNotes) exception.setValue('resolution_notes', resolutionNotes);\r\n        exception.update();\r\n\r\n        this.auditEngine.logEvent({\r\n            sourceTable: 'x_695068_bcfa_ar_exception',\r\n            sourceRecord: exception.getUniqueValue(),\r\n            eventType: 'human_decision',\r\n            actor: userId,\r\n            actorType: 'user',\r\n            description: 'AR exception decision \"' + decision + '\" by ' + gs.getUserDisplayName() + ': ' + reason,\r\n            beforeValue: before,\r\n            afterValue: { status: newStatus, decision: decision, reason: reason, deduction_type: exception.getValue('deduction_type') }\r\n        });\r\n    },\r\n\r\n    _isAiIdentity: function(userId) {\r\n        var user = new GlideRecord('sys_user');\r\n        return user.get(userId) && user.getValue('identity_type') === 'ai_agent';\r\n    },\r\n\r\n    _hasAnyRole: function(roles) {\r\n        for (var i = 0; i < roles.length; i++) {\r\n            if (gs.hasRole(roles[i])) return true;\r\n        }\r\n        return gs.hasRole('x_695068_bcfa.admin');\r\n    },\r\n\r\n    _error: function(message) {\r\n        return { ok: false, error: message };\r\n    },\r\n\r\n    type: 'ArExceptionDecisionService'\r\n};\r\n]]></script>\n    <sys_name>ArExceptionDecisionService</sys_name>\n  </sys_script_include>\n</record_update>"},{"name":"sys_module_88dee0d1c1ff4aee9eede52722d68648.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_module\">\n  <sys_module action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>88dee0d1c1ff4aee9eede52722d68648</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_module_88dee0d1c1ff4aee9eede52722d68648</sys_update_name>\n    <content><![CDATA[// Phase 13: the human decision on an AR (cash application) exception. The\r\n// reviewer chooses one of three outcomes and must give a reason:\r\n//   approve_deduction      accept the short-pay residual as a deduction of\r\n//                          the type chosen on the exception (e.g. BANK_CHARGE).\r\n//                          The amount is the residual the deterministic\r\n//                          balance check computed, never a typed number. A\r\n//                          Deduction record is created, the balance is\r\n//                          re-checked (allocation - approved deductions =\r\n//                          payment), and the payment goes for approval by a\r\n//                          different user, then clearing via Mock SAP.\r\n//   request_clarification  the payment waits (ON_HOLD) for the customer\r\n//   hold                   the payment is parked (ON_HOLD)\r\n//\r\n// AI never calls this service: no agent tool reaches it, AI identities are\r\n// refused, and every decision is recorded against the signed-in user. The\r\n// AI note on the exception is advisory input to the human only.\r\nvar ArExceptionDecisionService = Class.create();\r\n\r\nArExceptionDecisionService.DECISIONS = {\r\n    approve_deduction: { roles: ['x_695068_bcfa.ar_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\r\n    request_clarification: { roles: ['x_695068_bcfa.ar_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION', 'ON_HOLD'] },\r\n    hold: { roles: ['x_695068_bcfa.ar_processor', 'x_695068_bcfa.finance_approver'], from: ['EXCEPTION'] }\r\n};\r\n\r\nArExceptionDecisionService.MIN_REASON_CHARS = 10;\r\n\r\nArExceptionDecisionService.prototype = {\r\n    initialize: function() {\r\n        this.arService = new ArDomainService();\r\n        this.auditEngine = new AuditEngine();\r\n        this.policy = new FinancePolicy();\r\n    },\r\n\r\n    // Returns { ok:true, decision, paymentState, ... } or { ok:false, error }.\r\n    // Every check runs before anything is written.\r\n    decide: function(exceptionSysId, decision, reason) {\r\n        var rule = ArExceptionDecisionService.DECISIONS[decision];\r\n        if (!rule) return this._error('Unknown decision \"' + decision + '\".');\r\n\r\n        var userId = gs.getUserID();\r\n        if (this._isAiIdentity(userId)) {\r\n            return this._error('AI identities cannot decide AR exceptions. A finance user must make this decision.');\r\n        }\r\n        if (!this._hasAnyRole(rule.roles)) {\r\n            return this._error('You need one of these roles to ' + decision.replace(/_/g, ' ') + ': ' + rule.roles.join(', ') + '.');\r\n        }\r\n\r\n        reason = reason ? String(reason).trim() : '';\r\n        if (reason.length < ArExceptionDecisionService.MIN_REASON_CHARS) {\r\n            return this._error('Enter a decision reason (at least ' + ArExceptionDecisionService.MIN_REASON_CHARS + ' characters) before choosing a decision.');\r\n        }\r\n\r\n        var exception = new GlideRecord('x_695068_bcfa_ar_exception');\r\n        if (!exception.get(exceptionSysId)) return this._error('AR exception not found.');\r\n        var status = exception.getValue('status');\r\n        if (status !== 'open' && status !== 'in_review') return this._error('This exception is already ' + status + '.');\r\n\r\n        var payment = new GlideRecord('x_695068_bcfa_payment');\r\n        if (!payment.get(exception.getValue('payment'))) return this._error('The linked payment was not found.');\r\n        if (rule.from.indexOf(payment.getValue('state')) < 0) {\r\n            return this._error('The payment is in state ' + payment.getValue('state') + '; ' + decision.replace(/_/g, ' ') + ' is only allowed from ' + rule.from.join(' or ') + '.');\r\n        }\r\n\r\n        return this['_' + decision](exception, payment, reason, userId);\r\n    },\r\n\r\n    _approve_deduction: function(exception, payment, reason, userId) {\r\n        if (exception.getValue('reason_code') !== 'short_pay') {\r\n            return this._error('Only a short payment can be balanced with a deduction; this exception is ' + exception.getDisplayValue('reason_code') + '.');\r\n        }\r\n        var type = exception.getValue('deduction_type');\r\n        if (!type) return this._error('Choose the Deduction Type on the exception (for example Bank Charge) before approving the deduction.');\r\n\r\n        var balance = this._balance(payment);\r\n        if (balance.allocations.length === 0) return this._error('The payment has no allocations to attach a deduction to.');\r\n        var amount = balance.residual;\r\n        if (amount <= this.arService.BALANCE_TOLERANCE) {\r\n            return this._error('There is no short-pay residual left to deduct (allocated ' + balance.allocated + ', approved deductions ' + balance.deductions + ', payment ' + balance.payment + ').');\r\n        }\r\n        // Credit-note netting (Phase 14): the credit note chosen on the\r\n        // exception must be open, belong to the payment's customer and equal\r\n        // the residual exactly.\r\n        var creditNoteSysId = null;\r\n        if (type === 'credit_note_netting') {\r\n            creditNoteSysId = exception.getValue('credit_note');\r\n            var note = new GlideRecord('x_695068_bcfa_credit_note');\r\n            if (!creditNoteSysId || !note.get(creditNoteSysId)) return this._error('Choose the Credit Note on the exception before netting.');\r\n            if (note.getValue('status') !== 'open') return this._error('Credit note ' + note.getValue('credit_note_number') + ' is ' + note.getValue('status') + ', not open.');\r\n            if (note.getValue('customer') !== payment.getValue('customer')) return this._error('Credit note ' + note.getValue('credit_note_number') + ' belongs to another customer.');\r\n            var noteOpen = parseFloat(note.getValue('open_amount') || '0');\r\n            if (Math.abs(noteOpen - amount) > this.arService.BALANCE_TOLERANCE) {\r\n                return this._error('Credit note ' + note.getValue('credit_note_number') + ' has ' + noteOpen + ' open, but the residual is ' + amount + '; netting must match exactly.');\r\n            }\r\n        }\r\n\r\n        // Phase 15: the BCFA AR Deduction decision table (type, amount,\r\n        // company) says whether this deduction is allowed and whether it\r\n        // needs a finance approver (properties are the fallback).\r\n        var policyDecision = this.policy.arDeductionDecision({\r\n            deductionType: type, amount: amount, company: payment.customer.company_code.toString()\r\n        });\r\n        if (!policyDecision.allowed) {\r\n            return this._error('Deduction type ' + exception.getDisplayValue('deduction_type') + ' of ' + amount + ' is not allowed. ' + policyDecision.rule);\r\n        }\r\n        if (policyDecision.approvalRequired && !gs.hasRole('x_695068_bcfa.finance_approver') && !gs.hasRole('x_695068_bcfa.admin')) {\r\n            return this._error('This deduction needs a finance approver. ' + policyDecision.rule);\r\n        }\r\n\r\n        // Attach to the allocation the remittance short-paid, else the last.\r\n        var target = balance.allocations[balance.allocations.length - 1];\r\n        var remittance = new MatchingEngine().resolveRemittanceReferences(payment.getUniqueValue());\r\n        if (remittance.available) {\r\n            for (var i = 0; i < remittance.items.length; i++) {\r\n                var ref = remittance.items[i];\r\n                if (ref.applied !== null && ref.applied < ref.openAmount - this.arService.BALANCE_TOLERANCE) {\r\n                    for (var a = 0; a < balance.allocations.length; a++) {\r\n                        if (balance.allocations[a].item === ref.sysId) target = balance.allocations[a];\r\n                    }\r\n                }\r\n            }\r\n        }\r\n\r\n        var deduction = new GlideRecord('x_695068_bcfa_deduction');\r\n        deduction.initialize();\r\n        deduction.setValue('payment_allocation', target.sysId);\r\n        deduction.setValue('deduction_type', type);\r\n        deduction.setValue('amount', amount);\r\n        deduction.setValue('status', 'approved');\r\n        deduction.setValue('approved_by', userId);\r\n        deduction.setValue('approved_at', new GlideDateTime().getValue());\r\n        deduction.setValue('notes', reason);\r\n        if (creditNoteSysId) deduction.setValue('credit_note', creditNoteSysId);\r\n        var deductionSysId = deduction.insert();\r\n\r\n        var allocation = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n        if (allocation.get(target.sysId) && (type === 'bank_charge' || type === 'tcs')) {\r\n            allocation.setValue(type, amount);\r\n            allocation.update();\r\n        }\r\n\r\n        this._recordDecision(exception, 'approve_deduction', reason, userId, 'resolved',\r\n            'Deduction ' + type + ' ' + amount + ' approved by ' + gs.getUserDisplayName() + ': ' + reason + ' [' + policyDecision.rule + ']');\r\n\r\n        // Deterministic re-check: allocation - approved deductions = payment.\r\n        var advance = this.arService.advanceAfterDeduction(payment.getUniqueValue());\r\n        if (!advance.balanced) {\r\n            return this._error('The deduction was recorded but the payment still does not balance (difference ' + advance.difference + '). It stays in exception.');\r\n        }\r\n        var approval = this.arService.routeForApproval(payment.getUniqueValue(), userId);\r\n        var after = new GlideRecord('x_695068_bcfa_payment');\r\n        after.get(payment.getUniqueValue());\r\n        return {\r\n            ok: true,\r\n            decision: 'approve_deduction',\r\n            deductionSysId: deductionSysId,\r\n            deductionType: type,\r\n            policy: policyDecision.source,\r\n            amount: amount,\r\n            netAllocated: advance.netAllocated,\r\n            approvalRequired: approval.approvalRequired,\r\n            approvalSysId: approval.approvalSysId,\r\n            paymentState: after.getValue('state')\r\n        };\r\n    },\r\n\r\n    _request_clarification: function(exception, payment, reason, userId) {\r\n        this._recordDecision(exception, 'request_clarification', reason, userId, 'in_review', null);\r\n        if (payment.getValue('state') !== 'ON_HOLD') {\r\n            this.arService._setState(payment.getUniqueValue(), 'ON_HOLD', null, 'Customer clarification requested: ' + reason);\r\n        }\r\n        return { ok: true, decision: 'request_clarification', paymentState: 'ON_HOLD', next: 'When the customer replies, correct the data and use Resolve & Retry, or approve a deduction.' };\r\n    },\r\n\r\n    _hold: function(exception, payment, reason, userId) {\r\n        this._recordDecision(exception, 'hold', reason, userId, 'in_review', null);\r\n        this.arService._setState(payment.getUniqueValue(), 'ON_HOLD', null, 'Payment put on hold: ' + reason);\r\n        return { ok: true, decision: 'hold', paymentState: 'ON_HOLD' };\r\n    },\r\n\r\n    _balance: function(payment) {\r\n        var result = { payment: parseFloat(payment.getValue('amount') || '0'), allocated: 0, deductions: 0, allocations: [] };\r\n        var allocation = new GlideRecord('x_695068_bcfa_payment_allocation');\r\n        allocation.addQuery('payment', payment.getUniqueValue());\r\n        allocation.addQuery('allocation_state', '!=', 'reversed');\r\n        allocation.orderBy('sys_created_on');\r\n        allocation.query();\r\n        while (allocation.next()) {\r\n            result.allocated += parseFloat(allocation.getValue('allocated_amount') || '0');\r\n            result.allocations.push({ sysId: allocation.getUniqueValue(), item: allocation.getValue('ar_open_item') });\r\n            var deduction = new GlideRecord('x_695068_bcfa_deduction');\r\n            deduction.addQuery('payment_allocation', allocation.getUniqueValue());\r\n            deduction.addQuery('status', 'approved');\r\n            deduction.query();\r\n            while (deduction.next()) result.deductions += parseFloat(deduction.getValue('amount') || '0');\r\n        }\r\n        result.allocated = Math.round(result.allocated * 100) / 100;\r\n        result.deductions = Math.round(result.deductions * 100) / 100;\r\n        result.residual = Math.round((result.allocated - result.deductions - result.payment) * 100) / 100;\r\n        return result;\r\n    },\r\n\r\n    _recordDecision: function(exception, decision, reason, userId, newStatus, resolutionNotes) {\r\n        var before = { status: exception.getValue('status'), decision: exception.getValue('decision') };\r\n        exception.setValue('decision', decision);\r\n        exception.setValue('decision_reason', reason);\r\n        exception.setValue('decided_by', userId);\r\n        exception.setValue('decided_at', new GlideDateTime().getValue());\r\n        exception.setValue('status', newStatus);\r\n        if (resolutionNotes) exception.setValue('resolution_notes', resolutionNotes);\r\n        exception.update();\r\n\r\n        this.auditEngine.logEvent({\r\n            sourceTable: 'x_695068_bcfa_ar_exception',\r\n            sourceRecord: exception.getUniqueValue(),\r\n            eventType: 'human_decision',\r\n            actor: userId,\r\n            actorType: 'user',\r\n            description: 'AR exception decision \"' + decision + '\" by ' + gs.getUserDisplayName() + ': ' + reason,\r\n            beforeValue: before,\r\n            afterValue: { status: newStatus, decision: decision, reason: reason, deduction_type: exception.getValue('deduction_type') }\r\n        });\r\n    },\r\n\r\n    _isAiIdentity: function(userId) {\r\n        var user = new GlideRecord('sys_user');\r\n        return user.get(userId) && user.getValue('identity_type') === 'ai_agent';\r\n    },\r\n\r\n    _hasAnyRole: function(roles) {\r\n        for (var i = 0; i < roles.length; i++) {\r\n            if (gs.hasRole(roles[i])) return true;\r\n        }\r\n        return gs.hasRole('x_695068_bcfa.admin');\r\n    },\r\n\r\n    _error: function(message) {\r\n        return { ok: false, error: message };\r\n    },\r\n\r\n    type: 'ArExceptionDecisionService'\r\n};\r\n]]></content>\n    <external_source>false</external_source>\n    <path>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ArExceptionDecisionService.server.js</path>\n    <sys_name>x_695068_bcfa/birla-carbon-finance-automation/0.0.1/src/server/script-includes/ArExceptionDecisionService.server.js</sys_name>\n  </sys_module>\n</record_update>"}];
var columns = [{"sysId":"6f2f0a75a8ed479183ef036ae1e06ba0","table":"x_695068_bcfa_ap_approval","element":"approval_group","fields":{"sys_scope":"229ba2b1a079431e104010f5ea883e85","active":"true","array":"false","audit":"false","column_label":"Approval Group","display":"false","element":"approval_group","element_reference":"false","function_field":"false","internal_type":"reference","mandatory":"false","name":"x_695068_bcfa_ap_approval","primary":"false","read_only":"true","read_only_option":"instance_configured","reference":"sys_user_group","spell_check":"false","table_reference":"false","text_index":"false","unique":"false","use_dependent_field":"false","use_reference_qualifier":"simple","virtual_type":"script","xml_view":"false"}}];
var docs = [{"name":"sys_documentation_x_695068_bcfa_ap_approval_approval_group_en.xml","xml":"<?xml version=\"1.0\"?>\n<record_update table=\"sys_documentation\">\n  <sys_documentation action=\"INSERT_OR_UPDATE\" apply_defaults=\"true\">\n    <sys_id>9dadf8b1af244d048a9b35496d24b4fb</sys_id>\n    <sys_scope display_value=\"x_695068_bcfa\">229ba2b1a079431e104010f5ea883e85</sys_scope>\n    <sys_update_name>sys_documentation_x_695068_bcfa_ap_approval_approval_group_en</sys_update_name>\n    <element>approval_group</element>\n    <help/>\n    <hint>Group the BCFA AP Approval decision table routed this approval to (Phase 15). Membership is enforced from Phase 17.</hint>\n    <label>Approval Group</label>\n    <language>en</language>\n    <name>x_695068_bcfa_ap_approval</name>\n    <plural>Approval Groups</plural>\n    <url/>\n    <url_target/>\n  </sys_documentation>\n</record_update>"}];
var out = [];
if (gs.getCurrentScopeName() !== 'rhino.global') {
  gs.info('BCFA_DEPLOY ABORTED: run in scope "global", current scope is ' + gs.getCurrentScopeName());
} else {
  var demo = {"groups":[{"sysId":"6c3107e75eeec3146f95ff49b9011def","name":"BCFA AP Operations","description":"Demo group: AP processors who own AP exceptions (POC)."},{"sysId":"e34ee8a159fd504893d4fc248a6632a7","name":"BCFA Finance Approvers","description":"Demo group: finance approvers for AP posting and overrides (POC)."},{"sysId":"a42557739c621c40c2570c9fa414cc46","name":"BCFA Cash Application","description":"Demo group: AR processors who own cash application exceptions (POC)."},{"sysId":"f1c12aaee7e9ac7e31fc871b0eca266b","name":"BCFA Finance Controllers","description":"Demo group: approves high-value invoices and overrides above 10% variance (POC decision table routing)."}],"users":[{"sysId":"6fe2fbfa188d7aa5829b61d52b3202c9","userName":"bcfa.ap.processor","first":"BCFA Demo","last":"AP Processor","role":"x_695068_bcfa.ap_processor","group":"6c3107e75eeec3146f95ff49b9011def"},{"sysId":"d33f6290d7533660937e25a599602b2c","userName":"bcfa.finance.approver","first":"BCFA Demo","last":"Finance Approver","role":"x_695068_bcfa.finance_approver","group":"e34ee8a159fd504893d4fc248a6632a7"},{"sysId":"a9f827de8d254b4150e07ac76dd9cef6","userName":"bcfa.ar.processor","first":"BCFA Demo","last":"AR Processor","role":"x_695068_bcfa.ar_processor","group":"a42557739c621c40c2570c9fa414cc46"}]};
  demo.groups.forEach(function(g) {
    var grp = new GlideRecord('sys_user_group');
    var exists = grp.get(g.sysId);
    if (!exists) { grp.initialize(); grp.setNewGuidValue(g.sysId); }
    grp.setValue('name', g.name);
    grp.setValue('description', g.description);
    grp.setValue('active', true);
    exists ? grp.update() : grp.insert();
  });
  demo.users.forEach(function(u) {
    var user = new GlideRecord('sys_user');
    var exists = user.get(u.sysId);
    if (!exists) { user.initialize(); user.setNewGuidValue(u.sysId); }
    user.setValue('user_name', u.userName);
    user.setValue('first_name', u.first);
    user.setValue('last_name', u.last);
    user.setValue('active', true);
    exists ? user.update() : user.insert();
    var role = new GlideRecord('sys_user_role');
    if (!role.get('name', u.role)) { out.push('ROLE MISSING ' + u.role); return; }
    var grant = new GlideRecord('sys_user_has_role');
    grant.addQuery('user', u.sysId);
    grant.addQuery('role', role.getUniqueValue());
    grant.query();
    if (!grant.hasNext()) { grant.initialize(); grant.setValue('user', u.sysId); grant.setValue('role', role.getUniqueValue()); grant.insert(); }
    var member = new GlideRecord('sys_user_grmember');
    member.addQuery('user', u.sysId);
    member.addQuery('group', u.group);
    member.query();
    if (!member.hasNext()) { member.initialize(); member.setValue('user', u.sysId); member.setValue('group', u.group); member.insert(); }
  });
  out.push('demo users: ' + demo.users.map(function(u) {
    return u.userName + ' ' + u.role.split('.')[1] + '=' + gs.getUser().getUserByID(u.sysId).hasRole(u.role);
  }).join(', '));

  var gum = new GlideUpdateManager2();
  var added = 0, present = 0, colFailed = [];
  // Columns first, so choice sets and UI that reference them load cleanly.
  columns.forEach(function(c) {
    if (new GlideRecord(c.table).isValidField(c.element)) { present++; return; }
    var d = new GlideRecord('sys_dictionary');
    d.initialize();
    d.setNewGuidValue(c.sysId);
    for (var k in c.fields) d.setValue(k, c.fields[k]);
    d.setValue('sys_package', '229ba2b1a079431e104010f5ea883e85');
    d.insert();
    if (new GlideRecord(c.table).isValidField(c.element)) added++; else colFailed.push(c.element);
  });
  // Column labels with their build sys_ids; drop the duplicate label the
  // dictionary insert created.
  var docOk = 0;
  docs.forEach(function(f) {
    try { gum.loadXML(f.xml); docOk++; } catch (e) { out.push('FAILED ' + f.name + ': ' + e); }
    var id = (f.xml.match(/<sys_id>([0-9a-f]{32})<\/sys_id>/) || [])[1];
    var el = (f.xml.match(/<element>([^<]*)<\/element>/) || [])[1];
    var tbl = (f.xml.match(/<name>([^<]*)<\/name>/) || [])[1];
    var extra = new GlideRecord('sys_documentation');
    extra.addQuery('name', tbl);
    extra.addQuery('element', el);
    extra.addQuery('language', 'en');
    extra.addQuery('sys_id', '!=', id);
    extra.query();
    while (extra.next()) extra.deleteRecord();
  });
  var ok = 0, failed = 0;
  files.forEach(function(f) {
    try { gum.loadXML(f.xml); ok++; }
    catch (e) { failed++; out.push('FAILED ' + f.name + ': ' + e); }
  });
  out.unshift('columns added=' + added + ' already present=' + present + (colFailed.length ? ' NOT CREATED: ' + colFailed.join(',') : '') +
    ' | labels=' + docOk + ' | records loaded=' + ok + ' failed=' + failed + ' of ' + files.length);
}
gs.info('BCFA_DEPLOY ' + out.join(' | '));
